  CONSTRAINT urun_aday_gorsel_tur_check CHECK ((tur = ANY (ARRAY['URUN'::text, 'CINCE_BILGI'::text, 'INFO_TR'::text, 'PAKET'::text]))),
  CONSTRAINT urun_aday_gorsel_pkey PRIMARY KEY (id)
);

