CREATE OR REPLACE FUNCTION public.cfo_ay_kazanan_yaz(p_ay date, p_maliyet_kaynagi text DEFAULT 'donem sonu unitCostTry'::text)
 RETURNS TABLE(yazilan integer, ay_toplam_kar numeric, kapsam_pct numeric)
 LANGUAGE plpgsql
AS $function$
declare v_ay date := date_trunc('month', p_ay)::date;
        v_toplam numeric; v_kapsam numeric; v_n int; v_ay_ciro numeric;
begin
  select coalesce(sum(net_kar),0) into v_toplam from cfo_aylik_urun_kar where ay = v_ay;
  select coalesce(sum(tutar_duz),0)::numeric into v_ay_ciro
    from cfo_satis_birim_duz where date_trunc('month',"orderDate")::date = v_ay;
  select round(100.0 * coalesce(sum(brut_ciro),0)::numeric / nullif(v_ay_ciro,0), 1)
    into v_kapsam from cfo_aylik_urun_kar where ay = v_ay;

  delete from cfo_ay_kazanan where ay = v_ay;

  insert into cfo_ay_kazanan (ay,sira,sku,ad,category,adet,siparis_satiri,brut_ciro,
    ort_siparis_tutari,kargo_toplam,kargo_pct,net_tahsilat,birim_maliyet,
    toplam_maliyet,net_kar,marj_pct,birim_kar,kanal_sayisi,oran_guveni,
    ay_toplam_kar,kar_payi_pct,kapsam_pct,maliyet_kaynagi)
  select v_ay, row_number() over (order by net_kar desc), sku, ad, category, adet, siparis_satiri,
    brut_ciro, ort_siparis_tutari, kargo_toplam, kargo_pct, net_tahsilat, birim_maliyet,
    toplam_maliyet, net_kar, marj_pct, birim_kar, kanal_sayisi, oran_guveni, v_toplam,
    round((net_kar / nullif(v_toplam,0) * 100)::numeric,1), v_kapsam, p_maliyet_kaynagi
  from cfo_aylik_urun_kar where ay = v_ay order by net_kar desc limit 10;

  get diagnostics v_n = row_count;
  return query select v_n, v_toplam, v_kapsam;
end $function$
;

CREATE OR REPLACE FUNCTION public.cfo_defter_denetim()
 RETURNS TABLE(sira integer, kod text, seviye text, bulgu text, detay text, ne_yapmali text)
 LANGUAGE sql
 STABLE
AS $function$
select 1, 'MUKERRER', case when count(*)>0 then 'KIRMIZI' else 'YESIL' end,
  count(*)||' mukerrer odeme grubu',
  coalesce(string_agg(distinct d.gun||' · '||round(d.tutar)||' TL x'||d.adet, ' | '),'yok'),
  'Ayni gun + ayni tutar birden fazla kez girilmis. Fazlasini sil.'
from (select "eventDate"::date gun, "outflowTry" tutar, count(*) adet
      from cfo_cash_event where coalesce("outflowTry",0)>0 and "isSettled"=false
      group by 1,2 having count(*)>1) d
union all
-- 2) EKSIK KREDI TAKSITI — nextPaymentDate'ten baslar (banka tablosu esas)
select 2, 'KREDI_EKSIK', case when count(*)>0 then 'KIRMIZI' else 'YESIL' end,
  count(*)||' kredi taksiti takvimde yok',
  coalesce(string_agg(x.bank||' '||to_char(x.beklenen,'DD.MM.YYYY')||' ('||round(x.taksit)||' TL)', ' | '),'yok'),
  'Aktif kredinin taksiti nakit takviminde yok. KREDI_TAKSITI olarak ekle.'
from (
  select l.bank, l."monthlyPaymentTry" taksit,
    (l."nextPaymentDate"::date + (m||' month')::interval)::date beklenen
  from cfo_loan l cross join generate_series(0,2) m
  where l.status::text='AKTIF' and l."nextPaymentDate" is not null
) x
where x.beklenen >= current_date
  and not exists (select 1 from cfo_cash_event e
    where e.kind::text='KREDI_TAKSITI' and e."eventDate"::date between x.beklenen-4 and x.beklenen+4
      and abs(coalesce(e."outflowTry",0) - x.taksit) < greatest(x.taksit*0.45, 5000))
union all
select 3, 'KART_EKSIK', case when count(*)>0 then 'KIRMIZI' else 'YESIL' end,
  count(*)||' kart odemesi takvimde yok',
  coalesce(string_agg(c.bank||' '||coalesce(c.holder,'')||' '||to_char(c."nextDueDate",'DD.MM.YYYY'), ' | '),'yok'),
  'Aktif kartin son odeme tarihi takvimde yok. KART_ODEMESI olarak ekle.'
from cfo_credit_card c
where c."isActive" and c."nextDueDate" is not null and c."nextDueDate"::date >= current_date
  and not exists (select 1 from cfo_cash_event e
    where e.kind::text='KART_ODEMESI' and e."eventDate"::date between c."nextDueDate"::date-3 and c."nextDueDate"::date+3
      and (e.bank = c.bank or e.description ilike '%'||c.bank||'%'))
union all
select 4, 'SABIT_GIDER_EKSIK', case when count(*)>0 then 'KIRMIZI' else 'YESIL' end,
  count(*)||' ay icin sabit gider kaydi yok',
  coalesce(string_agg(to_char(x.ay,'MM.YYYY'), ' | '),'yok'),
  'O ayin sabit gideri takvimde yok. Aylik toplam: '||
    (select round(sum("monthlyTry")) from cfo_fixed_expense where "isActive")||' TL'
from (select (date_trunc('month',current_date) + (m||' month')::interval)::date ay from generate_series(0,2) m) x
where not exists (select 1 from cfo_cash_event e
  where e.kind::text='SABIT_GIDER' and date_trunc('month',e."eventDate")::date = x.ay
    and coalesce(e."outflowTry",0) > 0 group by 1 having sum(coalesce(e."outflowTry",0)) >= 100000)
union all
select 5, 'HAKEDIS_EKSIK', case when count(*)>0 then 'KIRMIZI' else 'YESIL' end,
  count(*)||' pazaryeri kanalinin yaklasan hakedisi yok',
  coalesce(string_agg(k.channel, ' | '),'yok'),
  'Duzenli odeyen kanalin onumuzdeki 14 gunde hakedis kaydi yok. Panelden bak, cfo_receivable''a ekle.'
from (select distinct channel from cfo_receivable
      where "dueDate" >= current_date - 45 and "dueDate" < current_date) k
where not exists (select 1 from cfo_receivable r
  where r.channel = k.channel and r."isCollected"=false
    and r."dueDate"::date between current_date and current_date+14)
  and not exists (select 1 from cfo_receivable p
    where p.channel = k.channel and p."isCollected"
      and p."dueDate"::date >= current_date - 7)
union all
select 6, 'BAYAT_BAKIYE', case when count(*)>0 then 'KIRMIZI' else 'YESIL' end,
  count(*)||' hesabin bakiyesi 7 gunden eski',
  coalesce(string_agg(b.name||' ('||(current_date - b."lastUpdatedAt"::date)||' gun)', ' | '),'yok'),
  'Yuruyen bakiyenin tamami acilis bakiyesine dayanir. Ekrandan oku, guncelle.'
from cfo_bank_account b where b."isActive" and b."lastUpdatedAt"::date < current_date - 7
union all
select 7, 'TAHSILAT_ISARETSIZ', case when count(*)>0 then 'KIRMIZI' else 'YESIL' end,
  count(*)||' tahsilat vadesi gecti, isaretlenmedi ('||coalesce(round(sum("amountTry")),0)||' TL)',
  coalesce(string_agg(channel||' '||to_char("dueDate",'DD.MM'), ' | '),'yok'),
  'Para geldiyse tahsil edildi isaretle; gelmediyse gecikmis alacak olarak takip et.'
from cfo_receivable where "isCollected"=false and "dueDate"::date < current_date - 1
union all
select 8, 'ODEME_ISARETSIZ', case when count(*)>0 then 'KIRMIZI' else 'YESIL' end,
  count(*)||' odeme tarihi gecti, isaretlenmedi ('||coalesce(round(sum("outflowTry")),0)||' TL)',
  coalesce(string_agg(left(description,30)||' '||to_char("eventDate",'DD.MM'), ' | '),'yok'),
  'Odendiyse isaretle; odenmediyse tarihini guncelle. Isaretlenmemis gecmis odeme yuruyen bakiyeyi bozar.'
from cfo_cash_event where "isSettled"=false and coalesce("outflowTry",0)>0 and "eventDate"::date < current_date
union all
select 9, 'TUTARSIZ_KAYIT', case when count(*)>0 then 'SARI' else 'YESIL' end,
  count(*)||' kayitta tutar bos veya sifir',
  coalesce(string_agg(left(description,40), ' | '),'yok'), 'Tutari gir veya kaydi sil.'
from cfo_cash_event
where "isSettled"=false and "eventDate" >= current_date
  and coalesce("outflowTry",0)=0 and coalesce("inflowTry",0)=0
union all
select 10, 'TAKVIM_UFKU',
  case when (select max("eventDate")::date from cfo_cash_event) < current_date + 60 then 'KIRMIZI'
       when (select max("eventDate")::date from cfo_cash_event) < current_date + 90 then 'SARI'
       else 'YESIL' end,
  'Nakit takvimi '||((select max("eventDate")::date from cfo_cash_event) - current_date)||' gun ileriye dolu',
  'Son kayit: '||to_char((select max("eventDate") from cfo_cash_event),'DD.MM.YYYY'),
  'Takvim en az 90 gun ileriye dolu olmali. Kredi/kart/sabit gider serilerini uzat.'
order by 1;
$function$
;

CREATE OR REPLACE FUNCTION public.cfo_google(p_body jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE
  tok text;
  body text;
BEGIN
  SELECT s.value INTO tok FROM public.cfo_secret s WHERE s.key = 'CFO_GOOGLE_INTERNAL_TOKEN';
  IF tok IS NULL OR length(tok) < 32 THEN
    RAISE EXCEPTION 'cfo_google: internal token not provisioned';
  END IF;
  SELECT h.content INTO body FROM extensions.http((
    'POST',
    'https://frbxpodiostxuwlrubkt.supabase.co/functions/v1/cfo-google',
    ARRAY[extensions.http_header('x-cfo-internal', tok)],
    'application/json',
    p_body::text
  )::extensions.http_request) h;
  RETURN body::jsonb;
END
$function$
;

CREATE OR REPLACE FUNCTION public.cfo_gumruk_dilim(p_gumruk_tarih date DEFAULT NULL::date)
 RETURNS TABLE(kalem text, tutar numeric, aciklama text)
 LANGUAGE sql
 STABLE
AS $function$
with g_tarih as (
  select coalesce(
    p_gumruk_tarih,
    (select min("eventDate")::date from cfo_cash_event
      where not "isSettled" and kind = 'VERGI_GUMRUK'
        and "eventDate"::date >= current_date)
  ) as d
),
k as (select * from cfo_nakit_kapisi),
onceki as (select pozisyon p from cfo_nakit_projeksiyon(120)
           where tarih = (select d from g_tarih) - 1),
gumruk as (select coalesce(sum("outflowTry"),0) v from cfo_cash_event
           where not "isSettled" and "eventDate"::date = (select d from g_tarih)),
sonra7 as (select coalesce(sum("outflowTry"),0) v from cfo_cash_event
           where not "isSettled" and "eventDate"::date
                 between (select d from g_tarih)+1 and (select d from g_tarih)+7),
taban as (select "netPositionFloorTry" v from cfo_settings)
select 'Gumruk oncesi pozisyon'::text, (select p from onceki),
       ((select d from g_tarih)-1)::text||' sonu'
union all select 'Gumruk odeme tarihi', null::numeric, (select d from g_tarih)::text
union all select 'Toplam gumruk tutari', (select v from gumruk), 'O gunun toplam cikisi'
union all select 'Genel ticari kaynak', (select nakit_try+bos_kmh_try from k), 'nakit + genel KMH'
union all select 'Amaca bagli KMH (gumruk)', (select amacli_kmh_try from k), 'Ziraat, yalniz gumruk odemesinde'
union all select 'Odeme aninda toplam kaynak', (select nakit_try+bos_kmh_try+amacli_kmh_try from k), 'Ikisinin toplami'
union all select 'Sonraki 7 gunun cikislari', (select v from sonra7), 'Odeme sonrasi tampon'
union all select 'SINIR 1 — taban kurali', (select v from taban)*-1 + (select p from onceki),
  'Taban -3.000.000 TL korunarak odenebilecek azami'
union all select 'SINIR 2 — fiziksel kaynak',
  (select nakit_try+bos_kmh_try+amacli_kmh_try from k) + (select p from onceki) - (select v from sonra7),
  'Amaca bagli limit dahil, sonraki 7 gun ayrildiktan sonra'
union all select 'BAGLAYICI AZAMI ODEME',
  least((select v from taban)*-1 + (select p from onceki),
        (select nakit_try+bos_kmh_try+amacli_kmh_try from k) + (select p from onceki) - (select v from sonra7)),
  'Iki sinirin kucugu'
union all select 'CEKILEBILIR ORAN (%)',
  round(100.0 * least((select v from taban)*-1 + (select p from onceki),
        (select nakit_try+bos_kmh_try+amacli_kmh_try from k) + (select p from onceki) - (select v from sonra7))
        / nullif((select v from gumruk),0), 1),
  'Konteynerin bu orani cekilir';
$function$
;

CREATE OR REPLACE FUNCTION public.cfo_kar_kopru(p_baz date, p_hedef date)
 RETURNS TABLE(sira integer, bilesen text, sku_sayisi integer, adet bigint, ciro numeric, kar numeric, marj numeric, kar_etkisi numeric, aciklama text)
 LANGUAGE sql
 STABLE
AS $function$
with a as (select * from cfo_aylik_urun_kar where ay = p_baz),
     b as (select * from cfo_aylik_urun_kar where ay = p_hedef),
     kalan_a as (select * from a where sku in (select sku from b)),
     kalan_b as (select * from b where sku in (select sku from a)),
     kayip as (select * from a where sku not in (select sku from b)),
     yeni as (select * from b where sku not in (select sku from a))
select 1, 'BAZ AY TOPLAM', count(*)::int, sum(adet)::bigint, round(sum(brut_ciro)),
  round(sum(net_kar)), round((sum(net_kar)/nullif(sum(brut_ciro),0)*100)::numeric,1), 0::numeric,
  'Baslangic noktasi: ' || to_char(p_baz,'MM.YYYY') from a
union all
select 2, 'Birakilen urunler', count(*)::int, sum(adet)::bigint, round(sum(brut_ciro)),
  round(sum(net_kar)), round((sum(net_kar)/nullif(sum(brut_ciro),0)*100)::numeric,1), round(-sum(net_kar)),
  'Bazda vardi, hedefte YOK. Marji ' || round((sum(net_kar)/nullif(sum(brut_ciro),0)*100)::numeric,1) || ' idi.' from kayip
union all
select 3, 'Kalan urunlerin IYILESMESI',
  (select count(*)::int from kalan_b), (select sum(adet)::bigint from kalan_b),
  (select round(sum(brut_ciro)) from kalan_b), (select round(sum(net_kar)) from kalan_b),
  (select round((sum(net_kar)/nullif(sum(brut_ciro),0)*100)::numeric,1) from kalan_b),
  (select round(sum(net_kar)) from kalan_b) - (select round(sum(net_kar)) from kalan_a),
  'AYNI SKUlar. Marj ' || (select round((sum(net_kar)/nullif(sum(brut_ciro),0)*100)::numeric,1) from kalan_a)
    || ' -> ' || (select round((sum(net_kar)/nullif(sum(brut_ciro),0)*100)::numeric,1) from kalan_b)
    || ' · adet ' || (select sum(adet) from kalan_a) || ' -> ' || (select sum(adet) from kalan_b)
    || ' · birim kar ' || (select round((sum(net_kar)/nullif(sum(adet),0))::numeric,2) from kalan_a)
    || ' -> ' || (select round((sum(net_kar)/nullif(sum(adet),0))::numeric,2) from kalan_b) || ' TL'
union all
select 4, 'Yeni urunler', count(*)::int, sum(adet)::bigint, round(sum(brut_ciro)),
  round(sum(net_kar)), round((sum(net_kar)/nullif(sum(brut_ciro),0)*100)::numeric,1), round(sum(net_kar)),
  'Hedefte var, bazda YOKTU. Marji ' || round((sum(net_kar)/nullif(sum(brut_ciro),0)*100)::numeric,1) from yeni
union all
select 5, 'HEDEF AY TOPLAM', count(*)::int, sum(adet)::bigint, round(sum(brut_ciro)),
  round(sum(net_kar)), round((sum(net_kar)/nullif(sum(brut_ciro),0)*100)::numeric,1),
  (select round(sum(net_kar)) from b) - (select round(sum(net_kar)) from a),
  'Varis: ' || to_char(p_hedef,'MM.YYYY') from b
order by 1;
$function$
;

CREATE OR REPLACE FUNCTION public.cfo_kargo_tahmin(p_date date, p_desi numeric, p_carrier text DEFAULT 'TEX'::text, p_order_try numeric DEFAULT NULL::numeric)
 RETURNS TABLE(price_ex_vat numeric, price_incl_vat numeric, basis text, tariff_valid_from date, verified boolean)
 LANGUAGE sql
 STABLE
AS $function$
  WITH barem AS (
    SELECT b.id, b.flat_price_ex_vat, b.verified FROM public.cfo_kargo_barem b
    WHERE p_order_try IS NOT NULL AND b.valid_from IS NOT NULL AND p_date BETWEEN b.valid_from AND b.valid_to
      AND p_order_try >= b.order_min_try AND p_order_try < b.order_below_try AND b.carrier_group = '*'
    ORDER BY b.id LIMIT 1),
  desi_row AS (
    SELECT t.price_ex_vat, t.valid_from, (t.valid_to IS NULL AND t.valid_from <= p_date) AS current_version
    FROM public.cfo_kargo_desi_tarife t
    WHERE lower(t.carrier) = lower(p_carrier) AND t.valid_from <= p_date AND (t.valid_to IS NULL OR t.valid_to >= p_date)
      AND t.desi = ceil(p_desi)::int
    ORDER BY t.valid_from DESC LIMIT 1)
  SELECT x.p, round(x.p * 1.20, 2), x.basis, x.vf, x.ver FROM (
    SELECT flat_price_ex_vat AS p, 'BAREM_' || id AS basis, NULL::date AS vf, verified AS ver FROM barem
    UNION ALL
    SELECT d.price_ex_vat, 'DESI_TARIFE', d.valid_from, false FROM desi_row d WHERE NOT EXISTS (SELECT 1 FROM barem)
  ) x
$function$
;

CREATE OR REPLACE FUNCTION public.cfo_kart_karari()
 RETURNS TABLE(sira integer, karar text, tarih date, kalem text, mevcut_odeme numeric, yeni_odeme numeric, kazanc numeric, aylik_faiz numeric, kumulatif_kazanc numeric, yeni_dip numeric, gerekce text)
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_taban numeric := (select "netPositionFloorTry" from cfo_settings);
  v_minpct numeric := (select "cardMinPct" from cfo_settings);
  v_faiz numeric := (select "kmhMonthlyRatePct" from cfo_settings);
  v_dip numeric; v_dip_tarih date; v_acik numeric;
  v_kum numeric := 0; v_i int := 0; r record; v_poz numeric;
begin
  select min(p.pozisyon) into v_dip from cfo_nakit_projeksiyon(120) p;
  select p.tarih into v_dip_tarih from cfo_nakit_projeksiyon(120) p
   where p.pozisyon = v_dip order by p.tarih limit 1;

  if v_dip >= v_taban then
    return query select 1,'TABAN KORUNUYOR'::text, v_dip_tarih,'-'::text,
      0::numeric,0::numeric,0::numeric,0::numeric,0::numeric,v_dip,
      ('En dip '||round(v_dip)||' TL, taban '||round(v_taban)||' TL, pay '||round(v_dip-v_taban)
       ||' TL. Kart odemeleri PLANLANDIGI GIBI yapilir.')::text;
    return;
  end if;

  v_acik := v_taban - v_dip;
  return query select 0,'TABAN DELINIYOR'::text, v_dip_tarih,'-'::text,
    0::numeric,0::numeric,0::numeric,0::numeric,0::numeric,v_dip,
    ('En dip '||round(v_dip)||' TL ('||v_dip_tarih||'), taban '||round(v_taban)||' TL. ACIK '
     ||round(v_acik)||' TL.')::text;

  for r in
    with kalem as (
      select e."eventDate"::date d, e.description aciklama, e."outflowTry" tam,
        (e.description ilike '%HARD DEADLINE%') korumali,
        (select coalesce(c."minOverrideTry", round(coalesce(c."statementDebtTry", e."outflowTry")*v_minpct/100.0,2))
           from cfo_credit_card c where c."isActive" and e.description ilike '%'||c.bank||'%'
          order by c."sortOrder" limit 1) asg
      from cfo_cash_event e
      where not e."isSettled" and e.kind::text='KART_ODEMESI'
        and e."eventDate"::date <= v_dip_tarih
        and e.description not ilike '%asgari%'
        and not (e.description ilike '%taksiti%' and e.description not ilike '%dahil%')
    )
    select d, aciklama, tam, asg, korumali from kalem where asg is not null and tam > asg + 1
    order by korumali asc, (tam - asg) desc
  loop
    if r.korumali then
      select p.pozisyon into v_poz from cfo_nakit_projeksiyon(120) p where p.tarih = r.d;
      if coalesce(v_poz, -1) >= 0 then
        return query select 50,'KORUMALI — TAM ODENIR'::text, r.d, left(r.aciklama,45),
          r.tam, r.tam, 0::numeric, 0::numeric, v_kum, (v_dip+v_kum),
          ('HARD DEADLINE var ve o gun pozisyon '||round(coalesce(v_poz,0))||' TL: tam odenir.')::text;
      else
        v_i := v_i + 1; v_kum := v_kum + (r.tam - r.asg);
        return query select 51,'KORUMALI AMA NAKIT YOK — ASGARIYE CEK'::text, r.d, left(r.aciklama,45),
          r.tam, r.asg, (r.tam-r.asg), round((r.tam-r.asg)*v_faiz/100.0,2), v_kum, (v_dip+v_kum),
          ('HARD DEADLINE var AMA o gun pozisyon '||round(coalesce(v_poz,0))
           ||' TL — tam odeme MUMKUN DEGIL. Asgari odenir, kalan '||round(r.tam-r.asg)
           ||' TL sonraki ekstreye devreder. Korumanin kaybi RAPORDA belirtilir.')::text;
      end if;
      continue;
    end if;

    exit when v_kum >= v_acik;
    v_i := v_i + 1; v_kum := v_kum + (r.tam - r.asg);
    return query select v_i,'ASGARIYE CEK'::text, r.d, left(r.aciklama,45),
      r.tam, r.asg, (r.tam-r.asg), round((r.tam-r.asg)*v_faiz/100.0,2), v_kum, (v_dip+v_kum),
      ('Ertelenen '||round(r.tam-r.asg)||' TL · aylik faiz ~'||round((r.tam-r.asg)*v_faiz/100.0)||' TL')::text;
  end loop;

  if coalesce(v_kum,0) < v_acik then
    return query select 99,'YETERSIZ — BASKA KALDIRAC SART'::text, v_dip_tarih,'-'::text,
      0::numeric,0::numeric,0::numeric,0::numeric, coalesce(v_kum,0), (v_dip+coalesce(v_kum,0)),
      ('Kart asgarilerinden sonra taban hala '||round(v_acik-coalesce(v_kum,0))
       ||' TL deliniyor. GECERLI KALDIRAC MERDIVENI (30.08 teyidi sonrasi): '
       ||'(1) 28.09 KISMI CEKIM karari — beyannameyi bol, kaynagin yettigi kadarini cek [cfo_gumruk_dilim()]; '
       ||'(2) antrepoda bekletme — ardiye maliyeti karsiligi nakdi zamana yay; '
       ||'(3) Trendyol erken odeme — ekim hakedislerini 04.10 oncesine cek; '
       ||'(4) 01.10 sabit giderlerini kis (348.400 TL, dip oncesindeki tek buyuk esnek kalem); '
       ||'(5) en pahali borcu yapilandir; (6) sahsi hesaplar — son care, sifir tampon. '
       ||'DIKKAT: gumruk TAKSITLENDIRME ve TEMINAT MEKTUBU ile mal cekimi YOKTUR '
       ||'(gumruk musaviri 30.08.2026 kesin ret). Yurtdisi siparis erteleme 30.08de zaten yapildi.')::text;
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.cfo_kaynak_yeterliligi()
 RETURNS TABLE(kalem text, tutar numeric, aciklama text)
 LANGUAGE sql
 STABLE
AS $function$
with p as (select min(pozisyon) dip from cfo_nakit_projeksiyon(120)),
d as (select tarih from cfo_nakit_projeksiyon(120) where pozisyon=(select dip from p) order by tarih limit 1),
k as (select * from cfo_nakit_kapisi),
sahsi as (select coalesce(sum("kmhLimitTry"),0) v from cfo_bank_account where "isActive" and "accountType" ilike '%ŞAHSİ%')
select 'En dip ihtiyac'::text, -(select dip from p), ('En dusuk pozisyon '||(select tarih from d))::text
union all select 'Nakit (ticari)', (select nakit_try from k), 'Sirketin kendi parasi'
union all select 'Bos GENEL KMH', (select bos_kmh_try from k), 'Her ise kullanilabilir'
union all select 'GENEL TICARI KAYNAK', (select nakit_try+bos_kmh_try from k), 'Amaca bagli limit HARIC'
union all select 'ACIK (genel kaynak)', (select nakit_try+bos_kmh_try from k)+(select dip from p),
  (case when (select nakit_try+bos_kmh_try from k)+(select dip from p) < 0
        then 'NEGATIF — genel kaynaklarla yetmiyor' else 'Yeterli' end)::text
union all select 'Amaca bagli KMH (Ziraat/gumruk)', (select amacli_kmh_try from k),
  'YALNIZCA gumruk vergisi Ziraattten odenirse acilir'
union all select 'GUMRUK ANINDA TOPLAM KAYNAK', (select nakit_try+bos_kmh_try+amacli_kmh_try from k),
  'Genel + amaca bagli'
union all select 'ACIK (gumruk limiti dahil)',
  (select nakit_try+bos_kmh_try+amacli_kmh_try from k)+(select dip from p),
  (case when (select nakit_try+bos_kmh_try+amacli_kmh_try from k)+(select dip from p) < 0
        then 'NEGATIF — gumruk limiti dahil bile yetmiyor' else 'YETERLI' end)::text
union all select 'Sahsi KMH (son care)', (select v from sahsi), 'KKDF %15 + BSMV: ~14-19 puan pahali'
union all select 'ACIK (her sey dahil)',
  (select nakit_try+bos_kmh_try+amacli_kmh_try from k)+(select v from sahsi)+(select dip from p),
  (case when (select nakit_try+bos_kmh_try+amacli_kmh_try from k)+(select v from sahsi)+(select dip from p) < 0
        then 'HALA NEGATIF' else 'Ancak sahsi hesaplarla ve SIFIR TAMPONLA kapaniyor' end)::text;
$function$
;

CREATE OR REPLACE FUNCTION public.cfo_kilometre_yaz(p_ay date DEFAULT (date_trunc('month'::text, (CURRENT_DATE - '1 mon'::interval)))::date)
 RETURNS TABLE(r_ay date, r_ciro numeric, r_ciro_usd numeric, r_kar numeric, r_kar_usd numeric, r_marj numeric, r_kur numeric)
 LANGUAGE plpgsql
AS $function$
begin
  insert into cfo_kilometre_tasi as t (ay, ciro, kar, kar_marji, top10_kar, birinci_urun,
    nakit, alacak, kredi_borc, kart_borc, servet_try, servet_usd, servet_yontem, olculdu_at)
  select p_ay,
    (select sum(s.tutar_duz) from cfo_satis_birim_duz s where date_trunc('month',s."orderDate")::date = p_ay),
    k.ay_toplam_kar, null, k.top10_kar, k.birinci,
    (select coalesce(sum(b."balanceTry"),0) from cfo_bank_account b where b."isActive"),
    (select coalesce(sum(r."amountTry"),0) from cfo_receivable r where not r."isCollected"),
    (select coalesce(sum(coalesce(l."remainingOverride",l."remainingTry")),0) from cfo_loan l where l.status::text='AKTIF'),
    (select coalesce(sum(c."totalDebtTry"),0) from cfo_credit_card c where c."isActive"),
    (select v.servet_try from cfo_servet v), (select v.servet_usd from cfo_servet v),
    'cfo_servet v1 (stok NRV + yoldaki mal iki tarafli)', now()
  from cfo_ay_kazanan_ozet k where k.ay = p_ay
  on conflict (ay) do update set
    ciro=excluded.ciro, kar=excluded.kar, top10_kar=excluded.top10_kar, birinci_urun=excluded.birinci_urun,
    nakit=excluded.nakit, alacak=excluded.alacak, kredi_borc=excluded.kredi_borc, kart_borc=excluded.kart_borc,
    servet_try=excluded.servet_try, servet_usd=excluded.servet_usd, servet_yontem=excluded.servet_yontem,
    olculdu_at=now();

  update cfo_kilometre_tasi x set kar_marji = round((x.kar/nullif(x.ciro,0)*100)::numeric,1) where x.ay = p_ay;

  update cfo_kilometre_tasi x set usd_try = k.usd_try,
    ciro_usd = round((x.ciro/k.usd_try)::numeric,0),
    kar_usd  = round((x.kar /k.usd_try)::numeric,0)
  from cfo_kur k where k.ay = x.ay and x.ay = p_ay;

  insert into cfo_hamle_olcum (hamle_kod, olcum_tarihi, deger, not_)
  select 'H01-MARJ-DONUSU', p_ay, x.kar_marji,
    'Aylik kapanis · ciro ' || coalesce(x.ciro_usd::text,'?') || ' USD · kar ' || coalesce(x.kar_usd::text,'?') || ' USD'
  from cfo_kilometre_tasi x where x.ay = p_ay and x.kar_marji is not null
  and not exists (select 1 from cfo_hamle_olcum o where o.hamle_kod='H01-MARJ-DONUSU' and o.olcum_tarihi=p_ay);

  return query select x.ay, x.ciro, x.ciro_usd, x.kar, x.kar_usd, x.kar_marji, x.usd_try
    from cfo_kilometre_tasi x where x.ay = p_ay;
end $function$
;

CREATE OR REPLACE FUNCTION public.cfo_model_hakedis(p_gun integer DEFAULT 120, p_guven numeric DEFAULT 1.0)
 RETURNS TABLE(tarih date, channel text, tutar numeric)
 LANGUAGE sql
 STABLE
AS $function$
with hiz as (
  select d.channel,
         sum(d.tutar_duz)/90.0 * coalesce(n.net_oran,0.65) gunluk_net
  from cfo_satis_birim_duz d
  left join cfo_kanal_net_oran n on n.channel = d.channel
  where d."orderDate" >= date '2026-09-08' - 90 and d."orderDate" < date '2026-09-08'
  group by d.channel, n.net_oran
), baslangic as (
  select h.channel, h.gunluk_net,
    coalesce(
      (select max(r."dueDate")::date from cfo_receivable r
        where not r."isCollected" and r.channel = g.alacak_channel),
      current_date + coalesce(g.gecikme_gun,30)
    ) ilk_gun
  from hiz h left join cfo_kanal_gecikme g on g.channel = h.channel
)
select gs::date, b.channel, round((b.gunluk_net * p_guven)::numeric, 2)
from baslangic b
cross join generate_series(current_date, current_date + p_gun, '1 day') gs
where gs::date > b.ilk_gun and b.gunluk_net > 0;
$function$
;

CREATE OR REPLACE FUNCTION public.cfo_nakit_projeksiyon(gun integer DEFAULT 120)
 RETURNS TABLE(tarih date, giris numeric, cikis numeric, net numeric, pozisyon numeric, aciklama text)
 LANGUAGE sql
 STABLE
AS $function$
with baslangic as (select nakit_try n from cfo_nakit_kapisi),
-- KANAL BAZLI ufuk: her kanalin KENDI son adli hakedisi ve KENDI gunluk hizi.
-- 07.09.2026 duzeltmesi: eskiden tek bir GLOBAL ufuk vardi.
-- 🔴 24.09.2026 DUZELTMESI — TAHSILAT ERIMESI:
--   Eskiden gunluk hiz da "not isCollected" ile suzuluyordu. Yani bir hakedis TAHSIL
--   EDILIP isaretlenince paydan dusuyor, payda (30) sabit kaliyordu; sonuc olarak
--   PARANIN GELMIS OLMASI, ayni kanalin GELECEK tahminini kalici olarak dusuruyordu.
--   Ters tesvik: defter ne kadar dogru tutulursa dip o kadar kotu gorunuyordu.
--   *24.09 olcumu: iki tahsilat isaretlenince (ePttAVM 34.846 + Trendyol 87.873)
--   gunluk tahmin 4.090,61 TL/gun dustu ve 01.12 dibi 170.593 TL YAPAY olarak
--   derinlesti.*
--   DUZELTME: gunluk hiz kanalin onumuzdeki 30 gundeki TUM kayitlarindan olculur
--   (tahsil edilmis olsun olmasin) — bu, kanalin ODEME TEMPOSUDUR.
--   son_d ise YALNIZ ACIK kayitlardan alinir, cunku tahmin ancak defter kayitlarinin
--   bittigi gunden SONRA baslar; boylece CIFT SAYIM olmaz (s7).
kanal as (
  select channel,
         coalesce(max("dueDate") filter (where not "isCollected" and "dueDate" >= current_date)::date,
                  current_date - 1) son_d,
         coalesce(sum("amountTry") filter (where "dueDate" between current_date and current_date + 30),0)/30.0 gunluk
  from cfo_receivable
  where "dueDate" >= current_date - 30
  group by channel),
takvim as (select generate_series(current_date, current_date + gun, '1 day')::date d),
gir as (select "dueDate"::date d, sum("amountTry") v, string_agg(channel,'+') a
        from cfo_receivable where not "isCollected" and "dueDate" between current_date and current_date + gun
        group by 1),
cik as (select "eventDate"::date d, sum("outflowTry") v, string_agg(left(coalesce(description,kind::text),28),' | ') a
        from cfo_cash_event where not "isSettled" and "eventDate" between current_date and current_date + gun
        group by 1),
tah as (select t.d, sum(k.gunluk) v, count(*) n
        from takvim t join kanal k on t.d > k.son_d and k.gunluk > 0
        group by t.d),
h as (
  select t.d, coalesce(g.v,0) + coalesce(th.v,0) giris, coalesce(c.v,0) cikis,
         nullif(concat_ws(' · ', g.a,
           case when th.v is not null then 'tahmini tahsilat ('||th.n||' kanal)' end, c.a),'') acik
  from takvim t
  left join gir g on g.d=t.d left join cik c on c.d=t.d left join tah th on th.d=t.d
)
select h.d, round(h.giris)::numeric, round(h.cikis)::numeric, round(h.giris-h.cikis)::numeric,
       round((select n from baslangic) + sum(h.giris-h.cikis) over (order by h.d))::numeric, h.acik
from h order by h.d;
$function$
;

CREATE OR REPLACE FUNCTION public.cfo_norm(t text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$ select upper(regexp_replace(coalesce(t,''), '[^0-9A-Za-zÇĞİÖŞÜçğıöşü]', '', 'g')) $function$
;

CREATE OR REPLACE FUNCTION public.cfo_onucus()
 RETURNS TABLE(sira integer, seviye text, kontrol text, deger text, ne_yapmali text)
 LANGUAGE sql
 STABLE
AS $function$
  select * from cfo_onucus_v19()
  union all
  select 20,
    case when (select count(*) from cfo_defter_denetim() where seviye='KIRMIZI') > 0 then 'KIRMIZI'
         when (select count(*) from cfo_defter_denetim() where seviye='SARI') > 0 then 'SARI'
         else 'YESIL' end,
    'Defter butunlugu denetimi',
    (select count(*)||' kirmizi / '||count(*) filter (where seviye='SARI')||' sari'
     from cfo_defter_denetim() where seviye in ('KIRMIZI','SARI'))
      || coalesce((select ' — '||string_agg(kod,', ') from cfo_defter_denetim() where seviye='KIRMIZI'),''),
    'select * from cfo_defter_denetim() calistir. Kirmizi satirlarin ne_yapmali talimatini uygula. Eksik/mukerrer kayit nakit takvimini bozar.'
  union all
  select 21,
    case when count(*) filter (where otomatik_teshis in ('ACIKLANAMADI','TOPLU_DUZELTME_SUPHESI')) > 0 then 'KIRMIZI'
         when count(*) filter (where otomatik_teshis = 'BEKLIYOR_TRENDYOL_SENKRONU') > 0 then 'SARI'
         else 'YESIL' end,
    'Keskin stok dususu (XML)',
    count(*) filter (where otomatik_teshis in ('ACIKLANAMADI','TOPLU_DUZELTME_SUPHESI'))||' aciklanamayan · '
      ||count(*) filter (where otomatik_teshis='BEKLIYOR_TRENDYOL_SENKRONU')||' senkron bekliyor · '
      ||coalesce(sum(aciklanamayan_adet) filter (where otomatik_teshis in ('ACIKLANAMADI','TOPLU_DUZELTME_SUPHESI')),0)||' adet / '
      ||coalesce(sum(aciklanamayan_maliyet_try) filter (where otomatik_teshis in ('ACIKLANAMADI','TOPLU_DUZELTME_SUPHESI')),0)||' TL (son 14 gun)',
    'select * from cfo_stok_sicrama_durum where durum=''ACIK'' order by hareket_gunu desc; Her ACIKLANAMADI satiri icin once cfo_xml_urun_degisim ve diger kanallari kontrol et, yine aciklanamazsa Alperene TEK soru olarak sor. Cevap gelince cfo_sicrama_kapat(id, durum, aciklama). STOK DUSUSU SATIS DEGILDIR (§9).'
  from cfo_stok_sicrama_durum
  where durum = 'ACIK' and hareket_gunu >= current_date - 14
  order by 1;
$function$
;

CREATE OR REPLACE FUNCTION public.cfo_onucus_temel()
 RETURNS TABLE(sira integer, seviye text, kontrol text, deger text, ne_yapmali text)
 LANGUAGE sql
 STABLE
AS $function$
with tr as (select (now() at time zone 'Europe/Istanbul') t),
sat as (select max("orderDate")::date son, current_date - max("orderDate")::date gecikme from "MarketplaceSalesRecord"),
atf as (select (100.0*coalesce(sum("totalAmountTry"-tutar_duz),0)/nullif(sum("totalAmountTry"),0))::numeric(6,2) pay,
   coalesce(sum("totalAmountTry"-tutar_duz),0)::numeric(12,0) tl from cfo_satis_birim_duz where "orderDate">=current_date-90),
nak as (select * from cfo_nakit_kapisi),
banka as (select coalesce(max(current_date - "lastUpdatedAt"::date),0) bayat,
                 count(*) filter (where current_date - "lastUpdatedAt"::date > 2) n
          from cfo_bank_account where "isActive" and "accountType" not ilike '%ŞAHSİ%'),
proj as (select min(pozisyon) dip, (select "netPositionFloorTry" from cfo_settings) taban from cfo_nakit_projeksiyon(120)),
dipt as (select tarih from cfo_nakit_projeksiyon(120) where pozisyon=(select dip from proj) order by tarih limit 1),
kyn as (select (select nakit_try+bos_kmh_try from nak) + (select dip from proj) acik_ticari,
               (select nakit_try+bos_kmh_try from nak) kaynak),
kk as (select count(*) filter (where karar like 'ASGARIYE%' or karar like 'KORUMALI AMA%') n_asg,
              count(*) filter (where karar like 'YETERSIZ%') n_yetersiz from cfo_kart_karari()),
sip as (select count(*) n from cfo_order_batch b join cfo_order_line l on l.batch_id=b.id
        where b.status in ('ONAYLANDI','SIPARIS_VERILDI') and l.status in ('ONAYLANDI','SIPARIS_VERILDI')),
fot as (select max("takenAt") son, count(*) filter (where "takenAt">=current_date) bugun from cfo_snapshot),
log as (select max("changedAt") son from cfo_change_log),
soru as (select count(*) n from cfo_question where answer is not null and "processedAt" is null),
gec as (select count(*) n from cfo_gecikmis_karar), bek as (select count(*) n from cfo_bekleyen_karar),
ters as (select count(*) n from "Product" p where p."unitCostTry" is not null and p."sellingPriceTry" is not null and p."unitCostTry">p."sellingPriceTry"),
stok as (select count(*) n from (select p.sku from "Product" p join (
     select cfo_norm("modelNumber") ns, sum(adet_duz)/90.0 g from cfo_satis_birim_duz
     where "orderDate">=current_date-90 and "modelNumber" is not null group by 1 having sum(adet_duz)>=9) s
   on s.ns=cfo_norm(p.sku) where p."isActive" and p."stockQuantity" is not null and s.g>0 and p."stockQuantity"/s.g<30) x),
gecmis as (select count(*) n, coalesce(sum(coalesce("outflowTry",0)-coalesce("inflowTry",0)),0)::numeric(14,0) tl from cfo_cash_event where "eventDate"::date < current_date and not "isSettled"),
kaps as (select count(*) filter (where p."unitCostTry" is not null) var, count(*) tum from (
   select cfo_norm("modelNumber") ns, row_number() over (order by sum(tutar_duz) desc) r
   from cfo_satis_birim_duz where "orderDate">=current_date-90 and "modelNumber" is not null group by 1) s
   cross join lateral (select pp."unitCostTry" from "Product" pp where cfo_norm(pp.sku)=s.ns order by (pp."unitCostTry" is null), pp."isActive" desc, pp."stockQuantity" desc nulls last limit 1) p where s.r<=50)
select 1,'BILGI','Saat ve gun', to_char((select t from tr),'DD.MM.YYYY HH24:MI')||' TR · '||(array['Pazar','Pazartesi','Sali','Carsamba','Persembe','Cuma','Cumartesi'])[extract(dow from (select t from tr))::int+1],
  'Rotasyon: '||(array['karar kuyrugu','100K aday suzme','olu stok','listeleme kapsami','gorunurluk/SEO','alfashome donusumu','karar kuyrugu'])[extract(dow from (select t from tr))::int+1]||'. Tarihi BURADAN al.'
union all select 2, case when (select son from log)>now()-interval '20 hours' then 'SARI' else 'YESIL' end,'Baska kosu var mi',
  'son log '||coalesce(to_char((select son from log) at time zone 'Europe/Istanbul','DD.MM HH24:MI'),'-'),
  'SARI ise (1) cfo_change_log son 20 kaydini OKU, (2) claude/alfas-cfo-delta-'||to_char((select t from tr),'YYYY-MM-DD')||'.md belgesini project_read ile OKU. O belge VARSA UZERINE YAZMA - altina yeni bolum ekle. 01.09.2026da bir kosu bu belgeyi okumadan ezdi.'
union all select 3, case when (select gecikme from sat)>=2 then 'KIRMIZI' when (select gecikme from sat)=1 then 'SARI' else 'YESIL' end,
  'Satis verisi tazeligi','son kayit '||(select son from sat)||' ('||(select gecikme from sat)||' gun geride)','KIRMIZI ise rakamlari "Eski" etiketle.'
union all select 4, case when (select pay from atf)>=5 then 'KIRMIZI' when (select pay from atf)>=2 then 'SARI' else 'YESIL' end,
  'Atfedilmemis ciro','%'||(select pay from atf)||' ('||(select tl from atf)||' TL)','Birim analizde adet_duz + tutar_duz kullan.'
union all select 5, case when (select n from soru)>0 then 'KIRMIZI' else 'YESIL' end,'Islenmemis cevap',(select n from soru)||' cevap','Rotasyon isinden ONCE isle.'
union all select 6, case when (select n from gec)>0 then 'KIRMIZI' else 'YESIL' end,'Geciken karar',(select n from gec)||' geciken · '||(select n from bek)||' bekleyen','Bugun karara baglanir.'
union all select 7, case when (select nakit_try+girecek_10g-cikacak_10g from nak)<0 then 'KIRMIZI' else 'YESIL' end,'Nakit kapisi (10 gun)',
  'nakit '||round((select nakit_try from nak))||' + girecek '||round((select girecek_10g from nak))||' - cikacak '||round((select cikacak_10g from nak))||' = '||round((select nakit_try+girecek_10g-cikacak_10g from nak))||' TL',
  'Raporda BOS GECILEMEZ. KMH siparis kaynagi sayilmaz.'
union all select 8, case when (select acik_ticari from kyn)<0 then 'KIRMIZI' else 'YESIL' end,
  'KAYNAK YETERLILIGI',
  'ihtiyac '||round(-(select dip from proj))||' TL · ticari kaynak '||round((select kaynak from kyn))||' TL · acik '||round((select acik_ticari from kyn))||' TL',
  'KIRMIZI ise ODEME FIZIKSEL OLARAK YAPILAMAZ. select * from cfo_kaynak_yeterliligi(); Bu tabandan DAHA kritiktir - raporun 1. maddesi.'
union all select 9, case when (select dip from proj)<(select taban from proj) then 'KIRMIZI' else 'YESIL' end,
  'Net pozisyon tabani','dip '||round((select dip from proj))||' TL ('||(select tarih from dipt)||') · taban '||round((select taban from proj))||' TL',
  'KIRMIZI ise cfo_kart_karari() ciktisini UYGULA. Alperene sorma.'
union all select 10, case when (select n_asg from kk)>0 then 'KIRMIZI' when (select n_yetersiz from kk)>0 then 'SARI' else 'YESIL' end,
  'Kart karari','asgariye cekilecek '||(select n_asg from kk)||' kalem'||case when (select n_yetersiz from kk)>0 then ' · kaldirac YETERSIZ' else '' end,
  'KIRMIZI ise uygula. SARI ise kart kaldiraci tukendi - kaldirac merdivenini raporla (olu stok tasfiyesi 7. basamak).'
union all select 11, case when (select n from sip)>0 and (select nakit_try+girecek_10g-cikacak_10g from nak)<0 then 'KIRMIZI' else 'YESIL' end,
  'Nakitsiz onayli siparis',(select n from sip)||' satir','Yurtdisi siparis YALNIZCA nakitle.'
union all select 12, case when (select bugun from fot)=0 then 'KIRMIZI' else 'YESIL' end,'Bugunun fotografi',(select bugun from fot)||' adet','cfo_take_snapshot calistir.'
union all select 13, case when (select n from ters)>0 then 'SARI' else 'YESIL' end,'Maliyet > satis fiyati',(select n from ters)||' urun','Maliyet yanlis eslesmis olabilir.'
union all select 14, case when (select n from stok)>0 then 'KIRMIZI' else 'YESIL' end,'30 gunden az stok',(select n from stok)||' urun','ACIL: bildir. Nakit yoksa siparis verilmez.'
union all select 15, case when (select var from kaps)<(select tum from kaps)*0.9 then 'SARI' else 'YESIL' end,'Maliyet kapsami',(select var||'/'||tum from kaps),'Her kosuda en az 3 eksik maliyet doldurulur. Dropship SKUlarina maliyet YAZILMAZ.'
union all select 16, case when (select n from gecmis)>0 then 'KIRMIZI' else 'YESIL' end,'Gecmis tarihli odenmemis kalem',(select n||' kalem · '||tl||' TL net cikis' from gecmis),'KIRMIZI ise bu kalemler projeksiyondan SESSIZCE dusuyor — dip ihtiyaci oldugundan iyi gorunur. Her birini ya hesap hareketi/Alperen beyani ile isSettled=true yap, ya ILERI TARIHE al. Silme, teyitsiz settle etme. (02.09.2026 dersi: 303.400 TL boyle kaybolmustu.)'
union all select 17,
  case when (select bayat from banka) > 2 then 'KIRMIZI'
       when (select bayat from banka) > 0 then 'SARI' else 'YESIL' end,
  'Banka bakiyesi tazeligi',
  (select n from banka)||' hesap 2 gunden bayat · en eskisi '||(select bayat from banka)||' gun',
  'Bakiye bayatsa nakit ve bos KMH GERCEGINDEN IYI gorunur: yapilan bir odeme KMHden cikmissa defterde hic gorunmez. KIRMIZI ise nakit_try ve bos_kmh_try rakamlarini "Eski" etiketle, kaynak yeterliligi sonucunu KESIN sunma, Alperenden guncel bakiye iste. (05.09.2026 dersi: 04.09da 270.900 TL odendi, defter 03.09da duruyordu.)'
union all select 18,
  case when (select count(*) from cfo_receivable where not "isCollected" and "dueDate"::date < current_date) > 0 then 'KIRMIZI' else 'YESIL' end,
  'Vadesi gecmis tahsil edilmemis alacak',
  (select count(*)||' kalem · '||coalesce(sum("amountTry"),0)::numeric(14,0)||' TL · en eskisi '||coalesce(max(current_date - "dueDate"::date),0)||' gun' from cfo_receivable where not "isCollected" and "dueDate"::date < current_date),
  'KIRMIZI ise bu tutar ya TAHSIL EDILDI ve banka bakiyesine yazilmadi (cift sayim), ya da GERCEKTEN gelmedi (tahsilat sorunu). Ikisi de nakit kapisini iyimser gosterir. Her kalemi hesap hareketi/Alperen beyani ile isCollected=true yap ya da yeni vadeye al. Silme. (07.09.2026 dersi: 210.821 TL, 6-13 gun gecikmis, girecek_10g icinde GELECEK giris sayiliyordu.)'
order by 1;
$function$
;

CREATE OR REPLACE FUNCTION public.cfo_onucus_v19()
 RETURNS TABLE(sira integer, seviye text, kontrol text, deger text, ne_yapmali text)
 LANGUAGE sql
 STABLE
AS $function$
  select * from cfo_onucus_temel()
  union all
  select 19,
    case
      when (select count(*) from cfo_dead_stock_finding
            where status not in ('kapandi','gecersiz') and alarm='KIRMIZI'
              and action_taken is null and current_date - found_at > 21) > 0 then 'KIRMIZI'
      when (select count(*) from cfo_dead_stock_finding
            where status not in ('kapandi','gecersiz')
              and next_review_at is not null and next_review_at < current_date) > 0 then 'KIRMIZI'
      else 'YESIL' end,
    'Olu stok kontrol kuyrugu',
    (select 'kontrol vakti gelen ' || count(*) filter (where next_review_at <= current_date)
       || ' · KIRMIZI ' || count(*) filter (where alarm='KIRMIZI')
       || ' · SARI ' || count(*) filter (where alarm='SARI')
       || ' · 21 gunden eski aksiyonsuz KIRMIZI ' ||
          count(*) filter (where alarm='KIRMIZI' and action_taken is null and current_date-found_at>21)
       || ' · toplam bagli ' || coalesce(sum(tied_capital_try),0)::numeric(14,0) || ' TL'
     from cfo_dead_stock_finding where status not in ('kapandi','gecersiz')),
    'Iki tetikleyici var. (1) Kontrol tarihi gecmis bulgu: "select * from cfo_olu_stok where kontrol_gecikti order by bagli_sermaye desc" — her satirin kontrol_notu ne yapilacagini yazar. (2) YAS GUARDI: 21 gunden eski, hala hicbir aksiyon alinmamis KIRMIZI bulgu. Bu ikincisi next_review_at ileri atilarak susturulamaz — bulgu ancak action_taken yazilinca susar. Amac: olu stogu temizleyip yerine SATAN urun koymak; erteleme tek basina cozum degildir.'
  order by 1;
$function$
;

CREATE OR REPLACE FUNCTION public.cfo_sicrama_kapat(p_id bigint, p_durum text, p_aciklama text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
begin
  update cfo_stok_sicrama set durum = p_durum, aciklama = p_aciklama, kapandi_at = now() where id = p_id;
  insert into cfo_change_log(id, area, kind, item, "oldValue", "newValue", note, "changedAt")
  select gen_random_uuid()::text, 'stok', 'teyit', 'Stok sicramasi kapandi: '||sku||' '||delta, 'ACIK', p_durum, p_aciklama, now()
  from cfo_stok_sicrama where id = p_id;
  return 'ok';
end $function$
;

CREATE OR REPLACE FUNCTION public.cfo_stok_sicrama_kaydet(p_log_id text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare r record; v_med numeric; v_neden text;
begin
  select l.id, l."productId", l."previousQty", l."newQty", l.delta, l."syncedAt", p.sku, p.name
    into r
  from "XmlStockChangeLog" l join "Product" p on p.id = l."productId"
  where l.id = p_log_id;
  if r.id is null or r.delta > -5 then return; end if;

  select greatest(coalesce(percentile_cont(0.5) within group (order by -x.delta), 1), 1)
    into v_med
  from "XmlStockChangeLog" x
  where x."productId" = r."productId" and x.delta < 0 and x.delta >= -100 and x.id <> r.id
    and x."syncedAt" between r."syncedAt" - interval '90 days' and r."syncedAt";

  v_neden := concat_ws(' + ',
    case when -r.delta >= 3 * v_med then 'normalin '||round(-r.delta / v_med,1)||' kati' end,
    case when r."previousQty" > 0 and -r.delta >= 0.5 * r."previousQty" then 'stogun %'||round(100.0 * -r.delta / r."previousQty")||'i' end,
    case when r.delta < -100 then 'TOPLU (>100)' end);
  if v_neden is null or v_neden = '' then return; end if;

  insert into cfo_stok_sicrama(xml_log_id, product_id, sku, urun, synced_at, onceki, yeni, delta,
                               esik_nedeni, medyan_dusus, entegra_degisim_zamani)
  select r.id, r."productId", r.sku, r.name, r."syncedAt", r."previousQty", r."newQty", r.delta,
         v_neden, v_med, (select d."xmlDateChange" from "XmlProductData" d where d."productId" = r."productId" limit 1)
  on conflict (xml_log_id) do nothing;
end $function$
;

CREATE OR REPLACE FUNCTION public.cfo_stok_sicrama_trg()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  begin
    if NEW.delta <= -5 then perform cfo_stok_sicrama_kaydet(NEW.id); end if;
  exception when others then null;  -- XML senkronunu ASLA bozma
  end;
  return NEW;
end $function$
;

CREATE OR REPLACE FUNCTION public.cfo_take_snapshot(p_note text DEFAULT NULL::text)
 RETURNS cfo_snapshot
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_usd NUMERIC; v_cash NUMERIC; v_recv NUMERIC; v_stok NUMERIC;
  v_yolda NUMERIC; v_kredi NUMERIC; v_kart NUMERIC; v_yolda_borc NUMERIC;
  v_narrow NUMERIC; v_wide NUMERIC; v_row "cfo_snapshot";
BEGIN
  SELECT COALESCE(NULLIF("usdTryRate", 0), 1) INTO v_usd FROM "cfo_settings" LIMIT 1;
  IF v_usd IS NULL THEN v_usd := 1; END IF;

  SELECT
    COALESCE(SUM(tutar) FILTER (WHERE sira = 1), 0),
    COALESCE(SUM(tutar) FILTER (WHERE sira = 2), 0),
    COALESCE(SUM(tutar) FILTER (WHERE sira IN (3,4)), 0),
    COALESCE(SUM(tutar) FILTER (WHERE sira IN (5,6)), 0),
    COALESCE(-SUM(tutar) FILTER (WHERE sira = 7), 0),
    COALESCE(-SUM(tutar) FILTER (WHERE sira = 8), 0),
    COALESCE(-SUM(tutar) FILTER (WHERE sira = 9), 0)
  INTO v_cash, v_recv, v_stok, v_yolda, v_kredi, v_kart, v_yolda_borc
  FROM "cfo_servet_kalem";

  -- DAR: yoldaki mal haric (ne varligi ne borcu)
  v_narrow := v_cash + v_recv + v_stok - v_kredi - v_kart;
  -- GENIS: yoldaki mal iki tarafa birden (§4E kural 4)
  v_wide   := v_narrow + v_yolda - v_yolda_borc;

  INSERT INTO "cfo_snapshot" ("id","takenAt","netWorthTry","netWorthUsd","wideWorthTry",
      "wideWorthUsd","cashTry","receivablesTry","stockTry","debtTry","usdTryRate","note")
  VALUES (gen_random_uuid()::text, now(),
      round(v_narrow,2), round(v_narrow/v_usd,2), round(v_wide,2), round(v_wide/v_usd,2),
      round(v_cash,2), round(v_recv,2), round(v_stok + v_yolda,2),
      round(v_kredi + v_kart + v_yolda_borc,2), v_usd, p_note)
  RETURNING * INTO v_row;
  RETURN v_row;
END $function$
;

CREATE OR REPLACE FUNCTION public.cfo_xml_urun_degisim_trg()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare v_sku text;
begin
  begin
    select sku into v_sku from "Product" where id = NEW."productId";
    if TG_OP = 'INSERT' then
      insert into cfo_xml_urun_degisim(product_id, sku, alan, eski, yeni, entegra_degisim_zamani)
      values (NEW."productId", coalesce(v_sku, NEW."xmlSku"), 'YENI_URUN_FEEDDE', null, NEW."xmlName", NEW."xmlDateChange");
      return NEW;
    end if;
    if NEW."xmlDateChange" is distinct from OLD."xmlDateChange" then
      insert into cfo_xml_urun_degisim(product_id, sku, alan, eski, yeni, entegra_degisim_zamani)
      values (NEW."productId", coalesce(v_sku, NEW."xmlSku"), 'ENTEGRA_KAYIT_DEGISTI', OLD."xmlDateChange", NEW."xmlDateChange", NEW."xmlDateChange");
    end if;
    if NEW."xmlTrendyolPrice" is distinct from OLD."xmlTrendyolPrice" then
      insert into cfo_xml_urun_degisim(product_id, sku, alan, eski, yeni, entegra_degisim_zamani)
      values (NEW."productId", coalesce(v_sku, NEW."xmlSku"), 'FIYAT_TRENDYOL', OLD."xmlTrendyolPrice"::text, NEW."xmlTrendyolPrice"::text, NEW."xmlDateChange");
    end if;
    if NEW."xmlHbPrice" is distinct from OLD."xmlHbPrice" then
      insert into cfo_xml_urun_degisim(product_id, sku, alan, eski, yeni, entegra_degisim_zamani)
      values (NEW."productId", coalesce(v_sku, NEW."xmlSku"), 'FIYAT_HB', OLD."xmlHbPrice"::text, NEW."xmlHbPrice"::text, NEW."xmlDateChange");
    end if;
    if NEW."xmlAmazonPrice" is distinct from OLD."xmlAmazonPrice" then
      insert into cfo_xml_urun_degisim(product_id, sku, alan, eski, yeni, entegra_degisim_zamani)
      values (NEW."productId", coalesce(v_sku, NEW."xmlSku"), 'FIYAT_AMAZON', OLD."xmlAmazonPrice"::text, NEW."xmlAmazonPrice"::text, NEW."xmlDateChange");
    end if;
    if NEW."xmlPrice4" is distinct from OLD."xmlPrice4" then
      insert into cfo_xml_urun_degisim(product_id, sku, alan, eski, yeni, entegra_degisim_zamani)
      values (NEW."productId", coalesce(v_sku, NEW."xmlSku"), 'FIYAT_4', OLD."xmlPrice4"::text, NEW."xmlPrice4"::text, NEW."xmlDateChange");
    end if;
    if NEW."xmlName" is distinct from OLD."xmlName" then
      insert into cfo_xml_urun_degisim(product_id, sku, alan, eski, yeni, entegra_degisim_zamani)
      values (NEW."productId", coalesce(v_sku, NEW."xmlSku"), 'URUN_ADI', OLD."xmlName", NEW."xmlName", NEW."xmlDateChange");
    end if;
    if NEW."missingFromLatestFeed" is distinct from OLD."missingFromLatestFeed" then
      insert into cfo_xml_urun_degisim(product_id, sku, alan, eski, yeni, entegra_degisim_zamani)
      values (NEW."productId", coalesce(v_sku, NEW."xmlSku"),
              case when NEW."missingFromLatestFeed" then 'FEEDDEN_DUSTU' else 'FEEDE_GERI_DONDU' end,
              OLD."missingFromLatestFeed"::text, NEW."missingFromLatestFeed"::text, NEW."xmlDateChange");
    end if;
  exception when others then
    -- XML senkronunu ASLA bozma
    null;
  end;
  return NEW;
end $function$
;

CREATE OR REPLACE FUNCTION public.fm_backfill_sales_month(p_run uuid, p_month date, p_dry boolean DEFAULT false, p_today date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  m_end date := (p_month + interval '1 month')::date;
  sku_day_from date := p_today - 400;
  st_rev numeric; st_units numeric; st_rows bigint; st_orders bigint;
  w_company int := 0; w_channel int := 0; w_sku int := 0; w_skuday int := 0;
  chk_company numeric; chk_channel numeric; chk_sku numeric; chk_units numeric;
BEGIN
  IF p_month <> date_trunc('month', p_month)::date THEN RAISE EXCEPTION 'p_month ayın ilk günü olmalı: %', p_month; END IF;
  SELECT count(*), coalesce(sum(revenue_incl_vat_try) FILTER (WHERE disposition = 'COUNTED'), 0),
         coalesce(sum(units_counted) FILTER (WHERE disposition = 'COUNTED'), 0),
         count(DISTINCT channel || '|' || order_key) FILTER (WHERE disposition = 'COUNTED')
    INTO st_rows, st_rev, st_units, st_orders
  FROM public.fm_sales_canonical_snapshot WHERE economic_date >= p_month AND economic_date < m_end;
  IF p_dry THEN
    RETURN jsonb_build_object('month', p_month, 'dry_run', true, 'stage_rows', st_rows, 'revenue_incl_vat_try', st_rev,
                              'units', st_units, 'orders', st_orders);
  END IF;
  UPDATE public.fm_sales_company_day SET is_current = false WHERE economic_date >= p_month AND economic_date < m_end AND is_current;
  UPDATE public.fm_sales_channel_month SET is_current = false WHERE month = p_month AND is_current;
  UPDATE public.fm_sales_sku_month SET is_current = false WHERE month = p_month AND is_current;
  UPDATE public.fm_sales_sku_day SET is_current = false WHERE economic_date >= p_month AND economic_date < m_end AND is_current;
  WITH base AS (
    SELECT * FROM public.fm_sales_canonical_snapshot WHERE economic_date >= p_month AND economic_date < m_end
  ), flags AS (
    SELECT b.economic_date, array_agg(DISTINCT f ORDER BY f) AS flags
    FROM base b, unnest(b.quality_flags) f WHERE b.disposition = 'COUNTED' GROUP BY b.economic_date
  ), agg AS (
    SELECT economic_date,
      coalesce(sum(revenue_incl_vat_try) FILTER (WHERE disposition = 'COUNTED'), 0) AS revenue,
      CASE WHEN bool_and(amount_ex_vat_try IS NOT NULL) FILTER (WHERE disposition = 'COUNTED') THEN sum(amount_ex_vat_try) FILTER (WHERE disposition = 'COUNTED') END AS ex_vat,
      CASE WHEN bool_and(vat_try IS NOT NULL) FILTER (WHERE disposition = 'COUNTED') THEN sum(vat_try) FILTER (WHERE disposition = 'COUNTED') END AS vat,
      coalesce(bool_or(amount_ex_vat_try IS NOT NULL) FILTER (WHERE disposition = 'COUNTED') AND NOT bool_and(amount_ex_vat_try IS NOT NULL) FILTER (WHERE disposition = 'COUNTED'), false) AS ex_partial,
      coalesce(sum(revenue_incl_vat_try) FILTER (WHERE disposition = 'COUNTED' AND legacy_business IS NOT NULL), 0) AS legacy,
      coalesce(sum(units_counted) FILTER (WHERE disposition = 'COUNTED'), 0) AS units,
      count(DISTINCT channel || '|' || order_key) FILTER (WHERE disposition = 'COUNTED') AS orders,
      count(DISTINCT channel || '|' || order_key) FILTER (WHERE disposition = 'EXCLUDED_RETURN') AS ret,
      count(DISTINCT channel || '|' || order_key) FILTER (WHERE disposition = 'EXCLUDED_CANCELLED') AS canc,
      min(known_at) AS kmin, max(known_at) AS kmax
    FROM base GROUP BY economic_date
  )
  INSERT INTO public.fm_sales_company_day (economic_date, revenue_incl_vat_try, revenue_ex_vat_try, vat_try, revenue_legacy_textile_try, units, orders,
      return_signal_orders, cancel_signal_orders, known_at_min, known_at_max, flags, ingest_run_id)
  SELECT a.economic_date, a.revenue, a.ex_vat, a.vat, a.legacy, a.units, a.orders, a.ret, a.canc, a.kmin, a.kmax,
         CASE WHEN a.ex_partial THEN array_append(coalesce(f.flags, '{}'), 'ex_vat_partial') ELSE coalesce(f.flags, '{}') END, p_run
  FROM agg a LEFT JOIN flags f USING (economic_date)
  ON CONFLICT (economic_date) DO UPDATE SET revenue_incl_vat_try = EXCLUDED.revenue_incl_vat_try, revenue_ex_vat_try = EXCLUDED.revenue_ex_vat_try, vat_try = EXCLUDED.vat_try, revenue_legacy_textile_try = EXCLUDED.revenue_legacy_textile_try, units = EXCLUDED.units, orders = EXCLUDED.orders, return_signal_orders = EXCLUDED.return_signal_orders, cancel_signal_orders = EXCLUDED.cancel_signal_orders, known_at_min = EXCLUDED.known_at_min, known_at_max = EXCLUDED.known_at_max, flags = EXCLUDED.flags, ingest_run_id = EXCLUDED.ingest_run_id, is_current = true;
  GET DIAGNOSTICS w_company = ROW_COUNT;
  WITH base AS (
    SELECT * FROM public.fm_sales_canonical_snapshot WHERE economic_date >= p_month AND economic_date < m_end
  ), flags AS (
    SELECT b.channel, array_agg(DISTINCT f ORDER BY f) AS flags
    FROM base b, unnest(b.quality_flags) f WHERE b.disposition = 'COUNTED' GROUP BY b.channel
  ), agg AS (
    SELECT channel,
      coalesce(sum(revenue_incl_vat_try) FILTER (WHERE disposition = 'COUNTED'), 0) AS revenue,
      CASE WHEN bool_and(amount_ex_vat_try IS NOT NULL) FILTER (WHERE disposition = 'COUNTED') THEN sum(amount_ex_vat_try) FILTER (WHERE disposition = 'COUNTED') END AS ex_vat,
      CASE WHEN bool_and(vat_try IS NOT NULL) FILTER (WHERE disposition = 'COUNTED') THEN sum(vat_try) FILTER (WHERE disposition = 'COUNTED') END AS vat,
      coalesce(bool_or(amount_ex_vat_try IS NOT NULL) FILTER (WHERE disposition = 'COUNTED') AND NOT bool_and(amount_ex_vat_try IS NOT NULL) FILTER (WHERE disposition = 'COUNTED'), false) AS ex_partial,
      coalesce(sum(revenue_incl_vat_try) FILTER (WHERE disposition = 'COUNTED' AND legacy_business IS NOT NULL), 0) AS legacy,
      coalesce(sum(units_counted) FILTER (WHERE disposition = 'COUNTED'), 0) AS units,
      count(DISTINCT order_key) FILTER (WHERE disposition = 'COUNTED') AS orders,
      count(DISTINCT order_key) FILTER (WHERE disposition = 'EXCLUDED_RETURN') AS ret,
      count(DISTINCT order_key) FILTER (WHERE disposition = 'EXCLUDED_CANCELLED') AS canc,
      min(known_at) AS kmin, max(known_at) AS kmax
    FROM base GROUP BY channel
  )
  INSERT INTO public.fm_sales_channel_month (month, channel, revenue_incl_vat_try, revenue_ex_vat_try, vat_try, revenue_legacy_textile_try, units, orders,
      return_signal_orders, cancel_signal_orders, known_at_min, known_at_max, flags, ingest_run_id)
  SELECT p_month, a.channel, a.revenue, a.ex_vat, a.vat, a.legacy, a.units, a.orders, a.ret, a.canc, a.kmin, a.kmax,
         CASE WHEN a.ex_partial THEN array_append(coalesce(f.flags, '{}'), 'ex_vat_partial') ELSE coalesce(f.flags, '{}') END, p_run
  FROM agg a LEFT JOIN flags f USING (channel)
  ON CONFLICT (month, channel) DO UPDATE SET revenue_incl_vat_try = EXCLUDED.revenue_incl_vat_try, revenue_ex_vat_try = EXCLUDED.revenue_ex_vat_try, vat_try = EXCLUDED.vat_try, revenue_legacy_textile_try = EXCLUDED.revenue_legacy_textile_try, units = EXCLUDED.units, orders = EXCLUDED.orders, return_signal_orders = EXCLUDED.return_signal_orders, cancel_signal_orders = EXCLUDED.cancel_signal_orders, known_at_min = EXCLUDED.known_at_min, known_at_max = EXCLUDED.known_at_max, flags = EXCLUDED.flags, ingest_run_id = EXCLUDED.ingest_run_id, is_current = true;
  GET DIAGNOSTICS w_channel = ROW_COUNT;
  WITH base AS (
    SELECT s.*, CASE WHEN s.product_id IS NOT NULL THEN 'P:' || s.product_id
                     WHEN s.sku_raw IS NOT NULL THEN 'R:' || public.cfo_norm(s.sku_raw) ELSE 'R:(none)' END AS sku_key
    FROM public.fm_sales_canonical_snapshot s
    WHERE s.economic_date >= p_month AND s.economic_date < m_end AND s.disposition = 'COUNTED'
  ), flags AS (
    SELECT b.sku_key, array_agg(DISTINCT f ORDER BY f) AS flags FROM base b, unnest(b.quality_flags) f GROUP BY b.sku_key
  ), agg AS (
    SELECT sku_key, max(product_id) AS product_id, mode() WITHIN GROUP (ORDER BY sku_raw) AS label, bool_or(product_id IS NOT NULL) AS mapped,
      max(legacy_business) AS legacy_business, sum(revenue_incl_vat_try) AS revenue,
      CASE WHEN bool_and(amount_ex_vat_try IS NOT NULL) THEN sum(amount_ex_vat_try) END AS ex_vat,
      sum(units_counted) AS units, count(DISTINCT channel || '|' || order_key) AS orders, max(known_at) AS kmax
    FROM base GROUP BY sku_key
  )
  INSERT INTO public.fm_sales_sku_month (month, sku_key, product_id, sku_label, sku_mapped, legacy_business, revenue_incl_vat_try, revenue_ex_vat_try,
      units, orders, known_at_max, flags, ingest_run_id)
  SELECT p_month, a.sku_key, a.product_id, a.label, a.mapped, a.legacy_business, a.revenue, a.ex_vat, a.units, a.orders, a.kmax, coalesce(f.flags, '{}'), p_run
  FROM agg a LEFT JOIN flags f USING (sku_key)
  ON CONFLICT (month, sku_key) DO UPDATE SET product_id = EXCLUDED.product_id, sku_label = EXCLUDED.sku_label, sku_mapped = EXCLUDED.sku_mapped, legacy_business = EXCLUDED.legacy_business, revenue_incl_vat_try = EXCLUDED.revenue_incl_vat_try, revenue_ex_vat_try = EXCLUDED.revenue_ex_vat_try, units = EXCLUDED.units, orders = EXCLUDED.orders, known_at_max = EXCLUDED.known_at_max, flags = EXCLUDED.flags, ingest_run_id = EXCLUDED.ingest_run_id, is_current = true;
  GET DIAGNOSTICS w_sku = ROW_COUNT;
  IF m_end > sku_day_from THEN
    WITH base AS (
      SELECT s.*, CASE WHEN s.product_id IS NOT NULL THEN 'P:' || s.product_id
                       WHEN s.sku_raw IS NOT NULL THEN 'R:' || public.cfo_norm(s.sku_raw) ELSE 'R:(none)' END AS sku_key
      FROM public.fm_sales_canonical_snapshot s
      WHERE s.economic_date >= greatest(p_month, sku_day_from) AND s.economic_date < m_end AND s.disposition = 'COUNTED'
    ), flags AS (
      SELECT b.economic_date, b.sku_key, array_agg(DISTINCT f ORDER BY f) AS flags FROM base b, unnest(b.quality_flags) f GROUP BY b.economic_date, b.sku_key
    ), agg AS (
      SELECT economic_date, sku_key, max(product_id) AS product_id, mode() WITHIN GROUP (ORDER BY sku_raw) AS label, bool_or(product_id IS NOT NULL) AS mapped,
        max(legacy_business) AS legacy_business, sum(revenue_incl_vat_try) AS revenue, sum(units_counted) AS units,
        count(DISTINCT channel || '|' || order_key) AS orders, max(known_at) AS kmax
      FROM base GROUP BY economic_date, sku_key
    )
    INSERT INTO public.fm_sales_sku_day (economic_date, sku_key, product_id, sku_label, sku_mapped, legacy_business, revenue_incl_vat_try, units, orders,
        known_at_max, flags, ingest_run_id)
    SELECT a.economic_date, a.sku_key, a.product_id, a.label, a.mapped, a.legacy_business, a.revenue, a.units, a.orders, a.kmax, coalesce(f.flags, '{}'), p_run
    FROM agg a LEFT JOIN flags f USING (economic_date, sku_key)
  ON CONFLICT (economic_date, sku_key) DO UPDATE SET product_id = EXCLUDED.product_id, sku_label = EXCLUDED.sku_label, sku_mapped = EXCLUDED.sku_mapped, legacy_business = EXCLUDED.legacy_business, revenue_incl_vat_try = EXCLUDED.revenue_incl_vat_try, units = EXCLUDED.units, orders = EXCLUDED.orders, known_at_max = EXCLUDED.known_at_max, flags = EXCLUDED.flags, ingest_run_id = EXCLUDED.ingest_run_id, is_current = true;
    GET DIAGNOSTICS w_skuday = ROW_COUNT;
  END IF;
  SELECT coalesce(sum(revenue_incl_vat_try), 0), coalesce(sum(units), 0) INTO chk_company, chk_units
    FROM public.fm_sales_company_day WHERE economic_date >= p_month AND economic_date < m_end AND is_current;
  SELECT coalesce(sum(revenue_incl_vat_try), 0) INTO chk_channel FROM public.fm_sales_channel_month WHERE month = p_month AND is_current;
  SELECT coalesce(sum(revenue_incl_vat_try), 0) INTO chk_sku FROM public.fm_sales_sku_month WHERE month = p_month AND is_current;
  IF chk_company <> st_rev OR chk_channel <> st_rev OR chk_sku <> st_rev OR chk_units <> st_units THEN
    RAISE EXCEPTION 'fm backfill mutabakat hatası % : snapshot % / gün % / kanal % / sku % ; adet snapshot % / gün %',
      p_month, st_rev, chk_company, chk_channel, chk_sku, st_units, chk_units;
  END IF;
  RETURN jsonb_build_object('month', p_month, 'dry_run', false, 'stage_rows', st_rows, 'revenue_incl_vat_try', st_rev, 'units', st_units, 'orders', st_orders,
                            'company_day_rows', w_company, 'channel_month_rows', w_channel, 'sku_month_rows', w_sku, 'sku_day_rows', w_skuday);
END
$function$
;

CREATE OR REPLACE FUNCTION public.fm_backfill_sales_run(p_run uuid, p_from date, p_to date, p_max_chunks integer DEFAULT 12, p_dry boolean DEFAULT false, p_today date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  m date := date_trunc('month', p_from)::date;
  last_m date := date_trunc('month', p_to)::date;
  done_n int := 0; skipped int := 0; res jsonb; results jsonb := '[]'::jsonb; failed jsonb := NULL;
BEGIN
  WHILE m <= last_m AND done_n < p_max_chunks LOOP
    IF NOT p_dry AND EXISTS (SELECT 1 FROM public.fm_ingest_chunk WHERE run_id = p_run AND chunk = m::text AND status = 'succeeded') THEN
      skipped := skipped + 1;
    ELSE
      BEGIN
        res := public.fm_backfill_sales_month(p_run, m, p_dry, p_today);
        IF NOT p_dry THEN
          INSERT INTO public.fm_ingest_chunk (run_id, chunk, status, rows_written, revenue_incl_vat_try)
          VALUES (p_run, m::text, 'succeeded', coalesce((res->>'company_day_rows')::int, 0) + coalesce((res->>'channel_month_rows')::int, 0)
                  + coalesce((res->>'sku_month_rows')::int, 0) + coalesce((res->>'sku_day_rows')::int, 0), (res->>'revenue_incl_vat_try')::numeric)
          ON CONFLICT (run_id, chunk) DO UPDATE SET status = 'succeeded', rows_written = EXCLUDED.rows_written,
            revenue_incl_vat_try = EXCLUDED.revenue_incl_vat_try, error = NULL, done_at = now();
        END IF;
        results := results || jsonb_build_array(res);
        done_n := done_n + 1;
      EXCEPTION WHEN OTHERS THEN
        failed := jsonb_build_object('month', m, 'error', SQLERRM);
        INSERT INTO public.fm_ingest_chunk (run_id, chunk, status, error) VALUES (p_run, m::text, 'failed', SQLERRM)
          ON CONFLICT (run_id, chunk) DO UPDATE SET status = 'failed', error = EXCLUDED.error, done_at = now();
        EXIT;
      END;
    END IF;
    m := (m + interval '1 month')::date;
  END LOOP;
  RETURN jsonb_build_object('processed', done_n, 'skipped_done', skipped, 'next_month', CASE WHEN m <= last_m THEN m END,
                            'finished', failed IS NULL AND m > last_m, 'failed', failed, 'chunks', results);
END
$function$
;

CREATE OR REPLACE FUNCTION public.fm_backfill_sales_snapshot(p_run uuid)
 RETURNS bigint
 LANGUAGE plpgsql
AS $function$
DECLARE n bigint;
BEGIN
  REFRESH MATERIALIZED VIEW public.fm_sales_canonical_snapshot;
  SELECT count(*) INTO n FROM public.fm_sales_canonical_snapshot;
  UPDATE public.fm_ingest_run
     SET lineage = lineage || jsonb_build_object('snapshot_rows', n, 'snapshot_refreshed_at', now())
   WHERE id = p_run;
  RETURN n;
END
$function$
;

CREATE OR REPLACE FUNCTION public.fm_balance_refresh(p_v2_from date DEFAULT '2026-09-11'::date)
 RETURNS bigint
 LANGUAGE plpgsql
AS $function$
DECLARE n bigint;
BEGIN
  INSERT INTO public.fm_balance_day (economic_date, metric_key, definition_version, value_try, source, known_at)
  SELECT s.d, m.metric_key, 2, m.v, 'cfo_snapshot', s.known_at
  FROM (SELECT DISTINCT ON ("takenAt"::date) "takenAt"::date AS d, "takenAt" AS known_at, "cashTry", "debtTry", "receivablesTry", "netWorthTry", "stockTry"
        FROM public.cfo_snapshot WHERE "takenAt"::date >= p_v2_from ORDER BY "takenAt"::date, "takenAt" DESC) s
  CROSS JOIN LATERAL (VALUES ('cash_try', s."cashTry"), ('debt_try', s."debtTry"), ('receivables_try', s."receivablesTry"),
                             ('net_capital_try', s."netWorthTry"), ('inventory_value_try', s."stockTry")) AS m(metric_key, v)
  WHERE m.v IS NOT NULL
  ON CONFLICT (economic_date, metric_key, definition_version) DO UPDATE SET value_try = EXCLUDED.value_try,
    source = EXCLUDED.source, known_at = EXCLUDED.known_at;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END
$function$
;

CREATE OR REPLACE FUNCTION public.fm_grade(p_metric text, p_channel text, p_date date)
 RETURNS character
 LANGUAGE sql
 STABLE
AS $function$
  SELECT coalesce((
    SELECT q.grade FROM public.fm_quality_policy q
    WHERE q.metric_key = p_metric AND q.channel IN (p_channel, '*')
      AND q.valid_from <= p_date AND (q.valid_to IS NULL OR q.valid_to >= p_date)
    ORDER BY (q.channel = p_channel) DESC, q.valid_from DESC
    LIMIT 1
  ), 'U')::char(1)
$function$
;

CREATE OR REPLACE FUNCTION public.fm_grade_month(p_metric text, p_channel text, p_month date)
 RETURNS character
 LANGUAGE sql
 STABLE
AS $function$
  SELECT greatest(public.fm_grade(p_metric, p_channel, p_month),
                  public.fm_grade(p_metric, p_channel, (p_month + interval '1 month - 1 day')::date))::char(1)
$function$
;

CREATE OR REPLACE FUNCTION public.fm_stock_refresh()
 RETURNS TABLE(sku_day_rows bigint, company_day_rows bigint)
 LANGUAGE plpgsql
AS $function$
DECLARE a bigint; b bigint;
BEGIN
  INSERT INTO public.fm_stock_sku_day (product_id, economic_date, sku, units_eod, units_open, change_count, known_at_max)
  SELECT l."productId", l."syncedAt"::date, max(p.sku),
         (array_agg(l."newQty" ORDER BY l."syncedAt" DESC, l.id DESC))[1],
         (array_agg(l."previousQty" ORDER BY l."syncedAt" ASC, l.id ASC))[1],
         count(*)::int, max(l."syncedAt")
  FROM public."XmlStockChangeLog" l LEFT JOIN public."Product" p ON p.id = l."productId"
  GROUP BY l."productId", l."syncedAt"::date
  ON CONFLICT (product_id, economic_date) DO UPDATE SET sku = EXCLUDED.sku, units_eod = EXCLUDED.units_eod,
    units_open = EXCLUDED.units_open, change_count = EXCLUDED.change_count, known_at_max = EXCLUDED.known_at_max;
  GET DIAGNOSTICS a = ROW_COUNT;
  INSERT INTO public.fm_stock_company_day (economic_date, units_total_logged, products_logged, products_changed)
  SELECT d.day,
         sum(coalesce(last_eod.units_eod, first_open.units_open))::bigint,
         count(*)::int,
         count(chg.product_id)::int
  FROM (SELECT generate_series(min(economic_date), max(economic_date), interval '1 day')::date AS day FROM public.fm_stock_sku_day) d
  JOIN (SELECT product_id, min(economic_date) AS first_day FROM public.fm_stock_sku_day GROUP BY product_id) fp ON fp.first_day <= d.day
  LEFT JOIN LATERAL (SELECT units_eod FROM public.fm_stock_sku_day s WHERE s.product_id = fp.product_id AND s.economic_date <= d.day
                     ORDER BY s.economic_date DESC LIMIT 1) last_eod ON true
  LEFT JOIN LATERAL (SELECT units_open FROM public.fm_stock_sku_day s WHERE s.product_id = fp.product_id
                     ORDER BY s.economic_date ASC LIMIT 1) first_open ON true
  LEFT JOIN public.fm_stock_sku_day chg ON chg.product_id = fp.product_id AND chg.economic_date = d.day
  GROUP BY d.day
  ON CONFLICT (economic_date) DO UPDATE SET units_total_logged = EXCLUDED.units_total_logged,
    products_logged = EXCLUDED.products_logged, products_changed = EXCLUDED.products_changed;
  GET DIAGNOSTICS b = ROW_COUNT;
  RETURN QUERY SELECT a, b;
END
$function$
;

CREATE OR REPLACE FUNCTION public.fm_stock_refresh_after_sync(p_sync_log_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  s record;
  run_id uuid;
  r record;
  recon jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('fm_stock_refresh'));
  SELECT l.id, l.status::text AS status, l."completedAt" AS completed_at INTO s FROM public."XmlSyncLog" l WHERE l.id = p_sync_log_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('refreshed', false, 'reason', 'sync_log_not_found');
  END IF;
  IF EXISTS (SELECT 1 FROM public.fm_ingest_run WHERE kind = 'stock_refresh' AND status = 'succeeded' AND lineage ->> 'sync_log_id' = p_sync_log_id) THEN
    RETURN jsonb_build_object('refreshed', false, 'reason', 'already_refreshed', 'sync_log_id', p_sync_log_id);
  END IF;
  IF s.status <> 'SUCCESS' OR s.completed_at IS NULL THEN
    INSERT INTO public.fm_ingest_run (kind, status, finished_at, lineage)
    VALUES ('stock_refresh', 'failed', now(), jsonb_build_object('sync_log_id', p_sync_log_id, 'reason', 'sync_not_success', 'sync_status', s.status));
    RETURN jsonb_build_object('refreshed', false, 'reason', 'sync_not_success', 'sync_status', s.status);
  END IF;

  INSERT INTO public.fm_ingest_run (kind, status, lineage)
  VALUES ('stock_refresh', 'running', jsonb_build_object('sync_log_id', p_sync_log_id, 'sync_status', s.status))
  RETURNING id INTO run_id;
  BEGIN
    SELECT * INTO r FROM public.fm_stock_refresh();
    SELECT coalesce(jsonb_object_agg(x.status, x.n), '{}'::jsonb) INTO recon
      FROM (SELECT status, count(*) AS n FROM public.fm_stock_reconciliation GROUP BY status) x;
    UPDATE public.fm_ingest_run
       SET status = 'succeeded', finished_at = now(), rows_written = r.sku_day_rows + r.company_day_rows,
           range_from = (SELECT min(economic_date) FROM public.fm_stock_company_day), range_to = (SELECT max(economic_date) FROM public.fm_stock_company_day),
           lineage = lineage || jsonb_build_object('sku_day_rows', r.sku_day_rows, 'company_day_rows', r.company_day_rows, 'reconciliation', recon)
     WHERE id = run_id;
    RETURN jsonb_build_object('refreshed', true, 'run_id', run_id, 'sync_log_id', p_sync_log_id, 'sku_day_rows', r.sku_day_rows,
                              'company_day_rows', r.company_day_rows, 'reconciliation', recon);
  EXCEPTION WHEN OTHERS THEN
    UPDATE public.fm_ingest_run SET status = 'failed', finished_at = now(), lineage = lineage || jsonb_build_object('reason', 'refresh_error', 'error', SQLERRM) WHERE id = run_id;
    RETURN jsonb_build_object('refreshed', false, 'reason', 'refresh_error', 'error', SQLERRM);
  END;
END
$function$
;

CREATE OR REPLACE FUNCTION public.urun_aciklama_uret(p_ad text, p_marka text, p_kg numeric)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  t text := coalesce(p_ad, '');
  lt text := lower(translate(t, 'İIÇĞÖŞÜ', 'iıçğöşü'));
  tip text; malzeme text; montaj text; yedek boolean;
  bullets text[] := array[]::text[];
  olcu text; giris text; kapanis text; govde text;
begin
  tip := case
    when lt like '%çanak lavabo batarya%' then 'çanak lavabo bataryası'
    when lt like '%çanak lavabo%'      then 'tezgah üstü çanak lavabo'
    when lt like '%küvet batarya%'     then 'küvet bataryası'
    when lt like '%duş seti%' or lt like '%duş sistemi%' or lt like '%duş batarya%' then 'duş sistemi'
    when lt like '%eviye batarya%' or lt like '%evye batarya%' or lt like '%mutfak batarya%' then 'mutfak eviye bataryası'
    when lt like '%eviye seti%'        then 'mutfak eviye seti'
    when lt like '%eviyesi%'           then 'mutfak eviyesi'
    when lt like '%ankastre%'          then 'ankastre lavabo bataryası'
    when lt like '%lavabo batarya%'    then 'lavabo bataryası'
    when lt like '%somun%' or lt like '%rakor%' or lt like '%aksam%' or lt like '%gövdesi%'
                                       then 'batarya yedek parçası'
    else 'banyo armatürü' end;
  yedek := (tip = 'batarya yedek parçası');

  malzeme := case
    when lt like '%304%' or lt like '%sus304%' then '304 paslanmaz çelik'
    when lt like '%pirinç%'                     then 'pirinç'
    when lt like '%zamak%'                      then 'zamak (çinko alaşım) enjeksiyon döküm'
    else null end;

  montaj := case
    when lt like '%sıva altı%'      then 'Sıva altı (ankastre) montaj'
    when lt like '%duvara monte%'   then 'Duvara monte'
    when lt like '%yerden montaj%'  then 'Yerden montajlı, serbest duran'
    when lt like '%tezgah üstü - tezgah altı%' or lt like '%tezgah üstü tezgah altı%'
                                    then 'Tezgah üstü veya tezgah altı montaj'
    when lt like '%tezgah üstü%'    then 'Tezgah üstü montaj'
    else null end;

  if malzeme = '304 paslanmaz çelik' then
    bullets := bullets || '304 paslanmaz çelik gövde — paslanmaya ve lekeye karşı dayanıklı'::text;
  elsif malzeme = 'pirinç' then
    bullets := bullets || 'Pirinç gövde — uzun ömürlü ve dayanıklı'::text;
  elsif malzeme is not null then
    bullets := bullets || ('Zamak (çinko alaşım) enjeksiyon döküm gövde')::text;
  end if;

  if lt like '%krom kap%'       then bullets := bullets || 'Krom kaplama'::text; end if;
  if lt like '%pvd%'            then bullets := bullets || 'PVD kaplama'::text; end if;
  if montaj is not null         then bullets := bullets || montaj::text; end if;
  if lt like '%termostatik%'    then bullets := bullets || 'Termostatik kumanda — su sıcaklığı sabit tutulur'::text; end if;
  if lt like '%fotoselli%' or lt like '%sensörlü%' then bullets := bullets || 'Fotoselli sensör ile temassız kullanım'::text; end if;
  if lt like '%pilli%'          then bullets := bullets || 'Pille çalışır'::text; end if;
  if lt like '%led%'            then bullets := bullets || 'LED göstergeli'::text; end if;
  if lt like '%dijital ekran%'  then bullets := bullets || 'Dijital ekran'::text; end if;
  if lt like '%1080%'           then bullets := bullets || '1080° döner gövde'::text;
  elsif lt like '%360%'         then bullets := bullets || '360° döner gövde'::text; end if;
  if lt like '%spiralli%' or lt like '%çekmeli%' or lt like '%çekilebilir%' or lt like '%pull out%'
                                then bullets := bullets || 'Çekmeli (spiralli) başlık — eviyenin her noktasına ulaşır'::text; end if;
  if lt like '%şelale%'         then bullets := bullets || 'Şelale akış'::text; end if;
  if lt like '%yağmur%'         then bullets := bullets || 'Yağmurlama duş başlığı'::text; end if;
  if lt like '%el duş%'         then bullets := bullets || 'El duşu dahil'::text; end if;
  if lt like '%masaj jet%' or lt like '%sırt masaj%' then bullets := bullets || 'Sırt masaj jetleri'::text; end if;
  if lt like '%arıtmalı%'       then bullets := bullets || 'Arıtma su çıkışı (ayrı hat)'::text; end if;
  if lt like '%bardak yıka%'    then bullets := bullets || 'Bardak yıkama aparatı'::text; end if;
  if lt like '%sabunluk%'       then bullets := bullets || 'Sabunluk dahil'::text; end if;
  if lt like '%seramik kartuş%' or lt like '%seramik valf%'
                                then bullets := bullets || 'Seramik kartuş — damlamaya karşı sızdırmaz'::text; end if;
  if lt like '%aç kapa%'        then bullets := bullets || 'Aç-kapa tek kollu kullanım'::text;
  elsif lt like '%tek kollu%'   then bullets := bullets || 'Tek kollu kullanım'::text; end if;
  if lt like '%sıcak soğuk%'    then bullets := bullets || 'Sıcak ve soğuk su karıştırmalı'::text; end if;
  if lt ~ '[0-9]+ ?(fonksiyonlu|modlu|buton)' then
    bullets := bullets || (substring(t from '[0-9]+ ?(?:[FfMmBb][a-zçğıöşüA-ZÇĞİÖŞÜ]+)') || ' kullanım')::text;
  end if;
  if lt like '%kristal taş%'    then bullets := bullets || 'Kristal taş detaylı tasarım'::text; end if;
  if lt like '%nano%'           then bullets := bullets || 'Nano yüzey — çizilmeye ve lekeye dirençli'::text; end if;
  if lt like '%leke tutmaz%'    then bullets := bullets || 'Leke tutmaz yüzey'::text; end if;

  olcu := substring(t from '[0-9]+(?:[.,][0-9]+)? ?[xX×] ?[0-9]+(?:[.,][0-9]+)? ?(?:cm|mm)?');
  if olcu is null then olcu := substring(t from '[0-9]{2,3} ?cm'); end if;
  if olcu is not null then bullets := bullets || ('Ölçü: ' || olcu)::text; end if;

  if coalesce(p_kg,0) > 0 then
    bullets := bullets || ('Ürün ağırlığı: '
      || replace(trim(to_char(p_kg, 'FM999990.00')), '.', ',') || ' kg')::text;
  end if;

  giris := t || '.' || case
    when malzeme is not null then ' ' || malzeme || ' gövdeli bu ' || tip || ', '
    else ' Bu ' || tip || ', ' end
    || case
      when tip in ('lavabo bataryası','çanak lavabo bataryası','ankastre lavabo bataryası')
        then 'banyo lavabolarında günlük kullanım için tasarlandı.'
      when tip in ('mutfak eviye bataryası','mutfak eviye seti','mutfak eviyesi')
        then 'mutfak eviyelerinde günlük kullanım için tasarlandı.'
      when tip = 'duş sistemi'  then 'banyo duş alanı için eksiksiz bir set olarak sunulur.'
      when tip = 'küvet bataryası' then 'küvet dolumu ve duş kullanımı için tasarlandı.'
      when tip = 'tezgah üstü çanak lavabo' then 'banyo tezgahınızın üzerine oturtularak kullanılır.'
      when yedek then 'armatür üretimi ve montajında kullanılan bir yedek parçadır.'
      else 'banyo kullanımı için tasarlandı.' end;

  govde := array_to_string(array(select '• ' || u from unnest(bullets) u), E'\n');

  kapanis := case
    when yedek then 'Perakende satış için değil, üretim ve servis kullanımı içindir.'
    when malzeme = '304 paslanmaz çelik'
      then 'Yüzeyi yumuşak ve nemli bir bezle silin; aşındırıcı veya klor içeren temizleyiciler kaplamaya zarar verebilir.'
    when lt like '%pvd%'
      then 'PVD kaplamalı yüzeyi yumuşak bir bezle silin; aşındırıcı temizleyici kullanmayın.'
    else 'Yüzeyi yumuşak ve nemli bir bezle silin; aşındırıcı temizleyici kullanmayın.' end;

  return giris || E'\n\nÖne çıkan özellikler:\n' || govde || E'\n\n' || kapanis;
end $function$
;

CREATE OR REPLACE FUNCTION public.urun_aday_sku_num(s text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select x[1] from regexp_matches(coalesce(s, ''), '(\d{6,})', 'g') as m(x)
   order by length(x[1]) desc limit 1;
$function$
;

CREATE OR REPLACE FUNCTION public.urun_kutu_tahmin(p_ad text, p_kg numeric)
 RETURNS numeric[]
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  t text := coalesce(p_ad,'');
  lt text := lower(translate(t,'İIÇĞÖŞÜ','iıçğöşü'));
  d1 numeric; d2 numeric; vol numeric; s numeric;
begin
  if coalesce(p_kg,0) <= 0 then return null; end if;

  -- ÇANAK LAVABO: ölçü başlıkta yazıyor, kutu = ürün + 5 cm pay.
  if lt like '%çanak lavabo%' and lt not like '%batarya%' then
    d1 := (substring(t from '([0-9]{2,3}) ?[xX×] ?[0-9]{2,3} ?cm'))::numeric;
    d2 := (substring(t from '[0-9]{2,3} ?[xX×] ?([0-9]{2,3}) ?cm'))::numeric;
    if d1 is null then
      d1 := (substring(t from '([0-9]{2,3}) ?cm'))::numeric;
      d2 := d1;                                   -- yuvarlak çanak → kare kutu
    end if;
    if d1 is not null then
      return array[round(d1 + 5), round(d2 + 5), 15];
    end if;
  end if;

  -- YERDEN MONTAJLI KÜVET BATARYASI: ~113 cm boyunda, uzun kutu (faturadan).
  if lt like '%küvet batarya%' and lt like '%yerden%' then
    return array[115, 20, 20];
  end if;

  vol := p_kg * 2500;                             -- paketli yoğunluk ~0,4 kg/L

  -- DUŞ SİSTEMİ: uzun kutu, 5 : 1,5 : 1
  if lt like '%duş seti%' or lt like '%duş sistemi%' or lt like '%duş batarya%' then
    s := power(vol / 7.5, 1.0/3.0);
    return array[round(5*s), round(1.5*s), round(s)];
  end if;

  -- BATARYA ve diğerleri: 2 : 1 : 1 (AS304167 çapası — 0,80 kg → 20x10x10)
  s := power(vol / 2.0, 1.0/3.0);
  return array[round(2*s), round(s), round(s)];
end $function$
;

CREATE OR REPLACE VIEW public.candidate_board AS
 SELECT c.id,
    c.term,
    c.title_en,
    c.title_tr_terms,
    c.canonical_image_url,
    c.source_url,
    c.category,
    c.risk_flags,
    c.status,
    c.first_seen,
    s.total,
    s.verdict,
    s.demand_sub,
    s.gap_sub,
    s.source_sub,
    s.coverage,
    s.reason,
    s.missing,
    sd.amazon_bsr,
    sd.amazon_bsr_delta,
    sd.tr_listing_count,
    sd.tr_review_count,
    d.human_verdict,
    d.notes,
    d.rating,
    d.decided_at,
    c.asin,
    c.pref_score,
    c.brand
   FROM (((candidates c
     LEFT JOIN LATERAL ( SELECT scores.candidate_id,
            scores.date,
            scores.total,
            scores.verdict,
            scores.demand_sub,
            scores.gap_sub,
            scores.source_sub,
            scores.confidence_mult,
            scores.velocity_bonus,
            scores.coverage,
            scores.subscores,
            scores.missing,
            scores.errors,
            scores.reason
           FROM scores
          WHERE (scores.candidate_id = c.id)
          ORDER BY scores.date DESC
         LIMIT 1) s ON (true))
     LEFT JOIN LATERAL ( SELECT signals_daily.candidate_id,
            signals_daily.date,
            signals_daily.ad_days_running,
            signals_daily.ad_variants,
            signals_daily.ad_advertisers,
            signals_daily.ad_active,
            signals_daily.ad_impressions_band,
            signals_daily.tiktok_volume,
            signals_daily.tiktok_growth,
            signals_daily.amazon_bsr,
            signals_daily.amazon_bsr_delta,
            signals_daily.trends_us,
            signals_daily.trends_tr,
            signals_daily.trends_us_slope,
            signals_daily.trends_tr_slope,
            signals_daily.tr_listing_count,
            signals_daily.tr_review_count,
            signals_daily.tr_review_velocity,
            signals_daily.cn_unit_cost,
            signals_daily.cn_moq
           FROM signals_daily
          WHERE (signals_daily.candidate_id = c.id)
          ORDER BY signals_daily.date DESC
         LIMIT 1) sd ON (true))
     LEFT JOIN LATERAL ( SELECT decisions.id,
            decisions.candidate_id,
            decisions.decided_at,
            decisions.human_verdict,
            decisions.bought,
            decisions.outcome,
            decisions.notes,
            decisions.rating
           FROM decisions
          WHERE (decisions.candidate_id = c.id)
          ORDER BY decisions.decided_at DESC
         LIMIT 1) d ON (true));

CREATE OR REPLACE VIEW public.cfo_ay_kazanan_ozet AS
 SELECT to_char((ay)::timestamp with time zone, 'YYYY-MM'::text) AS ay_str,
    ay,
    max(ay_toplam_kar) AS ay_toplam_kar,
    max(kapsam_pct) AS kapsam_pct,
    round(sum(net_kar)) AS top10_kar,
    round(((sum(net_kar) / NULLIF(max(ay_toplam_kar), (0)::numeric)) * (100)::numeric), 1) AS top10_payi_pct,
    (array_agg(sku ORDER BY sira))[1] AS birinci,
    (array_agg(net_kar ORDER BY sira))[1] AS birinci_kar,
    max(dondurulma_tarihi) AS dondurulma,
    min(maliyet_kaynagi) AS maliyet_kaynagi,
        CASE
            WHEN (max(kapsam_pct) >= (85)::numeric) THEN 'YUKSEK'::text
            WHEN (max(kapsam_pct) >= (60)::numeric) THEN 'ORTA'::text
            ELSE 'DUSUK'::text
        END AS guven
   FROM cfo_ay_kazanan
  GROUP BY ay;

CREATE OR REPLACE VIEW public.cfo_bekleyen_karar AS
 SELECT 'aday'::text AS tur,
    (c.id)::text AS kayit_id,
    c.product_name AS baslik,
    c.verdict AS durum,
    c.found_at AS acilis,
    (CURRENT_DATE - c.found_at) AS bekleme_gun
   FROM cfo_product_candidate c
  WHERE (c.verdict <> ALL (ARRAY['sermaye_planinda'::text, 'cekirdek_tut'::text, 'paket_ici'::text, 'ele'::text, 'reddedildi'::text]))
UNION ALL
 SELECT 'olu_stok'::text AS tur,
    (d.id)::text AS kayit_id,
    COALESCE(d.product_name, d.sku, '(isimsiz)'::text) AS baslik,
    COALESCE(d.status, 'acik'::text) AS durum,
    COALESCE(d.next_review_at, d.found_at) AS acilis,
    (CURRENT_DATE - COALESCE(d.next_review_at, d.found_at)) AS bekleme_gun
   FROM cfo_dead_stock_finding d
  WHERE ((COALESCE(d.status, 'acik'::text) <> ALL (ARRAY['kapandi'::text, 'gecersiz'::text])) AND ((d.next_review_at IS NULL) OR (d.next_review_at < CURRENT_DATE)))
UNION ALL
 SELECT 'soru'::text AS tur,
    q.id AS kayit_id,
    "left"(q.question, 70) AS baslik,
    q.status AS durum,
    (q."askedAt")::date AS acilis,
    (CURRENT_DATE - (q."askedAt")::date) AS bekleme_gun
   FROM cfo_question q
  WHERE ((q.status = 'ACIK'::text) AND (q."processedAt" IS NULL))
UNION ALL
 SELECT 'bayat_not'::text AS tur,
    n.id AS kayit_id,
    n.title AS baslik,
    'gozden_gecir'::text AS durum,
    (n."reviewBy")::date AS acilis,
    (CURRENT_DATE - (n."reviewBy")::date) AS bekleme_gun
   FROM cfo_note n
  WHERE ((n."archivedAt" IS NULL) AND (n."reviewBy" IS NOT NULL) AND (n."reviewBy" < now()));

CREATE OR REPLACE VIEW public.cfo_hamle_erken_uyari AS
 WITH son3 AS (
         SELECT cfo_kilometre_tasi.ay,
            cfo_kilometre_tasi.kar_marji,
            cfo_kilometre_tasi.kar,
            cfo_kilometre_tasi.ciro,
            round((cfo_kilometre_tasi.kar / NULLIF(cfo_kilometre_tasi.ciro, (0)::numeric)), 4) AS marj_ham,
            lag(cfo_kilometre_tasi.kar_marji) OVER (ORDER BY cfo_kilometre_tasi.ay) AS onceki_marj,
            lag(cfo_kilometre_tasi.kar) OVER (ORDER BY cfo_kilometre_tasi.ay) AS onceki_kar
           FROM cfo_kilometre_tasi
          WHERE (cfo_kilometre_tasi.ay >= '2026-01-01'::date)
        )
 SELECT ay,
    ciro,
    kar,
    kar_marji,
    onceki_marj,
    round((kar_marji - onceki_marj), 1) AS marj_degisim,
        CASE
            WHEN (onceki_marj IS NULL) THEN 'BAZ'::text
            WHEN (kar_marji < (onceki_marj - (2)::numeric)) THEN '🔴 MARJ 2 PUANDAN FAZLA DUSTU — H01 tezi tehlikede'::text
            WHEN (kar_marji < onceki_marj) THEN '🟡 marj geriledi'::text
            WHEN ((kar < onceki_kar) AND (kar_marji > onceki_marj)) THEN '🔴 MARJ ARTTI AMA KAR DUSTU — fiyat hacmi kiriyor, tez yanlis olabilir'::text
            ELSE '🟢 marj korunuyor'::text
        END AS uyari
   FROM son3
  ORDER BY ay DESC;

CREATE OR REPLACE VIEW public.cfo_hamle_hikaye AS
 SELECT kod,
    karar_tarihi,
    baslik,
    durum,
    sikisiklik,
    ((((((((((((((((to_char((karar_tarihi)::timestamp with time zone, 'DD.MM.YYYY'::text) || ' — '::text) || baslik) || '
'::text) || 'O GUN: '::text) || neden) || '
'::text) || 'YAPILAN: '::text) || yapilan) || '
'::text) || 'BASLANGIC: '::text) || COALESCE(((baslangic_metrik || ' = '::text) || (baslangic_deger)::text), 'olculmedi'::text)) || '
'::text) || 'SONUC: '::text) ||
        CASE
            WHEN (gerceklesen_deger IS NULL) THEN (('HENUZ OLCULMEDI (olcum '::text || COALESCE((ilk_olcum_tarihi)::text, '?'::text)) || ')'::text)
            ELSE (((((olcum_metrigi || ' = '::text) || (gerceklesen_deger)::text) || ' ('::text) || COALESCE((gerceklesen_tarih)::text, ''::text)) || ')'::text)
        END) || '
'::text) || COALESCE(('DERS: '::text || ders), ''::text)) AS hikaye,
    baslangic_deger,
    gerceklesen_deger,
        CASE
            WHEN ((baslangic_deger IS NOT NULL) AND (baslangic_deger <> (0)::numeric) AND (gerceklesen_deger IS NOT NULL)) THEN round((((gerceklesen_deger - baslangic_deger) / abs(baslangic_deger)) * (100)::numeric), 1)
            ELSE NULL::numeric
        END AS degisim_pct,
    ( SELECT count(*) AS count
           FROM cfo_hamle_olcum o
          WHERE (o.hamle_kod = h.kod)) AS olcum_sayisi
   FROM cfo_hamle h;

CREATE OR REPLACE VIEW public.cfo_kur_etkisi AS
 WITH t AS (
         SELECT cfo_kilometre_tasi.ay,
            cfo_kilometre_tasi.ciro,
            cfo_kilometre_tasi.kar,
            cfo_kilometre_tasi.usd_try,
            cfo_kilometre_tasi.ciro_usd,
            cfo_kilometre_tasi.kar_usd,
            lag(cfo_kilometre_tasi.ciro) OVER (ORDER BY cfo_kilometre_tasi.ay) AS onceki_ciro,
            lag(cfo_kilometre_tasi.ciro_usd) OVER (ORDER BY cfo_kilometre_tasi.ay) AS onceki_ciro_usd,
            lag(cfo_kilometre_tasi.usd_try) OVER (ORDER BY cfo_kilometre_tasi.ay) AS onceki_kur
           FROM cfo_kilometre_tasi
          WHERE (cfo_kilometre_tasi.usd_try IS NOT NULL)
        )
 SELECT ay,
    usd_try,
    round((((usd_try / NULLIF(onceki_kur, (0)::numeric)) - (1)::numeric) * (100)::numeric), 1) AS kur_degisim_pct,
    round(ciro) AS ciro_try,
    round((((ciro / NULLIF(onceki_ciro, (0)::numeric)) - (1)::numeric) * (100)::numeric), 1) AS ciro_try_pct,
    ciro_usd,
    round((((ciro_usd / NULLIF(onceki_ciro_usd, (0)::numeric)) - (1)::numeric) * (100)::numeric), 1) AS ciro_usd_pct,
    round((((ciro / NULLIF(onceki_ciro, (0)::numeric)) - (ciro_usd / NULLIF(onceki_ciro_usd, (0)::numeric))) * (100)::numeric), 1) AS kur_katkisi_puan,
    kar_usd,
    round((ciro_usd / 1000.0), 1) AS hedef_100k_pct
   FROM t
  ORDER BY ay DESC;

CREATE OR REPLACE VIEW public.cfo_nakit_kapisi AS
 SELECT ( SELECT COALESCE(sum(cfo_bank_account."balanceTry"), (0)::numeric) AS "coalesce"
           FROM cfo_bank_account
          WHERE (cfo_bank_account."isActive" AND (cfo_bank_account."balanceTry" IS NOT NULL) AND (cfo_bank_account."accountType" !~~* '%ŞAHSİ%'::text))) AS nakit_try,
    ( SELECT COALESCE(sum(cfo_receivable."amountTry"), (0)::numeric) AS "coalesce"
           FROM cfo_receivable
          WHERE ((NOT cfo_receivable."isCollected") AND ((cfo_receivable."dueDate")::date >= CURRENT_DATE) AND ((cfo_receivable."dueDate")::date <= (CURRENT_DATE + 10)) AND ((cfo_receivable.certainty)::text = 'KESIN'::text))) AS girecek_10g,
    ( SELECT COALESCE(sum(cfo_cash_event."outflowTry"), (0)::numeric) AS "coalesce"
           FROM cfo_cash_event
          WHERE ((NOT cfo_cash_event."isSettled") AND ((cfo_cash_event."eventDate")::date >= CURRENT_DATE) AND ((cfo_cash_event."eventDate")::date <= (CURRENT_DATE + 10)))) AS cikacak_10g,
    ( SELECT COALESCE(sum(GREATEST((cfo_bank_account."kmhLimitTry" - GREATEST((- cfo_bank_account."balanceTry"), (0)::numeric)), (0)::numeric)), (0)::numeric) AS "coalesce"
           FROM cfo_bank_account
          WHERE (cfo_bank_account."isActive" AND (cfo_bank_account."balanceTry" IS NOT NULL) AND (cfo_bank_account."accountType" !~~* '%ŞAHSİ%'::text))) AS bos_kmh_try,
    ( SELECT COALESCE(sum(cfo_bank_account."purposeLimitTry"), (0)::numeric) AS "coalesce"
           FROM cfo_bank_account
          WHERE (cfo_bank_account."isActive" AND (cfo_bank_account."accountType" !~~* '%ŞAHSİ%'::text))) AS amacli_kmh_try,
    ( SELECT COALESCE(sum(cfo_receivable."amountTry"), (0)::numeric) AS "coalesce"
           FROM cfo_receivable
          WHERE ((NOT cfo_receivable."isCollected") AND ((cfo_receivable."dueDate")::date < CURRENT_DATE))) AS vadesi_gecmis_alacak_try;

CREATE OR REPLACE VIEW public.cfo_satis_birim AS
 SELECT id,
    channel,
    "orderNumber",
    "platformRef",
    "externalLineId",
    "orderDate",
    status,
    "productName",
    "productCode",
    "modelNumber",
    "storeStockName",
    "productId",
    quantity,
    "grossAmountTry",
    "vatAmountTry",
    "totalAmountTry",
    "commissionTry",
    "commissionPct",
    "platformPaymentTry",
    "customerCode",
    "customerFirma",
    "customerInvoiceName",
    "customerVergiNo",
    "customerTcKimlik",
    "customerVergiDairesi",
    "customerCity",
    "cargoCompany",
    "cargoTrackingNo",
    "desiTotal",
    "customerId",
    "importedAt"
   FROM "MarketplaceSalesRecord"
  WHERE ((status <> 'İade-İptal'::text) AND (channel <> 'IDEASOFT'::text));

CREATE OR REPLACE VIEW public.cfo_satis_siparis AS
 SELECT channel,
    "orderNumber",
    min("orderDate") AS siparis_tarihi,
    sum("totalAmountTry") AS siparis_tutari,
    count(*) AS satir
   FROM "MarketplaceSalesRecord"
  WHERE (status <> 'İade-İptal'::text)
  GROUP BY channel, "orderNumber";

CREATE OR REPLACE VIEW public.cfo_snapshot_delta AS
 WITH s AS (
         SELECT cfo_snapshot."takenAt",
            cfo_snapshot."netWorthUsd",
            cfo_snapshot."cashTry",
            cfo_snapshot."debtTry",
            cfo_snapshot."usdTryRate",
            lag(cfo_snapshot."netWorthUsd") OVER w AS onceki_usd,
            lag(cfo_snapshot."cashTry") OVER w AS onceki_nakit,
            lag(cfo_snapshot."debtTry") OVER w AS onceki_borc,
            lag(cfo_snapshot."takenAt") OVER w AS onceki_an
           FROM cfo_snapshot
          WINDOW w AS (ORDER BY cfo_snapshot."takenAt")
        )
 SELECT "takenAt",
    "netWorthUsd",
    ("netWorthUsd" - onceki_usd) AS oncekine_gore_usd,
    ("cashTry" - onceki_nakit) AS oncekine_gore_nakit_try,
    ("debtTry" - onceki_borc) AS oncekine_gore_borc_try,
    onceki_an AS karsilastirilan_fotograf,
    "usdTryRate"
   FROM s
  ORDER BY "takenAt" DESC;

CREATE OR REPLACE VIEW public.cfo_snapshot_gunluk AS
 SELECT DISTINCT ON ((("takenAt")::date)) ("takenAt")::date AS gun,
    id,
    "takenAt",
    "netWorthTry",
    "netWorthUsd",
    "wideWorthTry",
    "wideWorthUsd",
    "cashTry",
    "receivablesTry",
    "stockTry",
    "debtTry",
    "usdTryRate",
    note
   FROM cfo_snapshot
  ORDER BY (("takenAt")::date) DESC, "takenAt" DESC;

CREATE OR REPLACE VIEW public.cfo_stok_hareket_hiz AS
 WITH temiz AS (
         SELECT "XmlStockChangeLog"."productId" AS pid,
            ("XmlStockChangeLog"."syncedAt")::date AS gun,
            (- "XmlStockChangeLog".delta) AS adet
           FROM "XmlStockChangeLog"
          WHERE (("XmlStockChangeLog".delta < 0) AND ("XmlStockChangeLog".delta > '-100'::integer))
        ), medyan AS (
         SELECT temiz.pid,
            percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY ((temiz.adet)::double precision)) AS med
           FROM temiz
          WHERE (temiz.gun >= (CURRENT_DATE - 30))
          GROUP BY temiz.pid
        ), pencere AS (
         SELECT t.pid,
            sum(t.adet) FILTER (WHERE (t.gun >= (CURRENT_DATE - 7))) AS adet7,
            sum(t.adet) FILTER (WHERE (t.gun >= (CURRENT_DATE - 30))) AS adet30,
            count(DISTINCT t.gun) FILTER (WHERE (t.gun >= (CURRENT_DATE - 30))) AS hareketli_gun30,
            max(t.gun) AS son_hareket,
            sum(t.adet) FILTER (WHERE ((t.gun >= (CURRENT_DATE - 30)) AND ((t.adet)::double precision > GREATEST((m.med * (5)::double precision), (10)::double precision)))) AS sicrama_adet30
           FROM (temiz t
             JOIN medyan m ON ((m.pid = t.pid)))
          GROUP BY t.pid
        )
 SELECT p.sku,
    p.name AS urun,
    p."stockQuantity" AS stok,
    p."unitCostTry" AS birim_maliyet,
    w.adet7,
    w.adet30,
    w.hareketli_gun30,
    w.son_hareket,
    COALESCE(w.sicrama_adet30, (0)::bigint) AS sicrama_adet30,
    round(((w.adet7)::numeric / 7.0), 2) AS gunluk_7g,
    round(((w.adet30)::numeric / 30.0), 2) AS gunluk_30g,
    round((((w.adet30 - COALESCE(w.sicrama_adet30, (0)::bigint)))::numeric / 30.0), 2) AS gunluk_30g_ihtiyatli,
        CASE
            WHEN (w.adet30 > COALESCE(w.sicrama_adet30, (0)::bigint)) THEN round(((p."stockQuantity")::numeric / (((w.adet30 - COALESCE(w.sicrama_adet30, (0)::bigint)))::numeric / 30.0)))
            ELSE NULL::numeric
        END AS tukenme_gun_ihtiyatli,
        CASE
            WHEN (w.adet7 > 0) THEN round(((p."stockQuantity")::numeric / ((w.adet7)::numeric / 7.0)))
            ELSE NULL::numeric
        END AS tukenme_gun_7g,
    round(((p."stockQuantity")::numeric * p."unitCostTry")) AS bagli_sermaye,
        CASE
            WHEN (w.adet30 > 0) THEN round((((w.adet7)::numeric / 7.0) / NULLIF(((w.adet30)::numeric / 30.0), (0)::numeric)), 2)
            ELSE NULL::numeric
        END AS hizlanma_katsayi,
    (COALESCE(w.sicrama_adet30, (0)::bigint) > 0) AS sicrama_var
   FROM ("Product" p
     JOIN pencere w ON ((w.pid = p.id)))
  WHERE (p."isActive" AND (p."stockQuantity" <> ALL (ARRAY[500, 998, 999, 1000, 9999, 10000])));

CREATE OR REPLACE VIEW public.cfo_stok_sicrama_durum AS
 WITH ty AS (
         SELECT s_1.id,
            COALESCE(sum(t.quantity) FILTER (WHERE (COALESCE(t.status, ''::text) !~~* '%cancel%'::text)), (0)::bigint) AS ty_adet
           FROM (cfo_stok_sicrama s_1
             LEFT JOIN "TrendyolSalesRecord" t ON ((((t."productId" = s_1.product_id) OR (lower(t."merchantSku") = lower(s_1.sku)) OR (t.barcode IN ( SELECT m."platformBarcode"
                   FROM "MarketplaceProductMapping" m
                  WHERE ((m."productId" = s_1.product_id) AND (m."platformBarcode" IS NOT NULL))))) AND (t."orderDate" > (s_1.synced_at - '26:00:00'::interval)) AND (t."orderDate" <= s_1.synced_at))))
          GROUP BY s_1.id
        ), fba AS (
         SELECT s_1.id,
            COALESCE(sum(m.quantity), (0)::bigint) AS fba_adet
           FROM (cfo_stok_sicrama s_1
             LEFT JOIN "MarketplaceSalesRecord" m ON (((m.channel = 'AMAZON_FBA'::text) AND (m."externalLineId" = s_1.sku) AND (m."orderDate" > (s_1.synced_at - '26:00:00'::interval)) AND (m."orderDate" <= s_1.synced_at))))
          GROUP BY s_1.id
        ), ent AS (
         SELECT s_1.id,
            COALESCE(sum(m.quantity), (0)::bigint) AS entegra_adet,
            count(DISTINCT m.channel) AS entegra_kanal
           FROM (cfo_stok_sicrama s_1
             LEFT JOIN "MarketplaceSalesRecord" m ON (((m.channel <> ALL (ARRAY['TRENDYOL'::text, 'AMAZON_FBA'::text])) AND (COALESCE(m.status, ''::text) !~~* '%ptal%'::text) AND ((m."productId" = s_1.product_id) OR ((m."productId" IS NULL) AND (lower(m."modelNumber") = lower(s_1.sku)))) AND (m."orderDate" > (s_1.synced_at - '26:00:00'::interval)) AND (m."orderDate" <= s_1.synced_at))))
          GROUP BY s_1.id
        ), tysync AS (
         SELECT max("TrendyolSalesRecord"."syncedAt") AS son
           FROM "TrendyolSalesRecord"
        ), entsync AS (
         SELECT max("MarketplaceSalesRecord"."orderDate") AS son
           FROM "MarketplaceSalesRecord"
        )
 SELECT s.id,
    s.sku,
    "left"(s.urun, 60) AS urun,
    ((s.synced_at)::date - 1) AS hareket_gunu,
    s.onceki,
    s.yeni,
    s.delta,
    s.medyan_dusus AS normal_gunluk_dusus,
    s.esik_nedeni,
    s.entegra_degisim_zamani,
    ty.ty_adet,
    fba.fba_adet,
    GREATEST(((((- s.delta) - ty.ty_adet) - fba.fba_adet) - ent.entegra_adet), (0)::bigint) AS aciklanamayan_adet,
    round(((GREATEST(((((- s.delta) - ty.ty_adet) - fba.fba_adet) - ent.entegra_adet), (0)::bigint))::numeric * COALESCE(p."unitCostTry", (0)::numeric))) AS aciklanamayan_maliyet_try,
    s.durum,
    s.aciklama,
        CASE
            WHEN (s.durum <> 'ACIK'::text) THEN ('KAPANDI: '::text || s.durum)
            WHEN (s.delta < '-100'::integer) THEN 'TOPLU_DUZELTME_SUPHESI'::text
            WHEN ((((ty.ty_adet + fba.fba_adet) + ent.entegra_adet))::numeric >= (0.8 * ((- s.delta))::numeric)) THEN 'SATIS_ESLESTI'::text
            WHEN (tysync.son < (s.synced_at + '04:00:00'::interval)) THEN 'BEKLIYOR_TRENDYOL_SENKRONU'::text
            WHEN (entsync.son < (s.synced_at - '24:00:00'::interval)) THEN 'BEKLIYOR_ENTEGRA_YUKLEMESI'::text
            ELSE 'ACIKLANAMADI'::text
        END AS otomatik_teshis,
    ent.entegra_adet,
    ent.entegra_kanal
   FROM ((((((cfo_stok_sicrama s
     JOIN ty ON ((ty.id = s.id)))
     JOIN fba ON ((fba.id = s.id)))
     JOIN ent ON ((ent.id = s.id)))
     CROSS JOIN tysync)
     CROSS JOIN entsync)
     LEFT JOIN "Product" p ON ((p.id = s.product_id)));

CREATE OR REPLACE VIEW public.cfo_xml_hareket AS
 SELECT l."productId" AS product_id,
    p.sku,
    ((l."syncedAt")::date - 1) AS is_gunu,
    l."syncedAt",
    l."previousQty" AS onceki,
    l."newQty" AS yeni,
    l.delta,
        CASE
            WHEN ((l.delta >= '-100'::integer) AND (l.delta <= '-1'::integer)) THEN 'SATIS'::text
            WHEN (l.delta < '-100'::integer) THEN 'TOPLU_DUZELTME'::text
            WHEN ((l.delta >= 1) AND (l.delta <= 5)) THEN 'IADE_VEYA_GIRIS'::text
            ELSE 'STOK_GIRISI'::text
        END AS hareket_turu,
        CASE
            WHEN ((l.delta >= '-100'::integer) AND (l.delta <= '-1'::integer)) THEN (- l.delta)
            ELSE 0
        END AS satis_adet
   FROM ("XmlStockChangeLog" l
     JOIN "Product" p ON ((p.id = l."productId")));

CREATE OR REPLACE VIEW public.cfo_yaklasan_odeme AS
 WITH nakit AS (
         SELECT COALESCE(sum(cfo_bank_account."balanceTry"), (0)::numeric) AS b
           FROM cfo_bank_account
          WHERE (cfo_bank_account."isActive" = true)
        ), hareket AS (
         SELECT e.id,
            (e."eventDate")::date AS tarih,
            'CIKIS'::text AS yon,
                CASE (e.kind)::text
                    WHEN 'KREDI_TAKSITI'::text THEN 'Kredi taksiti'::text
                    WHEN 'KART_ODEMESI'::text THEN 'Kart ödemesi'::text
                    WHEN 'SABIT_GIDER'::text THEN 'Sabit gider'::text
                    WHEN 'VERGI_GUMRUK'::text THEN 'Vergi / Gümrük'::text
                    ELSE initcap(replace((e.kind)::text, '_'::text, ' '::text))
                END AS tur,
            e.description AS aciklama,
            e.bank AS banka,
            e."outflowTry" AS tutar,
            (e.certainty)::text AS kesinlik,
            e."isSettled" AS odendi,
            e.note
           FROM cfo_cash_event e
          WHERE (COALESCE(e."outflowTry", (0)::numeric) > (0)::numeric)
        UNION ALL
         SELECT r.id,
            (r."dueDate")::date AS "dueDate",
            'GIRIS'::text AS "?column?",
            'Pazaryeri tahsilatı'::text AS "?column?",
            (r.channel || ' hakediş'::text),
            r.channel,
            r."amountTry",
            (r.certainty)::text AS certainty,
            r."isCollected",
            r.note
           FROM cfo_receivable r
        UNION ALL
         SELECT e.id,
            (e."eventDate")::date AS "eventDate",
            'GIRIS'::text AS "?column?",
            'Diğer tahsilat'::text AS "?column?",
            e.description,
            e.bank,
            e."inflowTry",
            (e.certainty)::text AS certainty,
            e."isSettled",
            e.note
           FROM cfo_cash_event e
          WHERE (COALESCE(e."inflowTry", (0)::numeric) > (0)::numeric)
        )
 SELECT id,
    tarih,
    yon,
    tur,
    aciklama,
    banka,
    tutar,
    kesinlik,
    odendi,
    note,
    (tarih - CURRENT_DATE) AS kalan_gun,
        CASE
            WHEN odendi THEN 'ODENDI'::text
            WHEN (tarih < CURRENT_DATE) THEN 'GECIKMIS'::text
            WHEN (tarih = CURRENT_DATE) THEN 'BUGUN'::text
            WHEN (tarih <= (CURRENT_DATE + 3)) THEN 'ACIL'::text
            WHEN (tarih <= (CURRENT_DATE + 7)) THEN 'BU_HAFTA'::text
            WHEN (tarih <= (CURRENT_DATE + 30)) THEN 'BU_AY'::text
            ELSE 'ILERIDE'::text
        END AS aciliyet,
        CASE
            WHEN (yon = 'CIKIS'::text) THEN (- tutar)
            ELSE tutar
        END AS net_etki,
    (( SELECT nakit.b
           FROM nakit) + sum(
        CASE
            WHEN odendi THEN (0)::numeric
            WHEN (yon = 'CIKIS'::text) THEN (- tutar)
            ELSE tutar
        END) OVER (ORDER BY tarih, yon DESC, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) AS kalan_nakit
   FROM hareket
  WHERE ((tarih >= CURRENT_DATE) OR (odendi = false))
  ORDER BY tarih, yon DESC;

CREATE OR REPLACE VIEW public.cfo_yolda_sku AS
 SELECT k.sku,
    (sum(k.adet))::integer AS yolda_adet,
    min((m."etaDate")::date) AS en_yakin_eta,
    string_agg(DISTINCT k.kod, ', '::text) AS partiler
   FROM ((cfo_yoldaki_kalem k
     JOIN cfo_yoldaki_mal ym ON ((ym.kod = k.kod)))
     LEFT JOIN cfo_import_project m ON ((m.code = k.kod)))
  WHERE ((k.sku IS NOT NULL) AND (ym.risk <> 'RISKLI'::text))
  GROUP BY k.sku;

CREATE OR REPLACE VIEW public.cfo_yoldaki_kapsam AS
 SELECT m.kod,
    m.aciklama,
    m.durum,
    m.risk,
    (p."etaDate")::date AS eta,
    m.kalem_sayisi AS beklenen_kalem,
    m.adet_toplam AS beklenen_adet,
    (count(k.id))::integer AS girilen_kalem,
    (COALESCE(sum(k.adet), (0)::bigint))::integer AS girilen_adet,
    (count(pr.id))::integer AS eslesen_kalem,
        CASE
            WHEN (COALESCE(m.kalem_sayisi, 0) = 0) THEN NULL::numeric
            ELSE round((((count(k.id))::numeric / (m.kalem_sayisi)::numeric) * (100)::numeric), 1)
        END AS kapsam_pct
   FROM (((cfo_yoldaki_mal m
     LEFT JOIN cfo_yoldaki_kalem k ON ((k.kod = m.kod)))
     LEFT JOIN "Product" pr ON ((pr.sku = k.sku)))
     LEFT JOIN cfo_import_project p ON ((p.code = m.kod)))
  GROUP BY m.kod, m.aciklama, m.durum, m.risk, p."etaDate", m.kalem_sayisi, m.adet_toplam;

CREATE OR REPLACE VIEW public.fm_memory_balance_day AS
 SELECT economic_date,
    metric_key,
    definition_version,
    value_try,
    source,
    known_at,
    fm_grade(metric_key, '*'::text, economic_date) AS grade
