CREATE OR REPLACE VIEW public.fm_memory_fx_monthly AS
 SELECT m.month,
    f.usd_try_forex_buying,
    f.ref_date,
    f.bulletin_no,
    f.is_fallback_day,
    fm_grade('usd_try'::text, '*'::text, m.month) AS usd_try_grade
   FROM (( SELECT (generate_series(('2020-08-01'::date)::timestamp with time zone, ((date_trunc('month'::text, (CURRENT_DATE)::timestamp with time zone))::date)::timestamp with time zone, '1 mon'::interval))::date AS month) m
     LEFT JOIN fm_fx_monthly f ON ((f.month = m.month)));

CREATE OR REPLACE VIEW public.fm_memory_sales_channel_month WITH (security_invoker=true) AS
 SELECT month,
