    vat_try,
    revenue_legacy_textile_try,
    (revenue_incl_vat_try - revenue_legacy_textile_try) AS revenue_alfas_incl_vat_try,
    units,
    orders,
    return_signal_orders,
    cancel_signal_orders,
    fm_grade_month('revenue_incl_vat_try'::text, channel, month) AS revenue_grade,
    fm_grade_month('units'::text, channel, month) AS units_grade,
    fm_grade_month('orders'::text, channel, month) AS orders_grade,
    fm_grade_month('returns'::text, channel, month) AS returns_grade,
    known_at_min,
    known_at_max,
    flags,
    ingest_run_id
   FROM fm_sales_channel_month f
  WHERE is_current;

