CREATE OR REPLACE VIEW public.fm_memory_stock_adjusted_company_day WITH (security_invoker=true) AS
 SELECT c.economic_date,
    c.units_total_logged AS units_observed_xml,
    COALESCE(a.delta_cum, (0)::bigint) AS units_adjustments_cum,
    (c.units_total_logged + COALESCE(a.delta_cum, (0)::bigint)) AS units_adjusted,
    c.products_logged,
        CASE
            WHEN (COALESCE(a.delta_cum, (0)::bigint) <> 0) THEN array_append(c.flags, 'manual_count_adjustment'::text)
            ELSE c.flags
        END AS flags,
    fm_grade('inventory_units'::text, '*'::text, c.economic_date) AS inventory_units_grade
   FROM (fm_stock_company_day c
     LEFT JOIN LATERAL ( SELECT sum(x.delta) AS delta_cum
           FROM fm_stock_adjustment x
          WHERE ((x.economic_date <= c.economic_date) AND (EXISTS ( SELECT 1
                   FROM fm_stock_sku_day s
                  WHERE ((s.product_id = x.product_id) AND (s.economic_date <= c.economic_date)))))) a ON (true));

CREATE OR REPLACE VIEW public.fm_memory_stock_company_day AS
 SELECT economic_date,
    units_total_logged,
    products_logged,
    products_changed,
    flags,
    fm_grade('inventory_units'::text, '*'::text, economic_date) AS inventory_units_grade
   FROM fm_stock_company_day c;

CREATE OR REPLACE VIEW public.fm_sales_source_rows WITH (security_invoker=true) AS
 SELECT 'MARKETPLACE'::text AS source_system,
    r.id AS source_row_id,
    r.channel,
        CASE
            WHEN ((r.channel = 'TRENDYOL'::text) AND (r."orderNumber" ~ '^[0-9]+-[0-9]+$'::text)) THEN split_part(r."orderNumber", '-'::text, 2)
            ELSE r."orderNumber"
        END AS order_key,
    COALESCE(r."externalLineId", r.id) AS line_key,
    (r."orderDate")::date AS economic_date,
    r.status AS status_raw,
    NULLIF(btrim(r."modelNumber"), ''::text) AS sku_raw,
    r."productId" AS product_id,
    r."productName" AS product_name,
    (r.quantity)::numeric AS quantity_raw,
    (r."totalAmountTry")::numeric AS amount_incl_vat_try,
    (r."grossAmountTry")::numeric AS amount_ex_vat_try,
    (r."vatAmountTry")::numeric AS vat_try,
    lower(btrim(COALESCE(r."customerInvoiceName", ''::text))) AS customer_name_lc,
    (r."importedAt")::timestamp without time zone AS known_at
   FROM "MarketplaceSalesRecord" r
UNION ALL
 SELECT 'TRENDYOL_API'::text AS source_system,
    t.id AS source_row_id,
    'TRENDYOL'::text AS channel,
    t."orderId" AS order_key,
    (t."lineId")::text AS line_key,
    (t."orderDate")::date AS economic_date,
    t.status AS status_raw,
    COALESCE(NULLIF(btrim(p.sku), ''::text), NULLIF(btrim(t."merchantSku"), ''::text)) AS sku_raw,
    t."productId" AS product_id,
    t."productName" AS product_name,
    (t.quantity)::numeric AS quantity_raw,
    (t."totalPriceTry")::numeric AS amount_incl_vat_try,
    NULL::numeric AS amount_ex_vat_try,
    NULL::numeric AS vat_try,
    ''::text AS customer_name_lc,
    (t."syncedAt")::timestamp without time zone AS known_at
   FROM ("TrendyolSalesRecord" t
     LEFT JOIN "Product" p ON ((p.id = t."productId")));

CREATE OR REPLACE VIEW public.fm_stock_reconciliation WITH (security_invoker=true) AS
 WITH last_chain AS (
         SELECT DISTINCT ON (fm_stock_sku_day.product_id) fm_stock_sku_day.product_id,
            fm_stock_sku_day.sku,
            fm_stock_sku_day.units_eod AS chain_last_qty,
            fm_stock_sku_day.economic_date AS chain_last_date
           FROM fm_stock_sku_day
          ORDER BY fm_stock_sku_day.product_id, fm_stock_sku_day.economic_date DESC
        ), adj AS (
         SELECT fm_stock_adjustment.product_id,
            (sum(fm_stock_adjustment.delta))::integer AS adj_delta
           FROM fm_stock_adjustment
          GROUP BY fm_stock_adjustment.product_id
        )
 SELECT l.product_id,
    l.sku,
    l.chain_last_date,
    l.chain_last_qty,
    COALESCE(a.adj_delta, 0) AS adjustments_delta,
    (l.chain_last_qty + COALESCE(a.adj_delta, 0)) AS expected_qty,
    p."stockQuantity" AS product_qty,
    (p."stockQuantity" - (l.chain_last_qty + COALESCE(a.adj_delta, 0))) AS unexplained_diff,
        CASE
            WHEN (p."stockQuantity" <> (l.chain_last_qty + COALESCE(a.adj_delta, 0))) THEN 'UNEXPLAINED'::text
            WHEN (COALESCE(a.adj_delta, 0) <> 0) THEN 'MATCH_AFTER_ADJUSTMENT'::text
            ELSE 'MATCH'::text
        END AS status
   FROM ((last_chain l
     JOIN "Product" p ON ((p.id = l.product_id)))
     LEFT JOIN adj a ON ((a.product_id = l.product_id)));

CREATE OR REPLACE VIEW public.urun_aday_katalog AS
 SELECT a.id AS aday_id,
    a.sku AS aday_sku,
    p.id AS product_id,
    p.sku AS katalog_sku,
    p.name AS katalog_ad,
    p."isActive" AS katalog_aktif
   FROM (urun_aday a
     JOIN "Product" p ON (((urun_aday_sku_num(p.sku) = urun_aday_sku_num(a.sku)) AND (urun_aday_sku_num(a.sku) IS NOT NULL))));

CREATE OR REPLACE VIEW public.cfo_gecikmis_karar AS
 SELECT tur,
    kayit_id,
    baslik,
    durum,
    acilis,
    bekleme_gun
   FROM cfo_bekleyen_karar
  WHERE (bekleme_gun >= 3)
  ORDER BY bekleme_gun DESC, tur;

CREATE OR REPLACE VIEW public.cfo_nakit_dibi AS
 SELECT tarih,
    round(kalan_nakit) AS kalan_nakit,
    (tarih - CURRENT_DATE) AS kalan_gun,
    to_char((tarih)::timestamp with time zone, 'DD.MM.YYYY'::text) AS tarih_str
   FROM cfo_yaklasan_odeme
  WHERE (tarih <= (CURRENT_DATE + 90))
  ORDER BY (round(kalan_nakit))
 LIMIT 5;

CREATE OR REPLACE VIEW public.cfo_odeme_gunluk AS
 WITH gun AS (
         SELECT cfo_yaklasan_odeme.tarih,
            count(*) FILTER (WHERE ((cfo_yaklasan_odeme.yon = 'CIKIS'::text) AND (NOT cfo_yaklasan_odeme.odendi))) AS odeme_adet,
            COALESCE(sum(cfo_yaklasan_odeme.tutar) FILTER (WHERE ((cfo_yaklasan_odeme.yon = 'CIKIS'::text) AND (NOT cfo_yaklasan_odeme.odendi))), (0)::numeric) AS cikacak,
            COALESCE(sum(cfo_yaklasan_odeme.tutar) FILTER (WHERE ((cfo_yaklasan_odeme.yon = 'GIRIS'::text) AND (NOT cfo_yaklasan_odeme.odendi))), (0)::numeric) AS girecek,
            COALESCE(sum(
                CASE
                    WHEN cfo_yaklasan_odeme.odendi THEN (0)::numeric
                    ELSE cfo_yaklasan_odeme.net_etki
                END), (0)::numeric) AS net,
            COALESCE(sum(cfo_yaklasan_odeme.tutar) FILTER (WHERE ((cfo_yaklasan_odeme.yon = 'CIKIS'::text) AND cfo_yaklasan_odeme.odendi)), (0)::numeric) AS odenmis_cikis,
            COALESCE(sum(cfo_yaklasan_odeme.tutar) FILTER (WHERE ((cfo_yaklasan_odeme.yon = 'GIRIS'::text) AND cfo_yaklasan_odeme.odendi)), (0)::numeric) AS tahsil_edilmis_giris,
            min(cfo_yaklasan_odeme.kalan_nakit) AS gun_ici_dip,
            min(cfo_yaklasan_odeme.aciliyet) AS aciliyet,
            bool_or(((cfo_yaklasan_odeme.yon = 'CIKIS'::text) AND (cfo_yaklasan_odeme.kesinlik = 'KESIN'::text) AND (NOT cfo_yaklasan_odeme.odendi))) AS kesin_odeme_var,
            bool_and(cfo_yaklasan_odeme.odendi) AS tumu_islendi
           FROM cfo_yaklasan_odeme
          GROUP BY cfo_yaklasan_odeme.tarih
        ), acilis AS (
         SELECT COALESCE(sum(cfo_bank_account."balanceTry"), (0)::numeric) AS b
           FROM cfo_bank_account
          WHERE (cfo_bank_account."isActive" = true)
        )
 SELECT tarih,
    (tarih - CURRENT_DATE) AS kalan_gun,
    to_char((tarih)::timestamp with time zone, 'DD.MM.YYYY'::text) AS tarih_str,
        CASE EXTRACT(dow FROM tarih)
            WHEN 0 THEN 'Pazar'::text
            WHEN 1 THEN 'Pazartesi'::text
            WHEN 2 THEN 'Salı'::text
            WHEN 3 THEN 'Çarşamba'::text
            WHEN 4 THEN 'Perşembe'::text
            WHEN 5 THEN 'Cuma'::text
            ELSE 'Cumartesi'::text
        END AS gun_adi,
    odeme_adet,
    cikacak,
    girecek,
    net,
    (( SELECT acilis.b
           FROM acilis) + sum(net) OVER (ORDER BY tarih ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) AS gun_sonu_nakit,
    aciliyet,
    kesin_odeme_var,
    gun_ici_dip,
    tumu_islendi,
    odenmis_cikis,
    tahsil_edilmis_giris
   FROM gun;

CREATE OR REPLACE VIEW public.cfo_satis_birim_duz AS
 WITH tekli AS (
         SELECT cfo_norm(cfo_satis_birim."modelNumber") AS nsku,
            (date_trunc('month'::text, cfo_satis_birim."orderDate"))::date AS ay,
            cfo_satis_birim."totalAmountTry" AS f
           FROM cfo_satis_birim
          WHERE ((cfo_satis_birim.quantity = 1) AND (cfo_satis_birim."modelNumber" IS NOT NULL) AND (cfo_satis_birim."totalAmountTry" > (0)::numeric))
        ), aylik AS (
         SELECT tekli.nsku,
            tekli.ay,
            percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY ((tekli.f)::double precision)) AS med,
            count(*) AS n
           FROM tekli
          GROUP BY tekli.nsku, tekli.ay
        ), genel AS (
         SELECT tekli.nsku,
            percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY ((tekli.f)::double precision)) AS med,
            count(*) AS n
           FROM tekli
          GROUP BY tekli.nsku
        ), mark AS (
         SELECT aylik.nsku,
            aylik.ay,
            aylik.n,
                CASE
                    WHEN (aylik.n >= 3) THEN aylik.med
                    ELSE NULL::double precision
                END AS g,
            count(
                CASE
                    WHEN (aylik.n >= 3) THEN 1
                    ELSE NULL::integer
                END) OVER (PARTITION BY aylik.nsku ORDER BY aylik.ay) AS gf,
            count(
                CASE
                    WHEN (aylik.n >= 3) THEN 1
                    ELSE NULL::integer
                END) OVER (PARTITION BY aylik.nsku ORDER BY aylik.ay DESC) AS gb
           FROM aylik
        ), fill AS (
         SELECT mark.nsku,
            mark.ay,
            mark.n,
            COALESCE(max(mark.g) OVER (PARTITION BY mark.nsku, mark.gf), max(mark.g) OVER (PARTITION BY mark.nsku, mark.gb)) AS tipik_ay
           FROM mark
        ), tip AS (
         SELECT f.nsku,
            f.ay,
            COALESCE(f.tipik_ay, g.med) AS tipik,
            (f.n + g.n) AS dayanak
           FROM (fill f
             JOIN genel g ON ((g.nsku = f.nsku)))
        ), h AS (
         SELECT r.id,
            r.channel,
            r."orderNumber",
            r."platformRef",
            r."externalLineId",
            r."orderDate",
            r.status,
            r."productName",
            r."productCode",
            r."modelNumber",
            r."storeStockName",
            r."productId",
            r.quantity,
            r."grossAmountTry",
            r."vatAmountTry",
            r."totalAmountTry",
            r."commissionTry",
            r."commissionPct",
            r."platformPaymentTry",
            r."customerCode",
            r."customerFirma",
            r."customerInvoiceName",
            r."customerVergiNo",
            r."customerTcKimlik",
            r."customerVergiDairesi",
            r."customerCity",
            r."cargoCompany",
            r."cargoTrackingNo",
            r."desiTotal",
            r."customerId",
            r."importedAt",
            t.tipik,
            COALESCE(t.dayanak, (0)::bigint) AS dayanak,
                CASE
                    WHEN ((t.tipik > (0)::double precision) AND (r.quantity > 0)) THEN (((r."totalAmountTry" / (r.quantity)::numeric))::double precision / t.tipik)
                    ELSE NULL::double precision
                END AS oran
           FROM (cfo_satis_birim r
             LEFT JOIN tip t ON (((t.nsku = cfo_norm(r."modelNumber")) AND (t.ay = (date_trunc('month'::text, r."orderDate"))::date))))
        )
 SELECT id,
    channel,
    "orderNumber",
    "platformRef",
    "externalLineId",
    "orderDate",
    status,
    "productName",
    "productCode",
    "modelNumber",
    "storeStockName",
    "productId",
    quantity,
    "grossAmountTry",
    "vatAmountTry",
    "totalAmountTry",
    "commissionTry",
    "commissionPct",
    "platformPaymentTry",
    "customerCode",
    "customerFirma",
    "customerInvoiceName",
    "customerVergiNo",
    "customerTcKimlik",
    "customerVergiDairesi",
    "customerCity",
    "cargoCompany",
    "cargoTrackingNo",
    "desiTotal",
    "customerId",
    "importedAt",
    tipik,
    dayanak,
    oran,
        CASE
            WHEN (quantity = 1) THEN 'YUKSEK'::text
            WHEN ((tipik IS NULL) OR (dayanak < 3)) THEN 'BILINMIYOR'::text
            WHEN ((oran >= (0.85)::double precision) AND (oran <= (1.15)::double precision)) THEN 'YUKSEK'::text
            WHEN (oran < (0.60)::double precision) THEN 'SET_DUZELTILDI'::text
            ELSE 'KARMA'::text
        END AS guven,
        CASE
            WHEN (quantity = 1) THEN 1
            WHEN ((tipik IS NULL) OR (dayanak < 3)) THEN quantity
            WHEN ((oran >= (0.85)::double precision) AND (oran <= (1.15)::double precision)) THEN quantity
            WHEN (oran > (1.15)::double precision) THEN 1
            ELSE LEAST(quantity, GREATEST(1, (floor((("totalAmountTry")::double precision / tipik)))::integer))
        END AS adet_duz,
        CASE
            WHEN (quantity = 1) THEN ("totalAmountTry")::double precision
            WHEN ((tipik IS NULL) OR (dayanak < 3)) THEN ("totalAmountTry")::double precision
            WHEN ((oran >= (0.85)::double precision) AND (oran <= (1.15)::double precision)) THEN ("totalAmountTry")::double precision
            WHEN (oran > (1.15)::double precision) THEN LEAST(("totalAmountTry")::double precision, tipik)
            ELSE LEAST(("totalAmountTry")::double precision, (tipik * (LEAST(quantity, GREATEST(1, (floor((("totalAmountTry")::double precision / tipik)))::integer)))::double precision))
        END AS tutar_duz
   FROM h;

CREATE OR REPLACE VIEW public.cfo_xml_urun_hareket AS
 SELECT sku,
    (sum(satis_adet) FILTER (WHERE (is_gunu >= (CURRENT_DATE - 30))))::integer AS xml_30g,
    (sum(satis_adet) FILTER (WHERE (is_gunu >= (CURRENT_DATE - 90))))::integer AS xml_90g,
    max(is_gunu) FILTER (WHERE (hareket_turu = 'SATIS'::text)) AS xml_son_satis,
    (sum(delta) FILTER (WHERE ((hareket_turu = ANY (ARRAY['IADE_VEYA_GIRIS'::text, 'STOK_GIRISI'::text])) AND (is_gunu >= (CURRENT_DATE - 30)))))::integer AS xml_giris_30g
   FROM cfo_xml_hareket
  GROUP BY sku;

CREATE OR REPLACE VIEW public.fm_sales_dispositioned WITH (security_invoker=true) AS
 WITH cfg AS (
         SELECT '2026-05-04'::date AS t_primary_from
        ), m_ty AS (
         SELECT fm_sales_source_rows.source_system,
            fm_sales_source_rows.source_row_id,
            fm_sales_source_rows.channel,
            fm_sales_source_rows.order_key,
            fm_sales_source_rows.line_key,
            fm_sales_source_rows.economic_date,
            fm_sales_source_rows.status_raw,
            fm_sales_source_rows.sku_raw,
            fm_sales_source_rows.product_id,
            fm_sales_source_rows.product_name,
            fm_sales_source_rows.quantity_raw,
            fm_sales_source_rows.amount_incl_vat_try,
            fm_sales_source_rows.amount_ex_vat_try,
            fm_sales_source_rows.vat_try,
            fm_sales_source_rows.customer_name_lc,
            fm_sales_source_rows.known_at
           FROM fm_sales_source_rows
          WHERE ((fm_sales_source_rows.source_system = 'MARKETPLACE'::text) AND (fm_sales_source_rows.channel = 'TRENDYOL'::text))
        ), m_keys AS (
         SELECT DISTINCT m_ty.order_key
           FROM m_ty
        ), t_keys AS (
         SELECT DISTINCT fm_sales_source_rows.order_key
           FROM fm_sales_source_rows
          WHERE (fm_sales_source_rows.source_system = 'TRENDYOL_API'::text)
        ), m_returned AS (
         SELECT m_ty.order_key
           FROM m_ty
          WHERE (m_ty.status_raw = ANY (ARRAY['İade-İptal'::text, 'İadesi Onaylanan'::text]))
          GROUP BY m_ty.order_key
        ), m_dup AS (
         SELECT DISTINCT m_ty.economic_date AS d_date,
            m_ty.sku_raw AS d_sku,
            m_ty.quantity_raw AS d_qty,
            round(COALESCE(m_ty.amount_incl_vat_try, (0)::numeric), 2) AS d_amt
           FROM m_ty
          WHERE (m_ty.sku_raw IS NOT NULL)
        ), ruled AS (
         SELECT s.source_system,
            s.source_row_id,
            s.channel,
            s.order_key,
            s.line_key,
            s.economic_date,
            s.status_raw,
            s.sku_raw,
            s.product_id,
            s.product_name,
            s.quantity_raw,
            s.amount_incl_vat_try,
            s.amount_ex_vat_try,
            s.vat_try,
            s.customer_name_lc,
            s.known_at,
                CASE
                    WHEN (s.channel <> 'TRENDYOL'::text) THEN 'SINGLE_SOURCE'::text
                    WHEN (s.source_system = 'MARKETPLACE'::text) THEN
                    CASE
                        WHEN (s.economic_date < cfg.t_primary_from) THEN 'M_PRIMARY'::text
                        WHEN (s.order_key IN ( SELECT t_keys.order_key
                           FROM t_keys)) THEN 'DEDUP_DROPPED'::text
                        ELSE 'M_FALLBACK'::text
                    END
                    ELSE
                    CASE
                        WHEN (s.economic_date >= cfg.t_primary_from) THEN 'T_PRIMARY'::text
                        WHEN (s.order_key IN ( SELECT m_keys.order_key
                           FROM m_keys)) THEN 'DEDUP_DROPPED'::text
                        ELSE 'T_GAP_FILL'::text
                    END
                END AS source_rule,
            ((s.source_system = 'TRENDYOL_API'::text) AND (s.order_key IN ( SELECT m_returned.order_key
                   FROM m_returned))) AS returned_by_marketplace
           FROM (fm_sales_source_rows s
             CROSS JOIN cfg)
        ), classed AS (
         SELECT ruled.source_system,
            ruled.source_row_id,
            ruled.channel,
            ruled.order_key,
            ruled.line_key,
            ruled.economic_date,
            ruled.status_raw,
            ruled.sku_raw,
            ruled.product_id,
            ruled.product_name,
            ruled.quantity_raw,
            ruled.amount_incl_vat_try,
            ruled.amount_ex_vat_try,
            ruled.vat_try,
            ruled.customer_name_lc,
            ruled.known_at,
            ruled.source_rule,
            ruled.returned_by_marketplace,
                CASE
                    WHEN ((ruled.source_system = 'MARKETPLACE'::text) AND (ruled.status_raw = ANY (ARRAY['İade-İptal'::text, 'İadesi Onaylanan'::text]))) THEN 'RETURN_OR_CANCEL'::text
                    WHEN ((ruled.source_system = 'MARKETPLACE'::text) AND (ruled.status_raw = 'Tedarik Edilemedi'::text)) THEN 'CANCELLED'::text
                    WHEN ((ruled.source_system = 'TRENDYOL_API'::text) AND (ruled.status_raw = 'Cancelled'::text)) THEN 'CANCELLED'::text
                    WHEN ((ruled.source_system = 'TRENDYOL_API'::text) AND ((ruled.status_raw = ANY (ARRAY['UnDeliveredAndReturned'::text, 'UnDelivered'::text])) OR ruled.returned_by_marketplace)) THEN 'RETURN_OR_CANCEL'::text
                    ELSE 'SALE'::text
                END AS status_class,
            ((ruled.customer_name_lc = 'test'::text) AND (COALESCE(ruled.amount_incl_vat_try, (0)::numeric) <= (5)::numeric)) AS is_test_order,
                CASE
                    WHEN ((ruled.sku_raw ~* '^(2[0-9](yt|kt|yd|k|y|yb)[0-9]|alinmodest|armine|21pnt|rimoli|gn.?(elbise|pijama)|acanta|copy45258)'::text) OR (ruled.product_name ~* '(armine|alinmodest|tesettür|tunik|pardesü|ferace|elbise|kadın (bluz|gömlek|pantolon|ceket|kaban|yelek|etek))'::text)) THEN 'TEXTILE_ARMINE'::text
                    ELSE NULL::text
                END AS legacy_business,
            (d.d_sku IS NOT NULL) AS marketplace_lookalike
           FROM (ruled
             LEFT JOIN m_dup d ON (((d.d_date = ruled.economic_date) AND (d.d_sku = ruled.sku_raw) AND (d.d_qty = ruled.quantity_raw) AND (d.d_amt = round(COALESCE(ruled.amount_incl_vat_try, (0)::numeric), 2)))))
        )
 SELECT source_system,
    source_row_id,
    channel,
    order_key,
    line_key,
    economic_date,
    status_raw,
    sku_raw,
    product_id,
    product_name,
    quantity_raw,
    amount_incl_vat_try,
    amount_ex_vat_try,
    vat_try,
    customer_name_lc,
    known_at,
    source_rule,
    returned_by_marketplace,
    status_class,
    is_test_order,
    legacy_business,
        CASE
            WHEN (source_rule = 'DEDUP_DROPPED'::text) THEN 'DEDUP_DROPPED'::text
            WHEN is_test_order THEN 'EXCLUDED_TEST'::text
            WHEN (status_class = 'CANCELLED'::text) THEN 'EXCLUDED_CANCELLED'::text
            WHEN (status_class = 'RETURN_OR_CANCEL'::text) THEN 'EXCLUDED_RETURN'::text
            ELSE 'COUNTED'::text
        END AS disposition,
    array_remove(ARRAY[
        CASE
            WHEN (source_rule = 'T_GAP_FILL'::text) THEN 'gap_filled_secondary'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (source_rule = 'M_FALLBACK'::text) THEN 'fallback_marketplace_only'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((source_system = 'MARKETPLACE'::text) AND (economic_date < '2022-01-01'::date)) THEN 'status_snapshot_stale'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((source_system = 'MARKETPLACE'::text) AND ((known_at)::date > (economic_date + 30))) THEN 'historical_bulk_import'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (amount_ex_vat_try IS NULL) THEN 'ex_vat_unknown'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((status_class = 'SALE'::text) AND (NOT is_test_order) AND (COALESCE(amount_incl_vat_try, (0)::numeric) = (0)::numeric)) THEN 'zero_amount'::text
            ELSE NULL::text
        END,
        CASE
            WHEN returned_by_marketplace THEN 'return_from_marketplace_status'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (channel = 'IDEASOFT'::text) THEN 'ideasoft_v1_excluded'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (legacy_business IS NOT NULL) THEN 'legacy_textile'::text
            ELSE NULL::text
        END,
        CASE
            WHEN is_test_order THEN 'test_order'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((source_system = 'TRENDYOL_API'::text) AND (order_key = '0'::text)) THEN 'invalid_order_id'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((source_rule = 'T_GAP_FILL'::text) AND marketplace_lookalike) THEN 'possible_cross_source_duplicate'::text
            ELSE NULL::text
        END], NULL::text) AS quality_flags
   FROM classed c;

CREATE OR REPLACE VIEW public.fm_stock_freshness WITH (security_invoker=true) AS
 SELECT ( SELECT max("XmlStockChangeLog"."syncedAt") AS max
           FROM "XmlStockChangeLog") AS latest_xml_log_at,
    ( SELECT max(fm_stock_sku_day.known_at_max) AS max
           FROM fm_stock_sku_day) AS memory_known_at,
    ( SELECT max(fm_ingest_run.finished_at) AS max
           FROM fm_ingest_run
          WHERE ((fm_ingest_run.kind = 'stock_refresh'::text) AND (fm_ingest_run.status = 'succeeded'::text))) AS last_successful_refresh_at,
    ( SELECT max("XmlSyncLog"."completedAt") AS max
           FROM "XmlSyncLog"
          WHERE ("XmlSyncLog".status = 'SUCCESS'::"XmlSyncStatus")) AS last_successful_sync_at,
    ( SELECT count(*) AS count
           FROM fm_stock_reconciliation
          WHERE (fm_stock_reconciliation.status = 'UNEXPLAINED'::text)) AS unexplained_products,
        CASE
            WHEN (COALESCE(( SELECT max(fm_stock_sku_day.known_at_max) AS max
               FROM fm_stock_sku_day), '1970-01-01 00:00:00'::timestamp without time zone) >= COALESCE(( SELECT max("XmlStockChangeLog"."syncedAt") AS max
               FROM "XmlStockChangeLog"), '1970-01-01 00:00:00'::timestamp without time zone)) THEN 'FRESH'::text
            ELSE 'STALE'::text
        END AS status;

CREATE OR REPLACE VIEW public.urun_aday_puan AS
 WITH g AS (
         SELECT urun_aday_gorsel.aday_id,
            count(*) FILTER (WHERE (urun_aday_gorsel.tur = ANY (ARRAY['URUN'::text, 'PAKET'::text]))) AS urun_gorsel,
            count(*) FILTER (WHERE (urun_aday_gorsel.tur = 'CINCE_BILGI'::text)) AS cince_gorsel,
            count(*) FILTER (WHERE (urun_aday_gorsel.tur = 'INFO_TR'::text)) AS info_gorsel
           FROM urun_aday_gorsel
          GROUP BY urun_aday_gorsel.aday_id
        ), k AS (
         SELECT urun_aday_katalog.aday_id,
            min(urun_aday_katalog.katalog_sku) AS katalog_sku,
            min(urun_aday_katalog.katalog_ad) AS katalog_ad,
            (count(*))::integer AS katalog_eslesme
           FROM urun_aday_katalog
          GROUP BY urun_aday_katalog.aday_id
        )
 SELECT a.id,
    a.sku,
    a.kaynak,
    a.invoice_ad,
    a.ad_tr,
    a.marka,
    a.kategori,
    a.aciklama,
    a.aciklama_1688,
    a.ozellikler,
    a.barkod,
    a.mensei,
    a.garanti_ay,
    a.adet,
    a.alis_rmb,
    a.birim_usd,
    a.gumruklu_usd,
    a.agirlik_kg,
    a.kutu_en_cm,
    a.kutu_boy_cm,
    a.kutu_yuk_cm,
    a.satis_try,
    a.kargo_try,
    a.link_1688,
    a.durum,
    a.red_sebep,
    a.note,
    a.created_at,
    a.updated_at,
    a.fatura_sku,
    COALESCE(g.urun_gorsel, (0)::bigint) AS urun_gorsel,
    COALESCE(g.cince_gorsel, (0)::bigint) AS cince_gorsel,
    COALESCE(g.info_gorsel, (0)::bigint) AS info_gorsel,
    k.katalog_sku,
    k.katalog_ad,
    COALESCE(k.katalog_eslesme, 0) AS katalog_eslesme,
    (k.katalog_sku IS NOT NULL) AS katalogda_var,
        CASE
            WHEN (length(COALESCE(a.ad_tr, ''::text)) >= 20) THEN 12
            ELSE 0
        END AS p_ad,
        CASE
            WHEN (COALESCE(a.marka, ''::text) <> ''::text) THEN 5
            ELSE 0
        END AS p_marka,
        CASE
            WHEN (COALESCE(a.kategori, ''::text) <> ''::text) THEN 9
            ELSE 0
        END AS p_kategori,
        CASE
            WHEN (length(COALESCE(a.aciklama, ''::text)) >= 400) THEN 15
            WHEN (length(COALESCE(a.aciklama, ''::text)) >= 150) THEN 7
            ELSE 0
        END AS p_aciklama,
        CASE
            WHEN (COALESCE(g.urun_gorsel, (0)::bigint) >= 1) THEN 17
            ELSE 0
        END AS p_ana_gorsel,
        CASE
            WHEN (COALESCE(g.urun_gorsel, (0)::bigint) >= 3) THEN 10
            ELSE 0
        END AS p_gorsel3,
        CASE
            WHEN (COALESCE(a.satis_try, (0)::numeric) > (0)::numeric) THEN 10
            ELSE 0
        END AS p_fiyat,
        CASE
            WHEN ((COALESCE(a.birim_usd, (0)::numeric) > (0)::numeric) AND (COALESCE(a.agirlik_kg, (0)::numeric) > (0)::numeric)) THEN 10
            ELSE 0
        END AS p_maliyet,
        CASE
            WHEN ((COALESCE(a.kutu_en_cm, (0)::numeric) > (0)::numeric) AND (COALESCE(a.kutu_boy_cm, (0)::numeric) > (0)::numeric) AND (COALESCE(a.kutu_yuk_cm, (0)::numeric) > (0)::numeric)) THEN 6
            ELSE 0
        END AS p_kutu,
        CASE
            WHEN ((COALESCE(a.mensei, ''::text) <> ''::text) AND (COALESCE(a.garanti_ay, 0) > 0)) THEN 6
            ELSE 0
        END AS p_mensei,
    a.kutu_kaynak
   FROM ((urun_aday a
     LEFT JOIN g ON ((g.aday_id = a.id)))
     LEFT JOIN k ON ((k.aday_id = a.id)));

CREATE OR REPLACE VIEW public.cfo_aylik_urun_kar AS
 WITH d AS (
         SELECT (date_trunc('month'::text, s."orderDate"))::date AS ay,
            COALESCE(s."productId", pm.id) AS prod,
            s.channel,
            s.adet_duz,
            s.tutar_duz,
                CASE
                    WHEN (COALESCE(n.kargo_payi, 0.121) = (0)::numeric) THEN (0)::numeric
                    WHEN (s.tutar_duz < (200)::double precision) THEN 53.61
                    WHEN (s.tutar_duz < (350)::double precision) THEN 91.89
                    WHEN (s.tutar_duz < (750)::double precision) THEN 106.25
                    WHEN (s.tutar_duz < (1500)::double precision) THEN 113.41
                    ELSE 154.91
                END AS kargo,
            (s.tutar_duz * ((COALESCE(n.net_oran, 0.65) + COALESCE(n.kargo_payi, 0.121)))::double precision) AS kargosuz_net,
            COALESCE(n.guven, 'DUSUK'::text) AS guven
           FROM ((cfo_satis_birim_duz s
             LEFT JOIN "Product" pm ON ((lower(pm.sku) = lower(s."modelNumber"))))
             LEFT JOIN cfo_kanal_net_oran n ON ((n.channel = s.channel)))
          WHERE (s."orderDate" >= '2025-01-01 00:00:00'::timestamp without time zone)
        ), k AS (
         SELECT d.ay,
            d.prod,
            sum(d.adet_duz) AS adet,
            count(*) AS satir,
            sum(d.tutar_duz) AS brut_ciro,
            sum(d.kargo) AS kargo_toplam,
            (sum(d.kargosuz_net) - (sum(d.kargo))::double precision) AS net_tahsilat,
            avg(d.tutar_duz) AS ort_sip,
            count(DISTINCT d.channel) AS kanal_sayisi,
            min(d.guven) AS oran_guveni
           FROM d
          WHERE (d.prod IS NOT NULL)
          GROUP BY d.ay, d.prod
        )
 SELECT k.ay,
    to_char((k.ay)::timestamp with time zone, 'YYYY-MM'::text) AS ay_str,
    p.sku,
    "left"(p.name, 70) AS ad,
    p.category,
    k.adet,
    k.satir AS siparis_satiri,
    round(k.brut_ciro) AS brut_ciro,
    round(k.ort_sip) AS ort_siparis_tutari,
    round(k.kargo_toplam) AS kargo_toplam,
    round(((((100.0 * k.kargo_toplam))::double precision / NULLIF(k.brut_ciro, (0)::double precision)))::numeric, 1) AS kargo_pct,
    round(k.net_tahsilat) AS net_tahsilat,
    p."unitCostTry" AS birim_maliyet,
    round(((k.adet)::numeric * p."unitCostTry")) AS toplam_maliyet,
    round((k.net_tahsilat - (((k.adet)::numeric * p."unitCostTry"))::double precision)) AS net_kar,
    round(((((k.net_tahsilat - (((k.adet)::numeric * p."unitCostTry"))::double precision) / NULLIF(k.brut_ciro, (0)::double precision)))::numeric * (100)::numeric), 1) AS marj_pct,
    round(((k.net_tahsilat - (((k.adet)::numeric * p."unitCostTry"))::double precision) / (NULLIF(k.adet, 0))::double precision)) AS birim_kar,
    k.kanal_sayisi,
    k.oran_guveni
   FROM (k
     JOIN "Product" p ON ((p.id = k.prod)))
  WHERE (p."unitCostTry" IS NOT NULL);

CREATE OR REPLACE VIEW public.cfo_nakit_mutabakat AS
 WITH banka AS (
         SELECT COALESCE(sum(cfo_bank_account."balanceTry"), (0)::numeric) AS b,
            min(cfo_bank_account."lastUpdatedAt") AS en_eski,
            max(cfo_bank_account."lastUpdatedAt") AS en_yeni
           FROM cfo_bank_account
          WHERE cfo_bank_account."isActive"
        ), isaretsiz_giris AS (
         SELECT COALESCE(sum(cfo_receivable."amountTry"), (0)::numeric) AS t,
            count(*) AS n
           FROM cfo_receivable
          WHERE ((NOT cfo_receivable."isCollected") AND ((cfo_receivable."dueDate")::date <= CURRENT_DATE))
        ), isaretsiz_cikis AS (
         SELECT COALESCE(sum(cfo_cash_event."outflowTry"), (0)::numeric) AS t,
            count(*) AS n
           FROM cfo_cash_event
          WHERE ((NOT cfo_cash_event."isSettled") AND ((cfo_cash_event."eventDate")::date < CURRENT_DATE) AND (cfo_cash_event."outflowTry" IS NOT NULL))
        ), bugun AS (
         SELECT COALESCE(cfo_odeme_gunluk.gun_sonu_nakit, (0)::numeric) AS g
           FROM cfo_odeme_gunluk
          WHERE (cfo_odeme_gunluk.tarih = CURRENT_DATE)
        )
 SELECT ( SELECT banka.b
           FROM banka) AS banka_nakit,
    ( SELECT (banka.en_eski)::date AS en_eski
           FROM banka) AS en_eski_bakiye,
    ( SELECT isaretsiz_giris.t
           FROM isaretsiz_giris) AS isaretsiz_tahsilat,
    ( SELECT isaretsiz_giris.n
           FROM isaretsiz_giris) AS isaretsiz_tahsilat_adet,
    ( SELECT isaretsiz_cikis.t
           FROM isaretsiz_cikis) AS isaretsiz_odeme,
    ( SELECT isaretsiz_cikis.n
           FROM isaretsiz_cikis) AS isaretsiz_odeme_adet,
        CASE
            WHEN (( SELECT isaretsiz_giris.n
               FROM isaretsiz_giris) > 0) THEN (((('🔴 '::text || ( SELECT isaretsiz_giris.n
               FROM isaretsiz_giris)) || ' TAHSILAT ISARETLENMEMIS ('::text) || round(( SELECT isaretsiz_giris.t
               FROM isaretsiz_giris))) || ' TL) — nakit OLDUGUNDAN FAZLA gorunuyor'::text)
            WHEN (( SELECT isaretsiz_cikis.n
               FROM isaretsiz_cikis) > 0) THEN (((('🔴 '::text || ( SELECT isaretsiz_cikis.n
               FROM isaretsiz_cikis)) || ' ODEME ISARETLENMEMIS ('::text) || round(( SELECT isaretsiz_cikis.t
               FROM isaretsiz_cikis))) || ' TL) — nakit OLDUGUNDAN AZ gorunuyor'::text)
            WHEN (( SELECT (banka.en_eski)::date AS en_eski
               FROM banka) < (CURRENT_DATE - 3)) THEN (('🟡 En eski banka bakiyesi '::text || ( SELECT (banka.en_eski)::date AS en_eski
               FROM banka)) || ' — bayat'::text)
            ELSE '🟢 Mutabik: banka bakiyesi ile takvim ayni tabandan basliyor'::text
        END AS durum;

CREATE OR REPLACE VIEW public.cfo_satis_atfedilmemis AS
 SELECT "orderDate",
    channel,
    "orderNumber",
    "modelNumber",
    "productName",
    guven,
    quantity AS ham_adet,
    adet_duz,
    "totalAmountTry" AS siparis_tutari,
    tutar_duz AS atfedilen,
    (("totalAmountTry")::double precision - tutar_duz) AS atfedilmemis
   FROM cfo_satis_birim_duz
  WHERE ((("totalAmountTry")::double precision - tutar_duz) > (0.01)::double precision);

CREATE OR REPLACE VIEW public.cfo_satis_kapsam AS
 WITH gunler AS (
         SELECT (generate_series(((CURRENT_DATE - 120))::timestamp with time zone, (CURRENT_DATE)::timestamp with time zone, '1 day'::interval))::date AS gun
        ), satis AS (
         SELECT (cfo_satis_birim_duz."orderDate")::date AS gun,
            (sum(cfo_satis_birim_duz.adet_duz))::integer AS adet,
            (sum(cfo_satis_birim_duz.tutar_duz))::numeric AS tutar
           FROM cfo_satis_birim_duz
          GROUP BY ((cfo_satis_birim_duz."orderDate")::date)
        ), xml AS (
         SELECT cfo_xml_hareket.is_gunu AS gun,
            (sum(cfo_xml_hareket.satis_adet))::integer AS adet,
            (count(*))::integer AS hareket
           FROM cfo_xml_hareket
          WHERE (cfo_xml_hareket.hareket_turu = 'SATIS'::text)
          GROUP BY cfo_xml_hareket.is_gunu
        )
 SELECT g.gun,
    COALESCE(s.adet, 0) AS satis_adet,
    round(COALESCE(s.tutar, (0)::numeric)) AS satis_tutar,
    COALESCE(x.adet, 0) AS xml_adet,
    COALESCE(x.hareket, 0) AS xml_hareket,
    (s.adet IS NOT NULL) AS satis_verisi_var,
    (x.adet IS NOT NULL) AS xml_sinyali_var,
        CASE
            WHEN (s.adet IS NOT NULL) THEN 'SATIS_VERISI'::text
            WHEN (x.adet IS NOT NULL) THEN 'XML_SINYALI'::text
            ELSE 'VERI_YOK'::text
        END AS kaynak
   FROM ((gunler g
     LEFT JOIN satis s ON ((s.gun = g.gun)))
     LEFT JOIN xml x ON ((x.gun = g.gun)));

CREATE OR REPLACE VIEW public.cfo_stok_deger AS
 WITH satis AS (
         SELECT COALESCE(d."productId", pm.id) AS pid,
            sum(d.adet_duz) AS adet,
            sum(d.tutar_duz) AS tutar,
            sum((d.tutar_duz * ((COALESCE(n.net_oran, 0.65) + COALESCE(n.kargo_payi, 0.121)))::double precision)) AS kargosuz_net,
            (sum((d.tutar_duz * (COALESCE(n.kargo_payi, 0.121))::double precision)) / NULLIF(sum(d.tutar_duz), (0)::double precision)) AS kargo_payi
           FROM ((cfo_satis_birim_duz d
             LEFT JOIN "Product" pm ON ((pm.sku = d."productCode")))
             LEFT JOIN cfo_kanal_net_oran n ON ((n.channel = d.channel)))
          WHERE ((d."orderDate" >= (CURRENT_DATE - 90)) AND (d.adet_duz > 0))
          GROUP BY COALESCE(d."productId", pm.id)
        ), t AS (
         SELECT p.id,
            p.sku,
            p.name,
            p.category,
            p."stockQuantity" AS stok,
            p."unitCostTry" AS birim_maliyet,
            ((p."stockQuantity" <> ALL (ARRAY[500, 998, 999, 1000, 9999, 10000])) AND (p."stockQuantity" <= 5000)) AS gercek_stok,
            ((s.tutar / (NULLIF(s.adet, 0))::double precision))::numeric AS birim_fiyat,
            ((s.kargosuz_net / (NULLIF(s.adet, 0))::double precision))::numeric AS birim_brut_net,
            (s.kargo_payi)::numeric AS kargo_payi,
            ((s.adet)::numeric / 90.0) AS gunluk_hiz
           FROM ("Product" p
             LEFT JOIN satis s ON ((s.pid = p.id)))
          WHERE (p."isActive" AND (p."stockQuantity" > 0))
        ), k AS (
         SELECT t.id,
            t.sku,
            t.name,
            t.category,
            t.stok,
            t.birim_maliyet,
            t.gercek_stok,
            t.birim_fiyat,
            t.birim_brut_net,
            t.kargo_payi,
            t.gunluk_hiz,
                CASE
                    WHEN (t.birim_fiyat IS NULL) THEN NULL::numeric
                    WHEN (COALESCE(t.kargo_payi, 0.121) = (0)::numeric) THEN (0)::numeric
                    WHEN (t.birim_fiyat < (200)::numeric) THEN 53.61
                    WHEN (t.birim_fiyat < (350)::numeric) THEN 91.89
                    WHEN (t.birim_fiyat < (750)::numeric) THEN 106.25
                    WHEN (t.birim_fiyat < (1500)::numeric) THEN 113.41
                    ELSE 154.91
                END AS birim_kargo
           FROM t
        )
 SELECT id,
    sku,
    name,
    category,
    stok,
    birim_maliyet,
    gercek_stok,
    birim_fiyat,
    birim_brut_net,
    kargo_payi,
    gunluk_hiz,
    birim_kargo,
        CASE
            WHEN (birim_fiyat IS NOT NULL) THEN 'GERCEKLESEN_SATIS'::text
            WHEN (birim_maliyet IS NOT NULL) THEN 'MALIYET'::text
            ELSE 'DEGERSIZ'::text
        END AS deger_kaynagi,
    round(COALESCE((birim_brut_net - birim_kargo), birim_maliyet, (0)::numeric), 2) AS birim_net_deger,
    round(((stok)::numeric * COALESCE((birim_brut_net - birim_kargo), birim_maliyet, (0)::numeric)), 2) AS net_deger,
    round(((stok)::numeric * COALESCE(birim_maliyet, (0)::numeric)), 2) AS maliyet_degeri,
        CASE
            WHEN (gunluk_hiz > (0)::numeric) THEN round(((stok)::numeric / gunluk_hiz), 0)
            ELSE NULL::numeric
        END AS ortu_gun
   FROM k;

CREATE OR REPLACE VIEW public.fm_sales_canonical WITH (security_invoker=true) AS
 WITH disp AS MATERIALIZED (
         SELECT fm_sales_dispositioned.source_system,
            fm_sales_dispositioned.source_row_id,
            fm_sales_dispositioned.channel,
            fm_sales_dispositioned.order_key,
            fm_sales_dispositioned.line_key,
            fm_sales_dispositioned.economic_date,
            fm_sales_dispositioned.status_raw,
            fm_sales_dispositioned.sku_raw,
            fm_sales_dispositioned.product_id,
            fm_sales_dispositioned.product_name,
            fm_sales_dispositioned.quantity_raw,
            fm_sales_dispositioned.amount_incl_vat_try,
            fm_sales_dispositioned.amount_ex_vat_try,
            fm_sales_dispositioned.vat_try,
            fm_sales_dispositioned.customer_name_lc,
            fm_sales_dispositioned.known_at,
            fm_sales_dispositioned.source_rule,
            fm_sales_dispositioned.returned_by_marketplace,
            fm_sales_dispositioned.status_class,
            fm_sales_dispositioned.is_test_order,
            fm_sales_dispositioned.legacy_business,
            fm_sales_dispositioned.disposition,
            fm_sales_dispositioned.quality_flags
           FROM fm_sales_dispositioned
        ), counted AS (
         SELECT disp.source_system,
            disp.source_row_id,
            disp.channel,
            disp.order_key,
            disp.line_key,
            disp.economic_date,
            disp.status_raw,
            disp.sku_raw,
            disp.product_id,
            disp.product_name,
            disp.quantity_raw,
            disp.amount_incl_vat_try,
            disp.amount_ex_vat_try,
            disp.vat_try,
            disp.customer_name_lc,
            disp.known_at,
            disp.source_rule,
            disp.returned_by_marketplace,
            disp.status_class,
            disp.is_test_order,
            disp.legacy_business,
            disp.disposition,
            disp.quality_flags
           FROM disp
          WHERE (disp.disposition = 'COUNTED'::text)
        ), tekli AS (
         SELECT cfo_norm(counted.sku_raw) AS nsku,
            (date_trunc('month'::text, (counted.economic_date)::timestamp with time zone))::date AS ay,
            (counted.amount_incl_vat_try)::double precision AS f
           FROM counted
          WHERE ((counted.quantity_raw = (1)::numeric) AND (counted.sku_raw IS NOT NULL) AND (counted.amount_incl_vat_try > (0)::numeric))
        ), aylik AS (
         SELECT tekli.nsku,
            tekli.ay,
            percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY tekli.f) AS med,
            count(*) AS n
           FROM tekli
          GROUP BY tekli.nsku, tekli.ay
        ), genel AS (
         SELECT tekli.nsku,
            percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY tekli.f) AS med,
            count(*) AS n
           FROM tekli
          GROUP BY tekli.nsku
        ), mark AS (
         SELECT aylik.nsku,
            aylik.ay,
            aylik.n,
                CASE
                    WHEN (aylik.n >= 3) THEN aylik.med
                    ELSE NULL::double precision
                END AS g,
            count(
                CASE
                    WHEN (aylik.n >= 3) THEN 1
                    ELSE NULL::integer
                END) OVER (PARTITION BY aylik.nsku ORDER BY aylik.ay) AS gf,
            count(
                CASE
                    WHEN (aylik.n >= 3) THEN 1
                    ELSE NULL::integer
                END) OVER (PARTITION BY aylik.nsku ORDER BY aylik.ay DESC) AS gb
           FROM aylik
        ), fill AS (
         SELECT mark.nsku,
            mark.ay,
            mark.n,
            COALESCE(max(mark.g) OVER (PARTITION BY mark.nsku, mark.gf), max(mark.g) OVER (PARTITION BY mark.nsku, mark.gb)) AS tipik_ay
           FROM mark
        ), tip AS (
         SELECT f.nsku,
            f.ay,
            COALESCE(f.tipik_ay, g.med) AS tipik,
            (f.n + g.n) AS dayanak
           FROM (fill f
             JOIN genel g USING (nsku))
        ), qty AS (
         SELECT c.source_system,
            c.source_row_id,
            t.tipik,
            COALESCE(t.dayanak, (0)::bigint) AS dayanak,
                CASE
                    WHEN ((t.tipik > (0)::double precision) AND (c.quantity_raw > (0)::numeric)) THEN (((c.amount_incl_vat_try)::double precision / (c.quantity_raw)::double precision) / t.tipik)
                    ELSE NULL::double precision
                END AS oran
           FROM (counted c
             LEFT JOIN tip t ON (((t.nsku = cfo_norm(c.sku_raw)) AND (t.ay = (date_trunc('month'::text, (c.economic_date)::timestamp with time zone))::date))))
        ), qty2 AS (
         SELECT d.source_system,
            d.source_row_id,
            d.channel,
            d.order_key,
            d.line_key,
            d.economic_date,
            d.status_raw,
            d.sku_raw,
            d.product_id,
            d.product_name,
            d.quantity_raw,
            d.amount_incl_vat_try,
            d.amount_ex_vat_try,
            d.vat_try,
            d.customer_name_lc,
            d.known_at,
            d.source_rule,
            d.returned_by_marketplace,
            d.status_class,
            d.is_test_order,
            d.legacy_business,
            d.disposition,
            d.quality_flags,
                CASE
                    WHEN (d.quantity_raw = (1)::numeric) THEN d.quantity_raw
                    WHEN ((q.tipik IS NULL) OR (q.dayanak < 3)) THEN d.quantity_raw
                    WHEN ((q.oran >= (0.85)::double precision) AND (q.oran <= (1.15)::double precision)) THEN d.quantity_raw
                    WHEN (q.oran > (1.15)::double precision) THEN (1)::numeric
                    ELSE LEAST(d.quantity_raw, GREATEST((1)::numeric, (floor(((d.amount_incl_vat_try)::double precision / q.tipik)))::numeric))
                END AS quantity_canonical
           FROM (disp d
             LEFT JOIN qty q ON (((q.source_system = d.source_system) AND (q.source_row_id = d.source_row_id) AND (d.disposition = 'COUNTED'::text))))
          WHERE (d.disposition <> 'DEDUP_DROPPED'::text)
        )
 SELECT ((((channel || '|'::text) || order_key) || '|'::text) || line_key) AS sale_key,
    source_system,
    source_row_id,
    source_rule,
    disposition,
    status_raw,
    status_class,
    channel,
    order_key,
    line_key,
    economic_date,
    sku_raw,
    product_id,
    product_name,
    legacy_business,
    quantity_raw,
        CASE
            WHEN (disposition = 'COUNTED'::text) THEN quantity_canonical
            ELSE (0)::numeric
        END AS units_counted,
    amount_incl_vat_try,
    amount_ex_vat_try,
    vat_try,
        CASE
            WHEN (disposition = 'COUNTED'::text) THEN COALESCE(amount_incl_vat_try, (0)::numeric)
            ELSE (0)::numeric
        END AS revenue_incl_vat_try,
    (disposition = 'COUNTED'::text) AS counts_as_sale,
    known_at,
        CASE
            WHEN ((disposition = 'COUNTED'::text) AND (quantity_canonical <> quantity_raw)) THEN array_append(quality_flags, 'set_qty_corrected'::text)
            ELSE quality_flags
        END AS quality_flags
   FROM qty2;

CREATE OR REPLACE VIEW public.fm_sales_reconciliation_monthly WITH (security_invoker=true) AS
 SELECT (date_trunc('month'::text, (economic_date)::timestamp with time zone))::date AS month,
    channel,
    source_system,
    source_rule,
    disposition,
    count(*) AS source_rows,
    COALESCE(sum(amount_incl_vat_try), (0)::numeric) AS raw_amount_incl_vat_try
   FROM fm_sales_dispositioned
  GROUP BY ((date_trunc('month'::text, (economic_date)::timestamp with time zone))::date), channel, source_system, source_rule, disposition;

CREATE OR REPLACE VIEW public.urun_aday_skor AS
 SELECT id,
    sku,
    kaynak,
    invoice_ad,
    ad_tr,
    marka,
    kategori,
    aciklama,
    aciklama_1688,
    ozellikler,
    barkod,
    mensei,
    garanti_ay,
    adet,
    alis_rmb,
    birim_usd,
    gumruklu_usd,
    agirlik_kg,
    kutu_en_cm,
    kutu_boy_cm,
    kutu_yuk_cm,
    satis_try,
    kargo_try,
    link_1688,
    durum,
    red_sebep,
    note,
    created_at,
    updated_at,
    fatura_sku,
    urun_gorsel,
    cince_gorsel,
    info_gorsel,
    katalog_sku,
    katalog_ad,
    katalog_eslesme,
    katalogda_var,
    p_ad,
    p_marka,
    p_kategori,
    p_aciklama,
    p_ana_gorsel,
    p_gorsel3,
    p_fiyat,
    p_maliyet,
    p_kutu,
    p_mensei,
    kutu_kaynak,
    (((((((((p_ad + p_marka) + p_kategori) + p_aciklama) + p_ana_gorsel) + p_gorsel3) + p_fiyat) + p_maliyet) + p_kutu) + p_mensei) AS puan,
        CASE
            WHEN (katalog_sku IS NOT NULL) THEN ARRAY[]::text[]
            ELSE array_remove(ARRAY[
            CASE
                WHEN (p_ad = 0) THEN 'Türkçe ad (en az 20 karakter)'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (p_marka = 0) THEN 'Marka'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (p_kategori = 0) THEN 'Kategori'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (p_aciklama < 15) THEN 'Açıklama (400+ karakter)'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (p_ana_gorsel = 0) THEN 'Ürün görseli'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (p_gorsel3 = 0) THEN 'En az 3 ürün görseli'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (p_fiyat = 0) THEN 'Satış fiyatı'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (p_maliyet = 0) THEN 'Birim maliyet + ağırlık'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (p_kutu = 0) THEN 'Kutu ölçüsü (desi)'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (p_mensei = 0) THEN 'Menşei + garanti süresi'::text
                ELSE NULL::text
            END], NULL::text)
        END AS eksikler
   FROM urun_aday_puan p;

CREATE OR REPLACE VIEW public.cfo_ciro_hedef AS
 WITH kural AS (
         SELECT COALESCE(max(cfo_settings."monthlyRevenueTargetUsd"), (100000)::numeric) AS hedef_usd,
            COALESCE(max(cfo_settings."usdTryRate"), 48.5) AS kur
           FROM cfo_settings
        ), son_tam AS (
         SELECT cfo_aylik_urun_kar.ay,
            cfo_aylik_urun_kar.ay_str,
            sum(cfo_aylik_urun_kar.brut_ciro) AS ciro_try,
            sum(cfo_aylik_urun_kar.adet) AS adet
           FROM cfo_aylik_urun_kar
          WHERE (cfo_aylik_urun_kar.ay < date_trunc('month'::text, (CURRENT_DATE)::timestamp with time zone))
          GROUP BY cfo_aylik_urun_kar.ay, cfo_aylik_urun_kar.ay_str
          ORDER BY cfo_aylik_urun_kar.ay DESC
         LIMIT 1
        )
 SELECT s.ay_str AS ay,
    round((s.ciro_try)::numeric, 0) AS ciro_try,
    round(((s.ciro_try / (k.kur)::double precision))::numeric, 0) AS ciro_usd,
    k.hedef_usd,
    round(((((s.ciro_try / (k.kur)::double precision) / (NULLIF(k.hedef_usd, (0)::numeric))::double precision) * (100)::double precision))::numeric, 1) AS hedef_pct,
    round((((k.hedef_usd)::double precision - (s.ciro_try / (k.kur)::double precision)))::numeric, 0) AS acik_usd,
    round((((k.hedef_usd)::double precision / NULLIF((s.ciro_try / (k.kur)::double precision), (0)::double precision)))::numeric, 2) AS gereken_kat,
    (s.adet)::integer AS adet
   FROM (son_tam s
     CROSS JOIN kural k);

CREATE OR REPLACE VIEW public.cfo_ithalat_oneri AS
 WITH kural AS (
         SELECT COALESCE(max(cfo_settings."importAirLeadDays"), 22) AS air_lead,
            COALESCE(max(cfo_settings."importSeaLeadDays"), 67) AS sea_lead,
            COALESCE(max(cfo_settings."importMinLineQty"), 5) AS min_adet,
            COALESCE(max(cfo_settings."usdTryRate"), 48.5) AS kur
           FROM cfo_settings
        ), ham AS (
         SELECT l.id,
            l.batch_id,
            l.sku,
            l.product_name,
            l.qty,
            l.unit_cost_usd,
            l.total_usd,
            l.priority,
            l.reason,
            l.monthly_sales,
            l.stock_now,
            l.stockout_date,
            l.wait_cost_try_monthly,
            l.data_tag,
            l.status,
            l.added_at,
            l.note,
            b.transport_mode,
            b.status AS batch_status,
            b.cash_gate,
            b.decision
           FROM (cfo_order_line l
             JOIN cfo_order_batch b ON ((b.id = l.batch_id)))
          WHERE ((l.status = 'BEKLIYOR'::text) AND (COALESCE(l.qty, 0) > 0) AND (b.status = ANY (ARRAY['ACIK'::text, 'PLANLANIYOR'::text])))
        ), tekil AS (
         SELECT DISTINCT ON (ham.transport_mode, ham.sku) ham.transport_mode AS mod,
            ham.sku,
            ham.product_name,
            ham.qty,
            ham.unit_cost_usd,
            ham.monthly_sales,
            ham.stock_now,
            ham.stockout_date,
            ham.wait_cost_try_monthly,
            ham.priority,
            ham.data_tag,
            ham.batch_id,
            ham.reason
           FROM ham
          ORDER BY ham.transport_mode, ham.sku, ham.added_at DESC NULLS LAST, ham.id DESC
        ), kopru AS (
         SELECT ham.sku
           FROM ham
          GROUP BY ham.sku
         HAVING (count(DISTINCT ham.transport_mode) > 1)
        ), fiyat AS (
         SELECT cfo_aylik_urun_kar.sku,
            ((sum(cfo_aylik_urun_kar.brut_ciro) / (NULLIF(sum(cfo_aylik_urun_kar.adet), (0)::numeric))::double precision))::numeric AS birim_fiyat_try
           FROM cfo_aylik_urun_kar
          WHERE (cfo_aylik_urun_kar.ay >= (date_trunc('month'::text, (CURRENT_DATE)::timestamp with time zone) - '3 mons'::interval))
          GROUP BY cfo_aylik_urun_kar.sku
        )
 SELECT t.mod,
    t.sku,
    t.product_name,
    t.priority,
    t.data_tag,
    t.batch_id AS kaynak_parti,
    t.reason,
    t.qty AS parti_adedi,
    GREATEST(t.qty, k.min_adet) AS onerilen_adet,
    (GREATEST(t.qty, k.min_adet) > t.qty) AS min_adet_uygulandi,
    t.unit_cost_usd AS birim_maliyet_usd,
    round(((GREATEST(t.qty, k.min_adet))::numeric * t.unit_cost_usd), 2) AS tutar_usd,
    (t.unit_cost_usd IS NULL) AS maliyet_eksik,
    t.monthly_sales AS aylik_satis,
    t.stock_now AS stok,
    COALESCE(t.stockout_date, (CURRENT_DATE + ((((COALESCE(t.stock_now, 0))::numeric / NULLIF(t.monthly_sales, (0)::numeric)) * (30)::numeric))::integer)) AS tukenis_tarihi,
        CASE
            WHEN (t.mod = 'HAVA'::text) THEN k.air_lead
            ELSE k.sea_lead
        END AS termin_gun,
    (COALESCE(t.stockout_date, (CURRENT_DATE + ((((COALESCE(t.stock_now, 0))::numeric / NULLIF(t.monthly_sales, (0)::numeric)) * (30)::numeric))::integer)) -
        CASE
            WHEN (t.mod = 'HAVA'::text) THEN k.air_lead
            ELSE k.sea_lead
        END) AS son_siparis_tarihi,
    ((COALESCE(t.stockout_date, (CURRENT_DATE + ((((COALESCE(t.stock_now, 0))::numeric / NULLIF(t.monthly_sales, (0)::numeric)) * (30)::numeric))::integer)) -
        CASE
            WHEN (t.mod = 'HAVA'::text) THEN k.air_lead
            ELSE k.sea_lead
        END) < CURRENT_DATE) AS gecikti,
    (CURRENT_DATE +
        CASE
            WHEN (t.mod = 'HAVA'::text) THEN k.air_lead
            ELSE k.sea_lead
        END) AS tahmini_varis,
    round(((GREATEST(t.qty, k.min_adet))::numeric / NULLIF(t.monthly_sales, (0)::numeric)), 1) AS kapsam_ay,
    COALESCE(t.wait_cost_try_monthly, (0)::numeric) AS aylik_risk_kar_try,
    round(f.birim_fiyat_try, 2) AS birim_fiyat_try,
    round(((t.monthly_sales * f.birim_fiyat_try) / k.kur), 0) AS aylik_ciro_usd,
    (kp.sku IS NOT NULL) AS kopru,
    ka.karar,
    ka.sebep AS karar_sebep,
    ka.gecerli_bitis AS karar_bitis,
    COALESCE((ka.karar = 'ALMA'::text), false) AS haric,
    COALESCE(y.yolda_adet, 0) AS yolda_adet,
    y.en_yakin_eta AS yolda_eta,
    y.partiler AS yolda_parti,
    ((y.yolda_adet IS NOT NULL) AND (y.en_yakin_eta IS NOT NULL) AND (y.en_yakin_eta <= (CURRENT_DATE +
        CASE
            WHEN (t.mod = 'HAVA'::text) THEN k.air_lead
            ELSE k.sea_lead
        END)) AND ((y.yolda_adet)::numeric >= (COALESCE(t.monthly_sales, (0)::numeric) * ((((CURRENT_DATE +
        CASE
            WHEN (t.mod = 'HAVA'::text) THEN k.air_lead
            ELSE k.sea_lead
        END) - y.en_yakin_eta))::numeric / (30)::numeric)))) AS yolda_yeterli,
    (row_number() OVER (PARTITION BY t.mod ORDER BY COALESCE(t.wait_cost_try_monthly, (0)::numeric) DESC, t.priority, t.sku))::integer AS sira
   FROM (((((tekil t
     CROSS JOIN kural k)
     LEFT JOIN fiyat f ON ((f.sku = t.sku)))
     LEFT JOIN kopru kp ON ((kp.sku = t.sku)))
     LEFT JOIN cfo_urun_karar ka ON (((ka.sku = t.sku) AND ((ka.gecerli_bitis IS NULL) OR (ka.gecerli_bitis >= CURRENT_DATE)))))
     LEFT JOIN cfo_yolda_sku y ON ((y.sku = t.sku)));

CREATE OR REPLACE VIEW public.cfo_olu_stok AS
 WITH esik AS (
         SELECT (COALESCE(max(cfo_settings."deadStockSalesRatioPct"), (20)::numeric) / 100.0) AS oran
           FROM cfo_settings
        ), kapsam AS (
         SELECT COALESCE(max(cfo_satis_kapsam.gun) FILTER (WHERE cfo_satis_kapsam.satis_verisi_var), CURRENT_DATE) AS satis_son_gun
           FROM cfo_satis_kapsam
        ), d AS (
         SELECT COALESCE(s."productId", pm.id) AS prod,
            s.adet_duz,
            s.tutar_duz,
            s."orderDate",
            s.channel
           FROM (cfo_satis_birim_duz s
             LEFT JOIN "Product" pm ON ((lower(pm.sku) = lower(s."modelNumber"))))
          WHERE (s."orderDate" >= (CURRENT_DATE - 400))
        ), a AS (
         SELECT d.prod,
            COALESCE(sum(d.adet_duz) FILTER (WHERE (d."orderDate" >= (CURRENT_DATE - 30))), (0)::bigint) AS a30,
            COALESCE(sum(d.adet_duz) FILTER (WHERE (d."orderDate" >= (CURRENT_DATE - 90))), (0)::bigint) AS a90,
            COALESCE(sum(d.adet_duz), (0)::bigint) AS a400,
            COALESCE(sum(d.adet_duz) FILTER (WHERE ((d."orderDate" >= (CURRENT_DATE - 90)) AND (d.channel = 'AMAZON_FBA'::text))), (0)::bigint) AS fba90,
            (COALESCE(sum(d.tutar_duz) FILTER (WHERE (d."orderDate" >= (CURRENT_DATE - 90))), (0)::double precision))::numeric AS t90,
            (max(d."orderDate"))::date AS son_satis
           FROM d
          WHERE (d.prod IS NOT NULL)
          GROUP BY d.prod
        ), x AS (
         SELECT p.sku,
            "left"(p.name, 60) AS ad,
            p."stockQuantity" AS stok,
            round((p."unitCostTry")::numeric, 2) AS birim_maliyet,
            round(COALESCE(((p."stockQuantity")::numeric * p."unitCostTry"), sd.net_deger)) AS bagli_sermaye,
            COALESCE(NULLIF(sd.maliyet_degeri, (0)::numeric), sd.net_deger) AS stok_deger,
            COALESCE(sd.deger_kaynagi,
                CASE
                    WHEN (p."unitCostTry" IS NOT NULL) THEN 'MALIYET'::text
                    ELSE 'DEGERSIZ'::text
                END) AS deger_kaynagi,
            COALESCE(a.a30, (0)::bigint) AS adet_30g,
            COALESCE(a.a90, (0)::bigint) AS adet_90g,
            COALESCE(a.a400, (0)::bigint) AS adet_400g,
            COALESCE(a.fba90, (0)::bigint) AS fba_90g,
            round(COALESCE(a.t90, (0)::numeric)) AS satis_90g_try,
            a.son_satis,
            (CURRENT_DATE - a.son_satis) AS gecen_gun,
                CASE
                    WHEN (COALESCE(a.a90, (0)::bigint) > 0) THEN round(((p."stockQuantity")::numeric / ((a.a90)::numeric / 90.0)))
                    ELSE NULL::numeric
                END AS ortu_gun,
            COALESCE(xh.xml_30g, 0) AS xml_30g,
            COALESCE(xh.xml_90g, 0) AS xml_90g,
            xh.xml_son_satis,
            ( SELECT kapsam.satis_son_gun
                   FROM kapsam) AS satis_verisi_son_gun,
            (CURRENT_DATE - ( SELECT kapsam.satis_son_gun
                   FROM kapsam)) AS satis_verisi_bayat_gun
           FROM ((("Product" p
             LEFT JOIN a ON ((a.prod = p.id)))
             LEFT JOIN cfo_stok_deger sd ON ((sd.sku = p.sku)))
             LEFT JOIN cfo_xml_urun_hareket xh ON ((xh.sku = p.sku)))
          WHERE ((p."stockQuantity" >= 1) AND ((p."stockQuantity" <> ALL (ARRAY[500, 998, 999, 1000, 9999, 10000])) AND (p."stockQuantity" <= 5000)) AND ((p."unitCostTry" IS NOT NULL) OR (COALESCE(sd.net_deger, (0)::numeric) > (0)::numeric)) AND (NOT (EXISTS ( SELECT 1
                   FROM cfo_stok_istisna i
                  WHERE (i.sku = p.sku)))))
        ), o AS (
         SELECT x.sku,
            x.ad,
            x.stok,
            x.birim_maliyet,
            x.bagli_sermaye,
            x.stok_deger,
            x.deger_kaynagi,
            x.adet_30g,
            x.adet_90g,
            x.adet_400g,
            x.fba_90g,
            x.satis_90g_try,
            x.son_satis,
            x.gecen_gun,
            x.ortu_gun,
            x.xml_30g,
            x.xml_90g,
            x.xml_son_satis,
            x.satis_verisi_son_gun,
            x.satis_verisi_bayat_gun,
                CASE
                    WHEN (x.stok_deger > (0)::numeric) THEN (x.satis_90g_try / x.stok_deger)
                    ELSE NULL::numeric
                END AS satis_stok_orani,
            ((x.adet_30g = 0) AND (x.xml_30g = 0)) AS gercekten_30g_sifir,
            ((x.adet_90g = 0) AND (x.xml_90g = 0)) AS gercekten_90g_sifir,
                CASE
                    WHEN (x.satis_verisi_bayat_gun > 2) THEN 'BOSLUK'::text
                    ELSE 'TAM'::text
                END AS veri_durumu
           FROM x
        )
 SELECT o.sku,
    o.ad,
    o.stok,
    o.birim_maliyet,
    o.bagli_sermaye,
    o.stok_deger,
    o.deger_kaynagi,
    o.satis_90g_try,
    o.satis_stok_orani,
    o.adet_30g,
    o.adet_90g,
    o.adet_400g,
    o.fba_90g,
    o.xml_30g,
    o.xml_90g,
    o.xml_son_satis,
    o.veri_durumu,
    o.satis_verisi_son_gun,
    o.satis_verisi_bayat_gun,
    o.son_satis,
    o.gecen_gun,
    o.ortu_gun,
        CASE
            WHEN ((o.gercekten_30g_sifir OR (o.ortu_gun > (365)::numeric)) AND (o.bagli_sermaye >= (50000)::numeric)) THEN 'KIRMIZI'::text
            WHEN ((o.satis_stok_orani < ( SELECT esik.oran
               FROM esik)) AND (o.bagli_sermaye >= (50000)::numeric)) THEN 'KIRMIZI'::text
            WHEN (o.gercekten_30g_sifir OR (o.ortu_gun > (180)::numeric)) THEN 'SARI'::text
            WHEN (o.satis_stok_orani < ( SELECT esik.oran
               FROM esik)) THEN 'SARI'::text
            ELSE 'YESIL'::text
        END AS alarm,
        CASE
            WHEN o.gercekten_90g_sifir THEN '90 gunde hic satmadi'::text
            WHEN o.gercekten_30g_sifir THEN '30 gunde hic satmadi'::text
            WHEN ((o.adet_30g = 0) AND (o.xml_30g > 0)) THEN (('satis verisi yuklenmemis; XML 30 gunde '::text || o.xml_30g) || ' adet hareket gormus'::text)
            WHEN (o.ortu_gun > (365)::numeric) THEN (('stok ortusu '::text || o.ortu_gun) || ' gun (1 yildan uzun)'::text)
            WHEN (o.ortu_gun > (180)::numeric) THEN (('stok ortusu '::text || o.ortu_gun) || ' gun'::text)
            WHEN (o.satis_stok_orani < ( SELECT esik.oran
               FROM esik)) THEN (((('90 gunluk satis stok degerinin %'::text || round(((100)::numeric * o.satis_stok_orani), 1)) || ' i (esik %'::text) || round(((100)::numeric * ( SELECT esik.oran
               FROM esik)))) || ')'::text)
            ELSE 'normal'::text
        END AS alarm_sebep,
    f.id AS bulgu_id,
    f.status AS bulgu_durum,
    f.action_taken AS aksiyon,
    f.watch_note AS kontrol_notu,
    f.next_review_at AS sonraki_kontrol,
    ((f.next_review_at IS NOT NULL) AND (f.next_review_at < CURRENT_DATE)) AS kontrol_gecikti,
    f.found_at AS ilk_tespit,
    (CURRENT_DATE - f.found_at) AS yas_gun,
    f.last_checked_at AS son_kontrol,
    ((f.status = 'aksiyon_alindi'::text) OR (f.action_taken IS NOT NULL)) AS aksiyon_var
   FROM (o
     LEFT JOIN LATERAL ( SELECT g.id,
            g.found_at,
            g.sku,
            g.product_name,
            g.stock_qty,
            g.days_idle,
            g.tied_capital_try,
            g.reason_code,
            g.reason_evidence,
            g.action_taken,
            g.action_applied_at,
            g.released_capital_try,
            g.status,
            g.updated_at,
            g.created_at,
            g.next_review_at,
            g.last_checked_at,
            g.watch_note,
            g.alarm,
            g.kapanis_turu
           FROM cfo_dead_stock_finding g
          WHERE (g.sku = o.sku)
          ORDER BY g.id DESC
         LIMIT 1) f ON (true))
  WHERE (o.gercekten_30g_sifir OR (o.ortu_gun > (180)::numeric) OR (o.satis_stok_orani < ( SELECT esik.oran
           FROM esik)));

CREATE OR REPLACE VIEW public.cfo_servet_kalem AS
 SELECT 1 AS sira,
    'VARLIK'::text AS tur,
    'Nakit'::text AS kalem,
    ( SELECT round(COALESCE(sum(cfo_bank_account."balanceTry"), (0)::numeric), 2) AS round
           FROM cfo_bank_account
          WHERE cfo_bank_account."isActive") AS tutar,
    'Banka bakiyeleri (cfo_bank_account)'::text AS kaynak,
    'YUKSEK'::text AS guven
UNION ALL
 SELECT 2 AS sira,
    'VARLIK'::text AS tur,
    'Alacaklar (pazaryeri hakedis)'::text AS kalem,
    ( SELECT round(COALESCE(sum(cfo_receivable."amountTry"), (0)::numeric), 2) AS round
           FROM cfo_receivable
          WHERE (NOT cfo_receivable."isCollected")) AS tutar,
    'cfo_receivable, tahsil edilmemis'::text AS kaynak,
    'YUKSEK'::text AS guven
UNION ALL
 SELECT 3 AS sira,
    'VARLIK'::text AS tur,
    'Stok — net gerceklesebilir deger'::text AS kalem,
    ( SELECT round(COALESCE(sum(cfo_stok_deger.net_deger), (0)::numeric), 2) AS round
           FROM cfo_stok_deger
          WHERE (cfo_stok_deger.gercek_stok AND (cfo_stok_deger.deger_kaynagi = 'GERCEKLESEN_SATIS'::text))) AS tutar,
    '110 SKU: 90 gunluk gerceklesen satis fiyati x kanal net orani − kargo (bant tarifesi)'::text AS kaynak,
    'ORTA'::text AS guven
UNION ALL
 SELECT 4 AS sira,
    'VARLIK'::text AS tur,
    'Stok — satis kaniti yok, maliyetle'::text AS kalem,
    ( SELECT round(COALESCE(sum(cfo_stok_deger.net_deger), (0)::numeric), 2) AS round
           FROM cfo_stok_deger
          WHERE (cfo_stok_deger.gercek_stok AND (cfo_stok_deger.deger_kaynagi = 'MALIYET'::text))) AS tutar,
    '7 SKU: 90 gunde satis yok, birim maliyetle deger verildi'::text AS kaynak,
    'DUSUK'::text AS guven
UNION ALL
 SELECT 5 AS sira,
    'VARLIK'::text AS tur,
    'Yoldaki mal — odenmis kisim'::text AS kalem,
    ( SELECT round(COALESCE(sum(cfo_yoldaki_mal.odenmis_try), (0)::numeric), 2) AS round
           FROM cfo_yoldaki_mal
          WHERE (cfo_yoldaki_mal.risk = 'NORMAL'::text)) AS tutar,
    'cfo_yoldaki_mal: 07.26sea + ROMANYA-2408'::text AS kaynak,
    'YUKSEK'::text AS guven
UNION ALL
 SELECT 6 AS sira,
    'VARLIK'::text AS tur,
    'Yoldaki mal — odenmemis vergi/navlun (varlik tarafi)'::text AS kalem,
    ( SELECT round(COALESCE(sum((cfo_yoldaki_mal.odenmemis_vergi_try + cfo_yoldaki_mal.odenmemis_navlun_try)), (0)::numeric), 2) AS round
           FROM cfo_yoldaki_mal
          WHERE (cfo_yoldaki_mal.risk = 'NORMAL'::text)) AS tutar,
    'Mal bu tutar odenince rafa iner; karsiligi asagida borc olarak dusulur'::text AS kaynak,
    'ORTA'::text AS guven
UNION ALL
 SELECT 7 AS sira,
    'BORC'::text AS tur,
    'Krediler'::text AS kalem,
    (- ( SELECT round(COALESCE(sum(COALESCE((cfo_loan."remainingOverride")::numeric, cfo_loan."remainingTry")), (0)::numeric), 2) AS round
           FROM cfo_loan
          WHERE ((cfo_loan.status)::text = 'AKTIF'::text))) AS tutar,
    'cfo_loan AKTIF kalan anapara'::text AS kaynak,
    'YUKSEK'::text AS guven
UNION ALL
 SELECT 8 AS sira,
    'BORC'::text AS tur,
    'Kredi kartlari (toplam borc)'::text AS kalem,
    (- ( SELECT round(COALESCE(sum(cfo_credit_card."totalDebtTry"), (0)::numeric), 2) AS round
           FROM cfo_credit_card
          WHERE cfo_credit_card."isActive")) AS tutar,
    'cfo_credit_card totalDebtTry — ekstre + donem ici'::text AS kaynak,
    'YUKSEK'::text AS guven
UNION ALL
 SELECT 9 AS sira,
    'BORC'::text AS tur,
    'Yoldaki mal — odenmemis gumruk/navlun'::text AS kalem,
    (- ( SELECT round(COALESCE(sum((cfo_yoldaki_mal.odenmemis_vergi_try + cfo_yoldaki_mal.odenmemis_navlun_try)), (0)::numeric), 2) AS round
           FROM cfo_yoldaki_mal
          WHERE (cfo_yoldaki_mal.risk = 'NORMAL'::text))) AS tutar,
    '07.26sea gumruk 3.000.000 (15.10, +-%5) + navlun 339.500 · ROMANYA-2408 vergi 500.000'::text AS kaynak,
    'ORTA'::text AS guven
UNION ALL
 SELECT 10 AS sira,
    'RISKLI'::text AS tur,
    'Romanya 1. parti (adli surec) — mansete dahil degil'::text AS kalem,
    ( SELECT round(COALESCE(sum(cfo_yoldaki_mal.odenmis_try), (0)::numeric), 2) AS round
           FROM cfo_yoldaki_mal
          WHERE (cfo_yoldaki_mal.risk = 'RISKLI'::text)) AS tutar,
    'Hukuki mulkiyet Eczacinda, 5607 musadere riski, ardiye isliyor'::text AS kaynak,
    'DUSUK'::text AS guven;

CREATE OR REPLACE VIEW public.cfo_servet_likidite AS
 WITH s AS (
         SELECT
                CASE
                    WHEN (cfo_stok_deger.ortu_gun IS NULL) THEN '4_SATMIYOR'::text
                    WHEN (cfo_stok_deger.ortu_gun <= (90)::numeric) THEN '1_0-3AY'::text
                    WHEN (cfo_stok_deger.ortu_gun <= (365)::numeric) THEN '2_3-12AY'::text
                    ELSE '3_12AY+'::text
                END AS dilim,
            cfo_stok_deger.net_deger,
            cfo_stok_deger.stok,
            cfo_stok_deger.ortu_gun,
                CASE
                    WHEN ((cfo_stok_deger.ortu_gun IS NULL) OR (cfo_stok_deger.ortu_gun <= (0)::numeric)) THEN (0)::numeric
                    ELSE LEAST(1.0, (365.0 / cfo_stok_deger.ortu_gun))
                END AS yil_ici_pay
           FROM cfo_stok_deger
          WHERE cfo_stok_deger.gercek_stok
        )
 SELECT dilim,
    count(*) AS urun,
    sum(stok) AS adet,
    round(sum(net_deger)) AS net_deger,
    round(sum((net_deger * yil_ici_pay))) AS bir_yilda_nakde_donen
   FROM s
  GROUP BY dilim
  ORDER BY dilim;

CREATE OR REPLACE VIEW public.cfo_xml_kalibrasyon AS
 WITH ortak AS (
         SELECT k.gun,
            k.satis_adet,
            k.xml_adet
           FROM cfo_satis_kapsam k
          WHERE (k.satis_verisi_var AND k.xml_sinyali_var AND (k.gun >= (CURRENT_DATE - 30)))
        )
 SELECT (count(*))::integer AS gun_sayisi,
    (sum(satis_adet))::integer AS gercek_adet,
    (sum(xml_adet))::integer AS xml_adet,
    round(((100.0 * (sum(xml_adet))::numeric) / (NULLIF(sum(satis_adet), 0))::numeric), 1) AS xml_gercegin_yuzdesi,
    round((corr((satis_adet)::double precision, (xml_adet)::double precision))::numeric, 3) AS gunluk_korelasyon,
    round(avg(abs((satis_adet - xml_adet))), 1) AS ort_mutlak_sapma,
    ((count(*) >= 10) AND (((sum(xml_adet))::numeric >= ((sum(satis_adet))::numeric * 0.8)) AND ((sum(xml_adet))::numeric <= ((sum(satis_adet))::numeric * 1.2)))) AS guvenilir
   FROM ortak;

CREATE MATERIALIZED VIEW IF NOT EXISTS public.fm_sales_canonical_snapshot AS
 SELECT sale_key,
    source_system,
    channel,
    order_key,
    economic_date,
    sku_raw,
    product_id,
    legacy_business,
    disposition,
    units_counted,
    revenue_incl_vat_try,
    amount_ex_vat_try,
    vat_try,
    known_at,
    quality_flags
   FROM fm_sales_canonical WITH DATA;

CREATE OR REPLACE VIEW public.cfo_alacak_borc AS
 SELECT 'ALACAK'::text AS tur,
    r.channel AS kalem,
    sum(r."amountTry") AS tutar,
    (count(*))::integer AS adet,
    COALESCE(sum(r."amountTry") FILTER (WHERE ((r.certainty)::text = 'KESIN'::text)), (0)::numeric) AS kesin_tutar,
    (min(r."dueDate"))::date AS en_yakin,
    'cfo_receivable — tahsil edilmemiş'::text AS kaynak,
    'YUKSEK'::text AS guven
   FROM cfo_receivable r
  WHERE (NOT r."isCollected")
  GROUP BY r.channel
UNION ALL
 SELECT 'BORC'::text AS tur,
    k.kalem,
    abs(k.tutar) AS tutar,
    NULL::integer AS adet,
    (0)::numeric AS kesin_tutar,
    NULL::date AS en_yakin,
    k.kaynak,
    k.guven
   FROM cfo_servet_kalem k
  WHERE (k.tur = 'BORC'::text);

CREATE OR REPLACE VIEW public.cfo_ithalat_oneri_ozet AS
 WITH kural AS (
         SELECT COALESCE(max(cfo_settings."importMinOrderUsd"), (10000)::numeric) AS min_usd,
            COALESCE(max(cfo_settings."importMinLineQty"), 5) AS min_adet,
            COALESCE(max(cfo_settings."usdTryRate"), 48.5) AS kur,
            COALESCE(max(cfo_settings."monthlyRevenueTargetUsd"), (100000)::numeric) AS hedef_ciro_usd
           FROM cfo_settings
        ), toplam AS (
         SELECT cfo_ithalat_oneri.mod,
            (count(*))::integer AS satir,
            (sum(cfo_ithalat_oneri.onerilen_adet))::integer AS toplam_adet,
            round(sum(cfo_ithalat_oneri.tutar_usd), 2) AS toplam_usd,
            (count(*) FILTER (WHERE cfo_ithalat_oneri.maliyet_eksik))::integer AS maliyet_eksik_satir,
            (count(*) FILTER (WHERE cfo_ithalat_oneri.gecikti))::integer AS gecikmis_satir,
            (count(*) FILTER (WHERE cfo_ithalat_oneri.kopru))::integer AS kopru_satir,
            round(sum(cfo_ithalat_oneri.aylik_ciro_usd), 0) AS aylik_ciro_usd,
            round(sum(cfo_ithalat_oneri.aylik_risk_kar_try), 0) AS aylik_risk_kar_try,
            min(cfo_ithalat_oneri.son_siparis_tarihi) AS en_erken_son_siparis,
            min(cfo_ithalat_oneri.tukenis_tarihi) AS en_erken_tukenis,
            max(cfo_ithalat_oneri.termin_gun) AS termin_gun
           FROM cfo_ithalat_oneri
          WHERE ((NOT cfo_ithalat_oneri.haric) AND (NOT cfo_ithalat_oneri.yolda_yeterli))
          GROUP BY cfo_ithalat_oneri.mod
        ), disarida AS (
         SELECT cfo_ithalat_oneri.mod,
            (count(*) FILTER (WHERE cfo_ithalat_oneri.haric))::integer AS haric_satir,
            (count(*) FILTER (WHERE cfo_ithalat_oneri.yolda_yeterli))::integer AS yolda_satir
           FROM cfo_ithalat_oneri
          GROUP BY cfo_ithalat_oneri.mod
        ), bugun AS (
         SELECT COALESCE(( SELECT cfo_nakit_kapisi.nakit_try
                   FROM cfo_nakit_kapisi), (0)::numeric) AS nakit_try
        ), kapi AS (
         SELECT t_1.mod,
            ( SELECT min(g.tarih) AS min
                   FROM cfo_odeme_gunluk g
                  WHERE ((g.tarih >= CURRENT_DATE) AND (g.gun_sonu_nakit >= (t_1.toplam_usd * k_1.kur)))) AS nakit_kapisi_tarihi,
            ( SELECT max(g.tarih) AS max
                   FROM cfo_odeme_gunluk g) AS projeksiyon_sonu,
            ( SELECT max(g.gun_sonu_nakit) AS max
                   FROM cfo_odeme_gunluk g
                  WHERE (g.tarih >= CURRENT_DATE)) AS projeksiyon_en_yuksek_nakit
           FROM (toplam t_1
             CROSS JOIN kural k_1)
        )
 SELECT t.mod,
    t.satir,
    t.toplam_adet,
    t.toplam_usd,
    round((t.toplam_usd * k.kur), 2) AS toplam_try,
    t.maliyet_eksik_satir,
    t.gecikmis_satir,
    t.kopru_satir,
    COALESCE(d.haric_satir, 0) AS haric_satir,
    COALESCE(d.yolda_satir, 0) AS yolda_satir,
    t.termin_gun,
    t.en_erken_tukenis,
    t.en_erken_son_siparis,
    GREATEST(CURRENT_DATE, t.en_erken_son_siparis) AS ideal_siparis_tarihi,
    k.min_usd AS min_tutar_usd,
    k.min_adet AS min_adet_kural,
    (t.toplam_usd >= k.min_usd) AS esik_karsilandi,
    GREATEST((k.min_usd - t.toplam_usd), (0)::numeric) AS esige_kalan_usd,
    b.nakit_try AS bugunku_nakit_try,
    GREATEST(round(((t.toplam_usd * k.kur) - b.nakit_try), 2), (0)::numeric) AS nakit_acigi_try,
    kp.nakit_kapisi_tarihi,
    kp.projeksiyon_sonu,
    round(kp.projeksiyon_en_yuksek_nakit, 2) AS projeksiyon_en_yuksek_nakit,
        CASE
            WHEN (kp.nakit_kapisi_tarihi IS NULL) THEN NULL::date
            ELSE GREATEST(GREATEST(CURRENT_DATE, t.en_erken_son_siparis), kp.nakit_kapisi_tarihi)
        END AS tavsiye_siparis_tarihi,
        CASE
            WHEN (kp.nakit_kapisi_tarihi IS NULL) THEN NULL::date
            ELSE (GREATEST(GREATEST(CURRENT_DATE, t.en_erken_son_siparis), kp.nakit_kapisi_tarihi) + t.termin_gun)
        END AS tahmini_varis,
        CASE
            WHEN (t.toplam_usd < k.min_usd) THEN 'ESIK_ALTI'::text
            WHEN (kp.nakit_kapisi_tarihi IS NULL) THEN 'KAPI_KAPALI'::text
            WHEN (kp.nakit_kapisi_tarihi > CURRENT_DATE) THEN 'NAKIT_BEKLIYOR'::text
            WHEN (t.en_erken_son_siparis < CURRENT_DATE) THEN 'GECIKMIS'::text
            ELSE 'HAZIR'::text
        END AS durum,
    t.aylik_ciro_usd,
    t.aylik_risk_kar_try,
    k.hedef_ciro_usd
   FROM ((((toplam t
     CROSS JOIN kural k)
     CROSS JOIN bugun b)
     JOIN kapi kp ON ((kp.mod = t.mod)))
     LEFT JOIN disarida d ON ((d.mod = t.mod)));

CREATE OR REPLACE VIEW public.cfo_olu_stok_ozet AS
 SELECT count(*) AS toplam_sku,
    count(*) FILTER (WHERE (alarm = 'KIRMIZI'::text)) AS kirmizi,
    count(*) FILTER (WHERE (alarm = 'SARI'::text)) AS sari,
    round(sum(bagli_sermaye)) AS bagli_sermaye,
    round(sum(bagli_sermaye) FILTER (WHERE (alarm = 'KIRMIZI'::text))) AS kirmizi_bagli,
    count(*) FILTER (WHERE (adet_30g = 0)) AS otuz_gun_sifir,
    count(*) FILTER (WHERE (adet_90g = 0)) AS doksan_gun_sifir,
    round(sum(bagli_sermaye) FILTER (WHERE (adet_90g = 0))) AS doksan_gun_sifir_bagli,
    count(*) FILTER (WHERE kontrol_gecikti) AS kontrol_gecikti,
    count(*) FILTER (WHERE ((adet_30g > 0) AND (COALESCE(ortu_gun, (0)::numeric) <= (180)::numeric))) AS sadece_oran_kurali,
    round(sum(bagli_sermaye) FILTER (WHERE ((adet_30g > 0) AND (COALESCE(ortu_gun, (0)::numeric) <= (180)::numeric)))) AS sadece_oran_bagli,
    count(*) FILTER (WHERE ((adet_30g = 0) AND (xml_30g > 0))) AS xml_kurtardi,
    max(satis_verisi_bayat_gun) AS satis_verisi_bayat_gun
   FROM cfo_olu_stok;

CREATE OR REPLACE VIEW public.cfo_servet AS
 SELECT round(sum(tutar) FILTER (WHERE (tur = 'VARLIK'::text)), 2) AS varlik,
    round((- sum(tutar) FILTER (WHERE (tur = 'BORC'::text))), 2) AS borc,
    round(sum(tutar) FILTER (WHERE (tur = ANY (ARRAY['VARLIK'::text, 'BORC'::text]))), 2) AS servet_try,
    round(sum(tutar) FILTER (WHERE (tur = 'RISKLI'::text)), 2) AS riskli_haric_tutulan,
    round((sum(tutar) FILTER (WHERE (tur <> 'RISKLI'::text)) + sum(tutar) FILTER (WHERE (tur = 'RISKLI'::text))), 2) AS servet_riskli_dahil,
    ( SELECT cfo_snapshot."usdTryRate"
           FROM cfo_snapshot
          ORDER BY cfo_snapshot."takenAt" DESC
         LIMIT 1) AS kur,
    round((sum(tutar) FILTER (WHERE (tur = ANY (ARRAY['VARLIK'::text, 'BORC'::text]))) / ( SELECT cfo_snapshot."usdTryRate"
           FROM cfo_snapshot
          ORDER BY cfo_snapshot."takenAt" DESC
         LIMIT 1)), 2) AS servet_usd
   FROM cfo_servet_kalem;

CREATE OR REPLACE VIEW public.fm_sales_memory_reconciliation_monthly WITH (security_invoker=true) AS
 WITH st AS (
         SELECT (date_trunc('month'::text, (s.economic_date)::timestamp with time zone))::date AS month,
            sum(s.revenue_incl_vat_try) FILTER (WHERE (s.disposition = 'COUNTED'::text)) AS snapshot_revenue,
            sum(s.units_counted) FILTER (WHERE (s.disposition = 'COUNTED'::text)) AS snapshot_units
           FROM fm_sales_canonical_snapshot s
          GROUP BY ((date_trunc('month'::text, (s.economic_date)::timestamp with time zone))::date)
        ), cd AS (
         SELECT (date_trunc('month'::text, (fm_sales_company_day.economic_date)::timestamp with time zone))::date AS month,
            sum(fm_sales_company_day.revenue_incl_vat_try) AS rev,
            sum(fm_sales_company_day.units) AS units
           FROM fm_sales_company_day
          WHERE fm_sales_company_day.is_current
          GROUP BY ((date_trunc('month'::text, (fm_sales_company_day.economic_date)::timestamp with time zone))::date)
        ), cm AS (
         SELECT fm_sales_channel_month.month,
            sum(fm_sales_channel_month.revenue_incl_vat_try) AS rev
           FROM fm_sales_channel_month
          WHERE fm_sales_channel_month.is_current
          GROUP BY fm_sales_channel_month.month
        ), sm AS (
         SELECT fm_sales_sku_month.month,
            sum(fm_sales_sku_month.revenue_incl_vat_try) AS rev
           FROM fm_sales_sku_month
          WHERE fm_sales_sku_month.is_current
          GROUP BY fm_sales_sku_month.month
        )
 SELECT st.month,
    COALESCE(st.snapshot_revenue, (0)::numeric) AS snapshot_revenue_incl_vat_try,
    ((cd.month IS NOT NULL) OR (cm.month IS NOT NULL) OR (sm.month IS NOT NULL)) AS backfilled,
    COALESCE(cd.rev, (0)::numeric) AS company_day_revenue,
    COALESCE(cm.rev, (0)::numeric) AS channel_month_revenue,
    COALESCE(sm.rev, (0)::numeric) AS sku_month_revenue,
    (COALESCE(st.snapshot_revenue, (0)::numeric) - COALESCE(cd.rev, (0)::numeric)) AS diff_company_day,
    (COALESCE(st.snapshot_revenue, (0)::numeric) - COALESCE(cm.rev, (0)::numeric)) AS diff_channel_month,
    (COALESCE(st.snapshot_revenue, (0)::numeric) - COALESCE(sm.rev, (0)::numeric)) AS diff_sku_month,
    (COALESCE(st.snapshot_units, (0)::numeric) - COALESCE(cd.units, (0)::numeric)) AS diff_units
   FROM (((st
     LEFT JOIN cd USING (month))
     LEFT JOIN cm USING (month))
     LEFT JOIN sm USING (month));

CREATE INDEX IF NOT EXISTS "CatalogProductInterest_product_idx" ON public."CatalogProductInterest" USING btree ("productId");

CREATE INDEX IF NOT EXISTS "CatalogProductInterest_share_idx" ON public."CatalogProductInterest" USING btree ("catalogShareId");

CREATE INDEX IF NOT EXISTS "CatalogProfile_enabled_idx" ON public."CatalogProfile" USING btree (enabled);

