    ('fm_stock_sku_day', 'cfo_acceptance_reader_select', 'CREATE POLICY cfo_acceptance_reader_select ON public.fm_stock_sku_day AS PERMISSIVE FOR SELECT TO cfo_acceptance_reader USING (true)'),
    ('trendyol_finance_import', 'cfo_acceptance_reader_select', 'CREATE POLICY cfo_acceptance_reader_select ON public.trendyol_finance_import AS PERMISSIVE FOR SELECT TO cfo_acceptance_reader USING (true)'),
    ('trendyol_invoice', 'cfo_acceptance_reader_select', 'CREATE POLICY cfo_acceptance_reader_select ON public.trendyol_invoice AS PERMISSIVE FOR SELECT TO cfo_acceptance_reader USING (true)'),
    ('trendyol_invoice_line', 'cfo_acceptance_reader_select', 'CREATE POLICY cfo_acceptance_reader_select ON public.trendyol_invoice_line AS PERMISSIVE FOR SELECT TO cfo_acceptance_reader USING (true)'),
    ('trendyol_settlement_line', 'cfo_acceptance_reader_select', 'CREATE POLICY cfo_acceptance_reader_select ON public.trendyol_settlement_line AS PERMISSIVE FOR SELECT TO cfo_acceptance_reader USING (true)')
  ) v(t, n, d) LOOP
    IF NOT EXISTS (SELECT 1 FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = r.t AND p.policyname = r.n) THEN EXECUTE r.d; END IF;
  END LOOP;
END $pol$;

